import { clamp } from './tree.js';

const AUDIO_FILES = {
  trunk: 'assets/audio/trunk.mp3',
  branch: 'assets/audio/branch.mp3',
  leaf: 'assets/audio/leaf.mp3',
  ambientRain: 'assets/audio/ambient-rain.mp3',
  ambientNight: 'assets/audio/ambient-night.mp3',
};

const AUDIO_LABELS = {
  trunk: 'trunk.mp3',
  branch: 'branch.mp3',
  leaf: 'leaf.mp3',
  ambientRain: 'ambient-rain.mp3',
  ambientNight: 'ambient-night.mp3',
};

// C major pentatonic scale across 2 octaves (semitones 0, 2, 4, 7, 9)
const PENTATONIC_TWO_OCTAVES = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24];

const BPM = 70;
const BEAT_SECONDS = 60 / BPM;
const GRID_STEP_SECONDS = BEAT_SECONDS / 4; // 16th-note grid (~0.214s at 70 BPM)
const MIN_NOTE_GAP_SECONDS = 0.14;
const MAX_SIMULTANEOUS_NOTES = 8;

/**
 * Compute playbackRate from semitone offset.
 * @param {number} semitones
 * @returns {number}
 */
export function semitonesToPlaybackRate(semitones) {
  return Math.pow(2, semitones / 12);
}

/**
 * Compute C major pentatonic semitone offset (limited to 2 octaves: 0..24)
 * so deeper branches strictly play higher or equal notes.
 * @param {number} depth Branch depth (>= 2 for normal branches)
 * @param {number} maxDepth Maximum tree depth (1..10)
 * @param {string} side 'left' | 'right' | 'trunk'
 * @returns {number}
 */
export function getBranchPentatonicSemitones(depth, maxDepth, side) {
  if (depth <= 1 || maxDepth <= 2) {
    return 0;
  }

  const normalLevels = Math.max(1, maxDepth - 2);
  // When there are <= 5 normal depth levels (maxDepth <= 7), assign each depth
  // a disjoint 2-note zone so left/right vary melodically while deeper depths
  // remain strictly higher in pitch.
  if (normalLevels <= 5) {
    const baseIndex = (depth - 2) * 2;
    const sideShift = side === 'right' ? 1 : 0;
    const idx = clamp(baseIndex + sideShift, 0, PENTATONIC_TWO_OCTAVES.length - 1);
    return PENTATONIC_TWO_OCTAVES[idx];
  }

  const ratio = clamp((depth - 2) / (normalLevels - 1), 0, 1);
  const idx = clamp(
    Math.round(ratio * (PENTATONIC_TWO_OCTAVES.length - 1)),
    0,
    PENTATONIC_TWO_OCTAVES.length - 1
  );
  return PENTATONIC_TWO_OCTAVES[idx];
}

/**
 * Scan decoded PCM channel data to skip pure leading silence while keeping
 * natural attack transients intact.
 * @param {AudioBuffer} buffer
 * @returns {number} Offset in seconds
 */
function findActiveStartOffset(buffer) {
  if (!buffer || buffer.length === 0) return 0;
  const data = buffer.getChannelData(0);
  const sampleRate = buffer.sampleRate || 44100;
  const windowSize = Math.max(256, Math.floor(sampleRate * 0.02));
  const maxScanSamples = Math.min(data.length, Math.floor(sampleRate * 8));

  for (let i = 0; i < maxScanSamples; i += windowSize) {
    let peak = 0;
    const end = Math.min(data.length, i + windowSize);
    for (let j = i; j < end; j++) {
      const abs = Math.abs(data[j]);
      if (abs > peak) peak = abs;
    }
    if (peak >= 0.02) {
      return Math.max(0, i / sampleRate - 0.02);
    }
  }
  return 0;
}

/**
 * Generate a warm, gentle stereo algorithmic impulse response for the ConvolverNode.
 * @param {BaseAudioContext} ctx
 * @param {number} durationSeconds
 * @returns {AudioBuffer}
 */
function createGentleReverbImpulse(ctx, durationSeconds = 2.2) {
  const sampleRate = ctx.sampleRate;
  const length = Math.floor(sampleRate * durationSeconds);
  const impulse = ctx.createBuffer(2, length, sampleRate);

  for (let ch = 0; ch < 2; ch++) {
    const channel = impulse.getChannelData(ch);
    let lp = 0;
    for (let i = 0; i < length; i++) {
      const t = i / length;
      // Soft attack envelope + smooth exponential decay
      const attack = Math.min(1, i / (sampleRate * 0.025));
      const decay = Math.pow(1 - t, 2.8);
      const white = Math.random() * 2 - 1;
      // Gentle single-pole low-pass so tail feels warm rather than harsh
      lp = lp * 0.72 + white * 0.28;
      channel[i] = lp * attack * decay * 0.5;
    }
  }
  return impulse;
}

/**
 * Web Audio API sound engine for Fractal Garden.
 * Handles sample loading, fallback tones, pentatonic branch mapping,
 * stereo panning, reverb/compression, polyphony limiting, 70 BPM quantization,
 * ambient loops, and transport synchronization.
 */
export class GardenAudio {
  /**
   * @param {Object} [callbacks]
   * @param {(info: { ready: boolean, missing: string[], message: string }) => void} [callbacks.onStatusChange]
   */
  constructor(callbacks = {}) {
    this.onStatusChange = callbacks.onStatusChange || (() => {});

    this.ctx = null;
    this.initialized = false;
    this.loadingStarted = false;
    this.isPlayingTree = false;
    this.isPaused = false;

    this.masterVolume = 0.8;
    this.ambientVolume = 0.5;
    this.muted = false;
    this.ambientEnabled = true;

    this.buffers = new Map();
    this.activeOffsets = new Map();
    this.missingFiles = [];

    this.activeNotes = new Set();
    this.gridOrigin = 0;
    this.lastScheduledTime = -Infinity;

    // Web Audio graph nodes (created only on user gesture)
    this.compressor = null;
    this.masterGain = null;
    this.pauseGain = null;
    this.dryBus = null;
    this.wetSend = null;
    this.convolver = null;
    this.wetBus = null;
    this.ambientBus = null;

    this.ambientSources = [];
    this.fallbackNoiseBuffer = null;
  }

  /**
   * Ensure AudioContext is created and resumed inside a user gesture handler.
   * @returns {Promise<boolean>}
   */
  async unlock() {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) {
      this.emitStatus('Web Audio API is unavailable in this browser.');
      return false;
    }

    if (!this.ctx) {
      this.ctx = new AudioCtx();
      this.buildGraph();
      this.initialized = true;
      this.gridOrigin = this.ctx.currentTime;
    }

    if (this.ctx.state === 'suspended' && !this.isPaused) {
      try {
        await this.ctx.resume();
      } catch {
        // Ignore resume failure if gesture context expired
      }
    }

    if (!this.loadingStarted) {
      this.loadingStarted = true;
      this.loadAllAssets();
    }

    return true;
  }

  /**
   * Construct master compressor, reverb send/return, dry bus, and ambient bus.
   */
  buildGraph() {
    const ctx = this.ctx;

    this.compressor = ctx.createDynamicsCompressor();
    this.compressor.threshold.setValueAtTime(-18, ctx.currentTime);
    this.compressor.knee.setValueAtTime(24, ctx.currentTime);
    this.compressor.ratio.setValueAtTime(3, ctx.currentTime);
    this.compressor.attack.setValueAtTime(0.015, ctx.currentTime);
    this.compressor.release.setValueAtTime(0.25, ctx.currentTime);

    this.pauseGain = ctx.createGain();
    this.pauseGain.gain.setValueAtTime(1, ctx.currentTime);

    this.masterGain = ctx.createGain();
    this.masterGain.gain.setValueAtTime(this.muted ? 0 : this.masterVolume, ctx.currentTime);

    this.dryBus = ctx.createGain();
    this.dryBus.gain.setValueAtTime(0.8, ctx.currentTime);

    this.wetSend = ctx.createGain();
    this.wetSend.gain.setValueAtTime(0.32, ctx.currentTime);

    this.convolver = ctx.createConvolver();
    this.convolver.buffer = createGentleReverbImpulse(ctx, 2.2);

    this.wetBus = ctx.createGain();
    this.wetBus.gain.setValueAtTime(0.38, ctx.currentTime);

    this.ambientBus = ctx.createGain();
    this.ambientBus.gain.setValueAtTime(0, ctx.currentTime);

    // Routing
    this.dryBus.connect(this.compressor);
    this.wetSend.connect(this.convolver);
    this.convolver.connect(this.wetBus);
    this.wetBus.connect(this.compressor);
    this.ambientBus.connect(this.compressor);

    this.compressor.connect(this.pauseGain);
    this.pauseGain.connect(this.masterGain);
    this.masterGain.connect(ctx.destination);
  }

  /**
   * Fetch and decode all required audio files asynchronously.
   * Missing or unreadable files are caught cleanly and replaced with soft synth fallbacks.
   */
  async loadAllAssets() {
    const entries = Object.entries(AUDIO_FILES);
    const missing = [];

    await Promise.all(
      entries.map(async ([key, url]) => {
        try {
          const response = await fetch(url);
          if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
          }
          const arrayBuffer = await response.arrayBuffer();
          const decoded = await this.ctx.decodeAudioData(arrayBuffer);
          this.buffers.set(key, decoded);
          if (key === 'trunk' || key === 'branch' || key === 'leaf') {
            this.activeOffsets.set(key, findActiveStartOffset(decoded));
          }
        } catch {
          missing.push(AUDIO_LABELS[key]);
        }
      })
    );

    this.missingFiles = missing;

    if (this.ambientEnabled && !this.isPaused && (this.isPlayingTree || this.ambientSources.length === 0)) {
      this.startAmbient();
    }

    if (missing.length > 0) {
      this.emitStatus(
        `Missing or unreadable audio file(s): ${missing.join(', ')} — using soft synthesized fallback.`
      );
    } else {
      this.emitStatus('Audio active · C major pentatonic (70 BPM)');
    }
  }

  /**
   * Emit status text and missing-file details to UI.
   * @param {string} message
   */
  emitStatus(message) {
    this.onStatusChange({
      ready: this.initialized,
      missing: [...this.missingFiles],
      message,
    });
  }

  /**
   * Synchronize audio transport when tree growth starts/restarts.
   */
  async startGrowth() {
    const ok = await this.unlock();
    if (!ok) return;

    this.isPlayingTree = true;
    this.isPaused = false;
    this.stopAllNotes(0.04);

    const now = this.ctx.currentTime;
    this.gridOrigin = now;
    this.lastScheduledTime = -Infinity;

    if (this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }
    this.pauseGain.gain.cancelScheduledValues(now);
    this.pauseGain.gain.setValueAtTime(this.pauseGain.gain.value, now);
    this.pauseGain.gain.linearRampToValueAtTime(1, now + 0.08);

    if (this.ambientEnabled) {
      this.startAmbient();
    }
  }

  /**
   * Pause both active notes and ambient audio smoothly.
   */
  async pause() {
    if (!this.ctx || this.isPaused) return;
    this.isPaused = true;

    const now = this.ctx.currentTime;
    this.stopAllNotes(0.05);

    this.pauseGain.gain.cancelScheduledValues(now);
    this.pauseGain.gain.setValueAtTime(this.pauseGain.gain.value, now);
    this.pauseGain.gain.linearRampToValueAtTime(0, now + 0.08);

    setTimeout(() => {
      if (this.isPaused && this.ctx && this.ctx.state === 'running') {
        this.ctx.suspend().catch(() => {});
      }
    }, 100);
  }

  /**
   * Resume audio smoothly alongside tree animation.
   */
  async resume() {
    if (!this.ctx || !this.isPaused) return;
    this.isPaused = false;

    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch {
        return;
      }
    }

    const now = this.ctx.currentTime;
    this.gridOrigin = now;
    this.lastScheduledTime = -Infinity;

    this.pauseGain.gain.cancelScheduledValues(now);
    this.pauseGain.gain.setValueAtTime(0, now);
    this.pauseGain.gain.linearRampToValueAtTime(1, now + 0.14);

    if (this.ambientEnabled) {
      this.startAmbient();
    }
  }

  /**
   * Reset audio: fade out active notes and ambient layers cleanly.
   */
  reset() {
    this.isPlayingTree = false;
    this.isPaused = false;

    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    this.lastScheduledTime = -Infinity;
    this.stopAllNotes(0.06);
    this.stopAmbient(0.5);

    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
    this.pauseGain.gain.cancelScheduledValues(now);
    this.pauseGain.gain.setValueAtTime(this.pauseGain.gain.value, now);
    this.pauseGain.gain.linearRampToValueAtTime(1, now + 0.06);
  }

  /**
   * Set master volume [0, 1].
   * @param {number} value
   */
  setMasterVolume(value) {
    this.masterVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.masterGain) return;
    const now = this.ctx.currentTime;
    const target = this.muted ? 0 : this.masterVolume;
    this.masterGain.gain.cancelScheduledValues(now);
    this.masterGain.gain.setTargetAtTime(target, now, 0.03);
  }

  /**
   * Set ambient volume [0, 1].
   * @param {number} value
   */
  setAmbientVolume(value) {
    this.ambientVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.ambientBus) return;
    const now = this.ctx.currentTime;
    const target = this.ambientEnabled ? this.ambientVolume * 0.28 : 0;
    this.ambientBus.gain.cancelScheduledValues(now);
    this.ambientBus.gain.setTargetAtTime(target, now, 0.08);
  }

  /**
   * Toggle or set mute state.
   * @param {boolean} muted
   */
  setMuted(muted) {
    this.muted = Boolean(muted);
    if (!this.ctx || !this.masterGain) return;
    const now = this.ctx.currentTime;
    const target = this.muted ? 0 : this.masterVolume;
    this.masterGain.gain.cancelScheduledValues(now);
    this.masterGain.gain.setTargetAtTime(target, now, 0.03);
  }

  /**
   * Toggle ambient rain/night loops on or off with smooth fade in / fade out.
   * @param {boolean} enabled
   */
  async setAmbientEnabled(enabled) {
    this.ambientEnabled = Boolean(enabled);
    if (!this.ctx) {
      if (this.ambientEnabled) {
        await this.unlock();
      }
      return;
    }

    if (this.ambientEnabled && !this.isPaused) {
      this.startAmbient();
    } else {
      this.stopAmbient(0.75);
    }
  }

  /**
   * Start ambient rain and night loops quietly with a gentle fade-in.
   */
  startAmbient() {
    if (!this.ctx || !this.ambientBus || !this.ambientEnabled || this.isPaused) return;

    const now = this.ctx.currentTime;
    const targetGain = this.ambientVolume * 0.28;

    // If ambient sources are already active, smoothly fade bus back in
    if (this.ambientSources.length > 0) {
      this.ambientBus.gain.cancelScheduledValues(now);
      this.ambientBus.gain.setValueAtTime(this.ambientBus.gain.value, now);
      this.ambientBus.gain.linearRampToValueAtTime(targetGain, now + 1.2);
      return;
    }

    const layers = [
      { key: 'ambientRain', layerGain: 0.45, fallbackFreq: 130.81, isNoise: true },
      { key: 'ambientNight', layerGain: 0.55, fallbackFreq: 196.0, isNoise: false },
    ];

    let createdAny = false;

    for (const layer of layers) {
      const buffer = this.buffers.get(layer.key);
      if (buffer) {
        const src = this.ctx.createBufferSource();
        src.buffer = buffer;
        src.loop = true;

        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(layer.layerGain, now);
        src.connect(gain);
        gain.connect(this.ambientBus);
        src.start(now);

        this.ambientSources.push({ src, gain });
        createdAny = true;
      } else if (this.missingFiles.includes(AUDIO_LABELS[layer.key])) {
        const fallback = this.createAmbientFallbackNode(layer.isNoise, layer.fallbackFreq, layer.layerGain, now);
        if (fallback) {
          this.ambientSources.push(fallback);
          createdAny = true;
        }
      }
    }

    if (createdAny) {
      this.ambientBus.gain.cancelScheduledValues(now);
      this.ambientBus.gain.setValueAtTime(0, now);
      this.ambientBus.gain.linearRampToValueAtTime(targetGain, now + 1.5);
    }
  }

  /**
   * Fade out and stop looping ambient audio cleanly.
   * @param {number} fadeSeconds
   */
  stopAmbient(fadeSeconds = 0.75) {
    if (!this.ctx || !this.ambientBus) return;
    const now = this.ctx.currentTime;

    this.ambientBus.gain.cancelScheduledValues(now);
    this.ambientBus.gain.setValueAtTime(this.ambientBus.gain.value, now);
    this.ambientBus.gain.linearRampToValueAtTime(0, now + fadeSeconds);

    const sourcesToStop = [...this.ambientSources];
    this.ambientSources = [];

    for (const item of sourcesToStop) {
      try {
        item.src.stop(now + fadeSeconds + 0.05);
      } catch {
        // Ignore if already stopped
      }
    }
  }

  /**
   * Create a soft synthesized ambient fallback loop (filtered rain noise or night drone).
   */
  createAmbientFallbackNode(isNoise, freq, layerGain, now) {
    const ctx = this.ctx;
    if (isNoise) {
      if (!this.fallbackNoiseBuffer) {
        const len = ctx.sampleRate * 2;
        const buf = ctx.createBuffer(1, len, ctx.sampleRate);
        const data = buf.getChannelData(0);
        let lastOut = 0;
        for (let i = 0; i < len; i++) {
          const white = Math.random() * 2 - 1;
          lastOut = (lastOut + 0.03 * white) / 1.03;
          data[i] = lastOut * 2.2;
        }
        this.fallbackNoiseBuffer = buf;
      }
      const src = ctx.createBufferSource();
      src.buffer = this.fallbackNoiseBuffer;
      src.loop = true;

      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(650, now);

      const gain = ctx.createGain();
      gain.gain.setValueAtTime(layerGain * 0.45, now);

      src.connect(filter);
      filter.connect(gain);
      gain.connect(this.ambientBus);
      src.start(now);
      return { src, gain };
    }

    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, now);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(layerGain * 0.12, now);

    osc.connect(gain);
    gain.connect(this.ambientBus);
    osc.start(now);
    return { src: osc, gain };
  }

  /**
   * Prune expired notes from activeVoices tracking.
   * @param {number} now
   */
  pruneActiveNotes(now) {
    for (const note of this.activeNotes) {
      if (now >= note.endTime) {
        this.activeNotes.delete(note);
      }
    }
  }

  /**
   * Stop and fade out all active branch/trunk/leaf notes cleanly without clicks.
   * @param {number} fadeSeconds
   */
  stopAllNotes(fadeSeconds = 0.04) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    for (const note of this.activeNotes) {
      try {
        note.gainNode.gain.cancelScheduledValues(now);
        note.gainNode.gain.setValueAtTime(note.gainNode.gain.value, now);
        note.gainNode.gain.linearRampToValueAtTime(0, now + fadeSeconds);
        note.source.stop(now + fadeSeconds + 0.02);
      } catch {
        // Already stopped
      }
    }
    this.activeNotes.clear();
  }

  /**
   * Play the mapped sound for a branch event when it begins growing,
   * quantized to the 70 BPM grid and capped at 8 simultaneous notes.
   * @param {Object} branch
   * @param {{ minX: number, maxX: number }} bounds
   * @param {number} maxDepth
   */
  playBranchEvent(branch, bounds, maxDepth) {
    if (!this.ctx || !this.initialized || this.isPaused || this.ctx.state !== 'running') {
      return;
    }

    const now = this.ctx.currentTime;
    this.pruneActiveNotes(now);

    if (this.activeNotes.size >= MAX_SIMULTANEOUS_NOTES) {
      return;
    }

    // Quantize start time onto a slow ~70 BPM musical grid (16th-note subdivisions)
    const isTrunk = branch.side === 'trunk' && branch.depth === 1;
    let scheduledTime = now;

    if (!isTrunk) {
      const stepsAhead = Math.max(0, Math.ceil((now - this.gridOrigin) / GRID_STEP_SECONDS));
      let quantized = this.gridOrigin + stepsAhead * GRID_STEP_SECONDS;

      if (quantized - this.lastScheduledTime < MIN_NOTE_GAP_SECONDS) {
        // Allow at most a single grid-step stagger so twin left/right branches
        // arpeggiate cleanly without queueing a long backlog at high depth.
        const nextSlot = quantized + GRID_STEP_SECONDS;
        if (
          nextSlot - this.lastScheduledTime >= MIN_NOTE_GAP_SECONDS &&
          nextSlot - now <= GRID_STEP_SECONDS * 1.6
        ) {
          quantized = nextSlot;
        } else {
          return;
        }
      }
      scheduledTime = Math.max(now + 0.005, quantized);
    }

    this.lastScheduledTime = scheduledTime;

    // Determine sound category, pitch, panning, and depth-scaled gain
    let key = 'branch';
    let playbackRate = 1;
    let baseGain = 0.3;
    let noteDuration = 0.95;
    let attack = 0.035;
    let release = 0.45;
    let fallbackFreq = 261.63; // C4

    if (isTrunk) {
      key = 'trunk';
      playbackRate = 1;
      baseGain = 0.4;
      noteDuration = 1.45;
      attack = 0.06;
      release = 0.55;
      fallbackFreq = 130.81; // C3
    } else if (branch.isLeaf) {
      key = 'leaf';
      playbackRate = 1;
      baseGain = 0.085 * Math.pow(0.92, Math.max(0, branch.depth - 1));
      noteDuration = 0.85;
      attack = 0.05;
      release = 0.48;
      fallbackFreq = 1046.5; // C6 soft chime
    } else {
      key = 'branch';
      const semitones = getBranchPentatonicSemitones(branch.depth, maxDepth, branch.side);
      playbackRate = semitonesToPlaybackRate(semitones);
      baseGain = 0.3 * Math.pow(0.84, Math.max(0, branch.depth - 2));
      noteDuration = 0.95;
      attack = 0.035;
      release = 0.45;
      fallbackFreq = 261.63 * playbackRate;
    }

    // Stereo panning based on branch horizontal x position
    const halfSpan = Math.max(20, Math.abs(bounds.minX), Math.abs(bounds.maxX));
    const pan = isTrunk ? 0 : clamp(branch.endX / halfSpan, -0.85, 0.85);

    const buffer = this.buffers.get(key);
    if (buffer) {
