import { getBranchPentatonicSemitones, semitonesToPlaybackRate } from './js/audio.js';

const validMod12 = new Set([0, 2, 4, 7, 9]);
for (const maxDepth of [1, 3, 5, 7, 10]) {
  let prevMax = -1;
  for (let d = 2; d < maxDepth; d++) {
    const leftSt = getBranchPentatonicSemitones(d, maxDepth, 'left');
    const rightSt = getBranchPentatonicSemitones(d, maxDepth, 'right');
    for (const st of [leftSt, rightSt]) {
      if (st < 0 || st > 24) throw new Error('Out of 2-octave range: ' + st);
      if (!validMod12.has(st % 12)) throw new Error('Not C major pentatonic: ' + st);
      const rate = semitonesToPlaybackRate(st);
      if (rate < 1 || rate > 4) throw new Error('Bad playbackRate: ' + rate);
    }
    if (leftSt < prevMax) throw new Error('Pitch decreased at depth ' + d + ' maxDepth ' + maxDepth);
    prevMax = Math.max(leftSt, rightSt);
  }
}
