import { GardenAudio } from './js/audio.js';
import { generateFractalTree, getTreeBounds } from './js/tree.js';

// Mock Web Audio API + fetch + window for pure logic verification of GardenAudio
let fakeTime = 10.0;
const createdSources = [];
const createdOscs = [];

class FakeParam {
  constructor(val = 0) { this.value = val; this.events = []; }
  setValueAtTime(v, t) { this.value = v; this.events.push(['set', v, t]); }
  linearRampToValueAtTime(v, t) { this.value = v; this.events.push(['lin', v, t]); }
  setTargetAtTime(v, t, tc) { this.value = v; this.events.push(['tgt', v, t, tc]); }
  cancelScheduledValues(t) { this.events.push(['cancel', t]); }
}
class FakeNode { connect() { return this; } }
class FakeGain extends FakeNode { constructor() { super(); this.gain = new FakeParam(1); } }
class FakePanner extends FakeNode { constructor() { super(); this.pan = new FakeParam(0); } }
class FakeComp extends FakeNode {
  constructor() {
    super();
    this.threshold = new FakeParam(-24); this.knee = new FakeParam(30);
    this.ratio = new FakeParam(12); this.attack = new FakeParam(0.003); this.release = new FakeParam(0.25);
  }
}
class FakeConv extends FakeNode { constructor() { super(); this.buffer = null; } }
class FakeFilter extends FakeNode { constructor() { super(); this.type = 'lowpass'; this.frequency = new FakeParam(350); } }
class FakeSource extends FakeNode {
  constructor() {
    super(); this.buffer = null; this.loop = false; this.playbackRate = new FakeParam(1);
    this.startedAt = null; this.stoppedAt = null; this.offset = 0;
  }
  start(w = 0, o = 0) { this.startedAt = w; this.offset = o; createdSources.push(this); }
  stop(w = 0) { this.stoppedAt = w; }
}
class FakeOsc extends FakeNode {
  constructor() {
    super(); this.type = 'sine'; this.frequency = new FakeParam(440);
    this.startedAt = null; this.stoppedAt = null;
  }
  start(w = 0) { this.startedAt = w; createdOscs.push(this); }
  stop(w = 0) { this.stoppedAt = w; }
}
class FakeBuffer {
  constructor(ch, len, sr) { this.numberOfChannels = ch; this.length = len; this.sampleRate = sr; this.duration = len / sr; this._d = [new Float32Array(len).fill(0.1), new Float32Array(len).fill(0.1)]; }
  getChannelData(c) { return this._d[c] || this._d[0]; }
}
class FakeAudioContext {
  constructor() { this.state = 'suspended'; this.sampleRate = 44100; this.destination = {}; }
  get currentTime() { return fakeTime; }
  async resume() { this.state = 'running'; }
  async suspend() { this.state = 'suspended'; }
  createGain() { return new FakeGain(); }
  createStereoPanner() { return new FakePanner(); }
  createDynamicsCompressor() { return new FakeComp(); }
  createConvolver() { return new FakeConv(); }
  createBiquadFilter() { return new FakeFilter(); }
  createBufferSource() { return new FakeSource(); }
  createOscillator() { return new FakeOsc(); }
  createBuffer(c, l, sr) { return new FakeBuffer(c, l, sr); }
  async decodeAudioData() { return new FakeBuffer(2, 44100 * 5, 44100); }
}

globalThis.window = { AudioContext: FakeAudioContext };

// 1. Test full asset load across depth 1, 7, 10
const fetchedUrls = [];
globalThis.fetch = async (url) => {
  fetchedUrls.push(url);
  return { ok: true, status: 200, arrayBuffer: async () => new ArrayBuffer(8) };
};

const statuses = [];
const audio = new GardenAudio({ onStatusChange: (s) => statuses.push(s) });
if (audio.initialized || fetchedUrls.length !== 0) throw new Error('Audio initialized before user click!');

await audio.startGrowth();
if (!audio.initialized || fetchedUrls.length !== 5) throw new Error('Expected 5 audio fetches after click');
await new Promise(r => setTimeout(r, 20));
if (statuses[statuses.length - 1].missing.length !== 0) throw new Error('Unexpected missing files');

// Test Depth 1, 7, 10 scheduling invariants
for (const depth of [1, 7, 10]) {
  createdSources.length = 0;
  await audio.startGrowth();
  const events = generateFractalTree({ depth, branchAngle: 25, lengthRatio: 0.72, randomness: 0.2, seed: 4217 });
  const bounds = getTreeBounds(events);
  for (const branch of events) {
    fakeTime = 10.0 + branch.startTime;
    audio.playBranchEvent(branch, bounds, depth);
    if (audio.activeNotes.size > 8) throw new Error('Exceeded 8 active notes at depth ' + depth);
  }
  const noteSources = createdSources.filter(s => !s.loop);
  if (noteSources.length === 0) throw new Error('No notes scheduled at depth ' + depth);
  // Check min gap between scheduled starts
  for (let i = 1; i < noteSources.length; i++) {
    const gap = noteSources[i].startedAt - noteSources[i - 1].startedAt;
    if (gap < 0.139) throw new Error('Min gap violated: ' + gap);
  }
  console.log('depth=' + depth, 'events=' + events.length, 'scheduledNotes=' + noteSources.length, 'maxSimultaneous<=8 OK');
}

// Test Pause / Resume / Reset + Mute / Ambient controls
await audio.pause();
if (!audio.isPaused) throw new Error('Pause failed');
await audio.resume();
if (audio.isPaused) throw new Error('Resume failed');
audio.setMuted(true);
audio.setMasterVolume(0.5);
audio.setAmbientVolume(0.3);
await audio.setAmbientEnabled(false);
await audio.setAmbientEnabled(true);
audio.reset();

// 2. Test missing file fallback + warning status
createdOscs.length = 0;
const missStatuses = [];
globalThis.fetch = async (url) => ({ ok: false, status: 404, arrayBuffer: async () => new ArrayBuffer(0) });
const audioMissing = new GardenAudio({ onStatusChange: (s) => missStatuses.push(s) });
await audioMissing.startGrowth();
await new Promise(r => setTimeout(r, 20));
const lastMiss = missStatuses[missStatuses.length - 1];
if (lastMiss.missing.length !== 5 || !lastMiss.message.includes('trunk.mp3')) {
  throw new Error('Missing file message not emitted properly: ' + JSON.stringify(lastMiss));
}
const ev7 = generateFractalTree({ depth: 7, seed: 4217 });
const b7 = getTreeBounds(ev7);
fakeTime = 20.0;
audioMissing.playBranchEvent(ev7[0], b7, 7);
if (createdOscs.length === 0) throw new Error('Synth fallback oscillator was not triggered');
console.log('Missing-file fallback & warning verified:', lastMiss.message);
"

