import { clamp } from './tree.js';

const AUDIO_FILES = {
  trunk: 'assets/audio/trunk.mp3',
  branch: 'assets/audio/branch.mp3',
  leaf: 'assets/audio/leaf.mp3',
  ambientRain: 'assets/audio/ambient-rain.mp3',
  ambientNight: 'assets/audio/ambient-night.mp3',
};

const AUDIO_LABELS = {
  trunk: 'trunk.mp3',
  branch: 'branch.mp3',
  leaf: 'leaf.mp3',
  ambientRain: 'ambient-rain.mp3',
  ambientNight: 'ambient-night.mp3',
};

export const SCALES = {
  'c-major': {
    label: 'C major pentatonic (Calm)',
    // C4, D4, E4, G4, A4, C5, D5, E5, G5, A5, C6
    semitones: [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24],
    trunkFreq: 130.81, // C3
    refFreq: 261.63,   // C4
    leafFreq: 1046.5,  // C6
  },
  'a-minor': {
    label: 'A minor pentatonic (Dreamy)',
    // A3, C4, D4, E4, G4, A4, C5, D5, E5, G5, A5
    semitones: [-3, 0, 2, 4, 7, 9, 12, 14, 16, 19, 21],
    trunkFreq: 110.0,  // A2
    refFreq: 261.63,   // C4 reference for semitone ratios
    leafFreq: 880.0,   // A5
  },
};

const MAX_SIMULTANEOUS_NOTES = 8;

/**
 * Compute playbackRate from semitone offset.
 * @param {number} semitones
 * @returns {number}
 */
export function semitonesToPlaybackRate(semitones) {
  return Math.pow(2, semitones / 12);
}

/**
 * Compute pentatonic semitone offset (limited to 2 octaves) so deeper branches
 * play higher or equal notes in the selected scale.
 * @param {number} depth Branch depth (>= 2 for normal branches)
 * @param {number} maxDepth Maximum tree depth (1..10)
 * @param {string} side 'left' | 'right' | 'trunk'
 * @param {string} [scaleId='c-major']
 * @returns {number}
 */
export function getBranchPentatonicSemitones(depth, maxDepth, side, scaleId = 'c-major') {
  const scale = SCALES[scaleId] || SCALES['c-major'];
  const ladder = scale.semitones;

  if (depth <= 1 || maxDepth <= 2) {
    return ladder[0];
  }

  const normalLevels = Math.max(1, maxDepth - 2);
  if (normalLevels <= 5) {
    const baseIndex = (depth - 2) * 2;
    const sideShift = side === 'right' ? 1 : 0;
    const idx = clamp(baseIndex + sideShift, 0, ladder.length - 1);
    return ladder[idx];
  }

  const ratio = clamp((depth - 2) / (normalLevels - 1), 0, 1);
  const idx = clamp(
    Math.round(ratio * (ladder.length - 1)),
    0,
    ladder.length - 1
  );
  return ladder[idx];
}

/**
 * Scan decoded PCM channel data to skip leading silence while preserving transients.
 * @param {AudioBuffer} buffer
 * @returns {number} Offset in seconds
 */
function findActiveStartOffset(buffer) {
  if (!buffer || buffer.length === 0) return 0;
  const data = buffer.getChannelData(0);
  const sampleRate = buffer.sampleRate || 44100;
  const windowSize = Math.max(256, Math.floor(sampleRate * 0.02));
  const maxScanSamples = Math.min(data.length, Math.floor(sampleRate * 8));

  for (let i = 0; i < maxScanSamples; i += windowSize) {
    let peak = 0;
    const end = Math.min(data.length, i + windowSize);
    for (let j = i; j < end; j++) {
      const abs = Math.abs(data[j]);
      if (abs > peak) peak = abs;
    }
    if (peak >= 0.02) {
      return Math.max(0, i / sampleRate - 0.02);
    }
  }
  return 0;
}

/**
 * Generate a warm, gentle stereo algorithmic impulse response for the ConvolverNode.
 * @param {BaseAudioContext} ctx
 * @param {number} durationSeconds
 * @returns {AudioBuffer}
 */
function createGentleReverbImpulse(ctx, durationSeconds = 2.2) {
  const sampleRate = ctx.sampleRate;
  const length = Math.floor(sampleRate * durationSeconds);
  const impulse = ctx.createBuffer(2, length, sampleRate);

  for (let ch = 0; ch < 2; ch++) {
    const channel = impulse.getChannelData(ch);
    let lp = 0;
    for (let i = 0; i < length; i++) {
      const t = i / length;
      const attack = Math.min(1, i / (sampleRate * 0.025));
      const decay = Math.pow(1 - t, 2.8);
      const white = Math.random() * 2 - 1;
      lp = lp * 0.72 + white * 0.28;
      channel[i] = lp * attack * decay * 0.5;
    }
  }
  return impulse;
}

/**
 * Web Audio API sound engine for Fractal Garden.
 * Supports separate Master/Notes/Leaves/Ambient gain buses, live reverb,
 * selectable C major / A minor pentatonic scales, queued tempo (50-90 BPM),
 * Rain/Night/Both/Off ambient modes, mute with volume memory, and safe
 * rapid Play/Pause/Stop/Restart synchronization.
 */
export class GardenAudio {
  /**
   * @param {Object} [callbacks]
   * @param {(info: { ready: boolean, missing: string[], message: string }) => void} [callbacks.onStatusChange]
   */
  constructor(callbacks = {}) {
    this.onStatusChange = callbacks.onStatusChange || (() => {});

    this.ctx = null;
    this.initialized = false;
    this.loadingStarted = false;
    this.isPlayingTree = false;
    this.isPaused = false;
    this.transportEpoch = 0;

    this.masterVolume = 0.8;
    this.preMuteVolume = 0.8;
    this.notesVolume = 0.8;
    this.leavesVolume = 0.7;
    this.ambientVolume = 0.5;
    this.reverbAmount = 0.38;
    this.muted = false;

    this.ambientMode = 'both'; // 'rain' | 'night' | 'both' | 'off'
    this.scale = 'c-major';    // 'c-major' | 'a-minor'
    this.pendingTempo = 70;
    this.activeTempo = 70;

    this.buffers = new Map();
    this.activeOffsets = new Map();
    this.loadingPromises = new Map();
    this.missingFiles = [];
    this.suspendTimer = null;

    this.activeNotes = new Set();
    this.gridOrigin = 0;
    this.lastScheduledTime = -Infinity;

    // Web Audio graph nodes
    this.compressor = null;
    this.masterGain = null;
    this.pauseGain = null;
    this.notesBus = null;
    this.leavesBus = null;
    this.dryBus = null;
    this.wetSend = null;
    this.convolver = null;
    this.wetBus = null;
    this.ambientBus = null;

    this.ambientTracks = null; // { rain: { src, gain }, night: { src, gain } }
    this.fadingAmbient = [];
    this.fallbackNoiseBuffer = null;
  }

  /**
   * Ensure AudioContext is created and resumed inside a user gesture handler.
   * @returns {Promise<boolean>}
   */
  async unlock() {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) {
      this.emitStatus('Web Audio API is unavailable in this browser.');
      return false;
    }

    if (!this.ctx) {
      this.ctx = new AudioCtx();
      this.buildGraph();
      this.initialized = true;
      this.gridOrigin = this.ctx.currentTime;
    }

    if (this.ctx.state === 'suspended' && !this.isPaused) {
      try {
        await this.ctx.resume();
      } catch {
        // Ignore resume rejection if called outside gesture
      }
    }

    if (!this.loadingStarted) {
      this.loadingStarted = true;
      this.loadAllAssets();
    }

    return true;
  }

  /**
   * Construct separated gain buses, reverb send/return, compressor, and master output.
   */
  buildGraph() {
    const ctx = this.ctx;
    const now = ctx.currentTime;

    this.compressor = ctx.createDynamicsCompressor();
    this.compressor.threshold.setValueAtTime(-18, now);
    this.compressor.knee.setValueAtTime(24, now);
    this.compressor.ratio.setValueAtTime(3, now);
    this.compressor.attack.setValueAtTime(0.015, now);
    this.compressor.release.setValueAtTime(0.25, now);

    this.pauseGain = ctx.createGain();
    this.pauseGain.gain.setValueAtTime(1, now);

    this.masterGain = ctx.createGain();
    this.masterGain.gain.setValueAtTime(this.muted ? 0 : this.masterVolume, now);

    this.notesBus = ctx.createGain();
    this.notesBus.gain.setValueAtTime(this.notesVolume, now);

    this.leavesBus = ctx.createGain();
    this.leavesBus.gain.setValueAtTime(this.leavesVolume, now);

    this.dryBus = ctx.createGain();
    this.dryBus.gain.setValueAtTime(0.88 - this.reverbAmount * 0.16, now);

    this.wetSend = ctx.createGain();
    this.wetSend.gain.setValueAtTime(0.65, now);

    this.convolver = ctx.createConvolver();
    this.convolver.buffer = createGentleReverbImpulse(ctx, 2.2);

    this.wetBus = ctx.createGain();
    this.wetBus.gain.setValueAtTime(this.reverbAmount * 0.78, now);

    this.ambientBus = ctx.createGain();
    this.ambientBus.gain.setValueAtTime(this.ambientVolume * 0.3, now);

    // Routing
    this.notesBus.connect(this.dryBus);
    this.notesBus.connect(this.wetSend);
    this.leavesBus.connect(this.dryBus);
    this.leavesBus.connect(this.wetSend);

    this.dryBus.connect(this.compressor);
    this.wetSend.connect(this.convolver);
    this.convolver.connect(this.wetBus);
    this.wetBus.connect(this.compressor);
    this.ambientBus.connect(this.compressor);

    this.compressor.connect(this.pauseGain);
    this.pauseGain.connect(this.masterGain);
    this.masterGain.connect(ctx.destination);
  }

  /**
   * Fetch and decode all required audio files asynchronously.
   */
  async loadAllAssets() {
    const entries = Object.entries(AUDIO_FILES);
    const missing = [];

    await Promise.all(
      entries.map(([key, url]) => {
        const task = (async () => {
          try {
            const response = await fetch(url);
            if (!response.ok) {
              throw new Error(`HTTP ${response.status}`);
            }
            const arrayBuffer = await response.arrayBuffer();
            const decoded = await this.ctx.decodeAudioData(arrayBuffer);
            this.buffers.set(key, decoded);
            if (key === 'trunk' || key === 'branch' || key === 'leaf') {
              this.activeOffsets.set(key, findActiveStartOffset(decoded));
            }
          } catch {
            missing.push(AUDIO_LABELS[key]);
          }
        })();
        this.loadingPromises.set(key, task);
        return task;
      })
    );

    this.missingFiles = missing;

    if (this.isPlayingTree && !this.isPaused && this.ambientMode !== 'off') {
      this.startAmbient();
    }

    if (missing.length > 0) {
      this.emitStatus(
        `Missing or unreadable audio file(s): ${missing.join(', ')} — using soft synthesized fallback.`
      );
    } else {
      this.emitActiveSummary();
    }
  }

  /**
   * Emit concise active status summary.
   */
  emitActiveSummary() {
    if (!this.initialized || this.missingFiles.length > 0) return;
    const scaleName = this.scale === 'a-minor' ? 'A minor' : 'C major';
    this.emitStatus(`Audio ready · ${scaleName} pentatonic · ${this.activeTempo} BPM`);
  }

  /**
   * Emit status text and missing-file details to UI.
   * @param {string} message
   */
  emitStatus(message) {
    this.onStatusChange({
      ready: this.initialized,
      missing: [...this.missingFiles],
      message,
    });
  }

  /**
   * Clear pending suspend timer cleanly.
   */
  clearSuspendTimer() {
    if (this.suspendTimer !== null) {
      clearTimeout(this.suspendTimer);
      this.suspendTimer = null;
    }
  }

  /**
   * Start or restart audio playback from the beginning of a growth cycle.
   * Applies any queued tempo change cleanly.
   * @param {Object} [options]
   * @param {boolean} [options.keepAmbient=false] Keep ambient running seamlessly on loop cycles
   */
  async startGrowth({ keepAmbient = false } = {}) {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();

    // Commit pending tempo when a new play begins
    this.activeTempo = this.pendingTempo;
    this.isPlayingTree = true;
    this.isPaused = false;

    const ok = await this.unlock();
    if (!ok || epoch !== this.transportEpoch) return;

    this.stopAllNotes(0.035);

    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch {
        return;
      }
      if (epoch !== this.transportEpoch) return;
    }

    const now = this.ctx.currentTime;
    this.gridOrigin = now;
    this.lastScheduledTime = -Infinity;

    this.pauseGain.gain.cancelScheduledValues(now);
    this.pauseGain.gain.setValueAtTime(this.pauseGain.gain.value, now);
    this.pauseGain.gain.linearRampToValueAtTime(1, now + 0.06);

    if (this.ambientMode !== 'off') {
      if (!keepAmbient || !this.ambientTracks) {
        this.startAmbient();
      } else {
        this.updateAmbientMix(0.4);
      }
    } else {
      this.stopAmbient(0.35);
    }

    this.emitActiveSummary();
  }

  /**
   * Pause active notes and ambient audio smoothly without clicks.
   */
  async pause() {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();
    if (!this.ctx || !this.isPlayingTree || this.isPaused) return;

    this.isPaused = true;
    const now = this.ctx.currentTime;
    this.stopAllNotes(0.045);

    this.pauseGain.gain.cancelScheduledValues(now);
    this.pauseGain.gain.setValueAtTime(this.pauseGain.gain.value, now);
    this.pauseGain.gain.linearRampToValueAtTime(0, now + 0.08);

    this.suspendTimer = setTimeout(() => {
      this.suspendTimer = null;
      if (epoch === this.transportEpoch && this.isPaused && this.ctx && this.ctx.state === 'running') {
        this.ctx.suspend().catch(() => {});
      }
    }, 105);
  }

  /**
   * Resume audio from paused position smoothly without replaying earlier notes.
   */
  async resume() {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();
    if (!this.ctx || !this.isPlayingTree || !this.isPaused) return;

    this.isPaused = false;

    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch {
        return;
      }
      if (epoch !== this.transportEpoch) return;
    }

    const now = this.ctx.currentTime;
    this.gridOrigin = now;
    this.lastScheduledTime = -Infinity;

    this.pauseGain.gain.cancelScheduledValues(now);
    this.pauseGain.gain.setValueAtTime(this.pauseGain.gain.value, now);
    this.pauseGain.gain.linearRampToValueAtTime(1, now + 0.12);

    if (this.ambientMode !== 'off') {
      this.startAmbient();
    }
  }

  /**
   * Stop all notes and ambient audio with a short fade, resetting playback state.
   */
  stop() {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();
    this.isPlayingTree = false;
    this.isPaused = false;
    this.lastScheduledTime = -Infinity;

    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    this.stopAllNotes(0.055);
    this.stopAmbient(0.4);

    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }

    if (epoch === this.transportEpoch) {
      this.pauseGain.gain.cancelScheduledValues(now);
      this.pauseGain.gain.setValueAtTime(this.pauseGain.gain.value, now);
      this.pauseGain.gain.linearRampToValueAtTime(1, now + 0.06);
    }
  }

  /**
   * Set master volume [0, 1] smoothly without clicks.
   * @param {number} value
   */
  setMasterVolume(value) {
    const v = clamp(Number(value) || 0, 0, 1);
    this.masterVolume = v;
    if (v > 0) {
      this.preMuteVolume = v;
      if (this.muted) {
        this.muted = false;
      }
    }
    if (!this.ctx || !this.masterGain) return;
    const now = this.ctx.currentTime;
    const target = this.muted ? 0 : this.masterVolume;
    this.masterGain.gain.cancelScheduledValues(now);
    this.masterGain.gain.setTargetAtTime(target, now, 0.025);
  }

  /**
   * Set trunk & branch notes volume [0, 1] smoothly.
   * @param {number} value
   */
  setNotesVolume(value) {
    this.notesVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.notesBus) return;
    const now = this.ctx.currentTime;
    this.notesBus.gain.cancelScheduledValues(now);
    this.notesBus.gain.setTargetAtTime(this.notesVolume, now, 0.025);
  }

  /**
   * Set base-case leaf notes volume [0, 1] smoothly.
   * @param {number} value
   */
  setLeavesVolume(value) {
    this.leavesVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.leavesBus) return;
    const now = this.ctx.currentTime;
    this.leavesBus.gain.cancelScheduledValues(now);
    this.leavesBus.gain.setTargetAtTime(this.leavesVolume, now, 0.025);
  }

  /**
   * Set ambient volume [0, 1] smoothly.
   * @param {number} value
   */
  setAmbientVolume(value) {
    this.ambientVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.ambientBus) return;
    const now = this.ctx.currentTime;
    this.ambientBus.gain.cancelScheduledValues(now);
    this.ambientBus.gain.setTargetAtTime(this.ambientVolume * 0.3, now, 0.04);
  }

  /**
   * Set live reverb amount [0, 1] smoothly.
   * @param {number} value
   */
  setReverbAmount(value) {
    this.reverbAmount = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.wetBus || !this.dryBus) return;
    const now = this.ctx.currentTime;
    this.wetBus.gain.cancelScheduledValues(now);
    this.wetBus.gain.setTargetAtTime(this.reverbAmount * 0.78, now, 0.035);
    this.dryBus.gain.cancelScheduledValues(now);
    this.dryBus.gain.setTargetAtTime(0.88 - this.reverbAmount * 0.16, now, 0.035);
  }

  /**
   * Queue tempo (50..90 BPM) to take effect on the next Play or Restart.
   * @param {number} bpm
   */
  setTempo(bpm) {
    this.pendingTempo = Math.round(clamp(Number(bpm) || 70, 50, 90));
  }

  /**
   * Set active scale / mood ('c-major' | 'a-minor').
   * @param {string} scaleId
   */
  setScale(scaleId) {
    this.scale = scaleId === 'a-minor' ? 'a-minor' : 'c-major';
    this.emitActiveSummary();
  }

  /**
   * Toggle or set mute; unmuting restores the saved previous volume.
   * @param {boolean} muted
   * @returns {number} Effective slider volume after change
   */
  setMuted(muted) {
    const nextMuted = Boolean(muted);
    if (nextMuted) {
      if (this.masterVolume > 0) {
        this.preMuteVolume = this.masterVolume;
      }
      this.muted = true;
    } else {
      this.muted = false;
      this.masterVolume = this.preMuteVolume > 0 ? this.preMuteVolume : 0.8;
    }

    if (this.ctx && this.masterGain) {
      const now = this.ctx.currentTime;
      const target = this.muted ? 0 : this.masterVolume;
      this.masterGain.gain.cancelScheduledValues(now);
      this.masterGain.gain.setTargetAtTime(target, now, 0.025);
    }

    return this.muted ? 0 : this.masterVolume;
  }

  /**
   * Set ambient mode ('rain' | 'night' | 'both' | 'off') with smooth crossfading.
   * @param {string} mode
   */
  setAmbientMode(mode) {
    const allowed = ['rain', 'night', 'both', 'off'];
    this.ambientMode = allowed.includes(mode) ? mode : 'both';

    if (!this.ctx || !this.isPlayingTree || this.isPaused) {
      return;
    }

    if (this.ambientMode === 'off') {
      this.stopAmbient(0.5);
    } else if (!this.ambientTracks) {
      this.startAmbient();
    } else {
      this.updateAmbientMix(0.45);
    }
  }

  /**
   * Target gain pair for the selected ambient mode.
   */
  getTargetAmbientMix() {
    switch (this.ambientMode) {
      case 'rain':
        return { rain: 0.72, night: 0 };
      case 'night':
        return { rain: 0, night: 0.78 };
      case 'both':
        return { rain: 0.45, night: 0.55 };
      case 'off':
      default:
        return { rain: 0, night: 0 };
    }
  }

  /**
   * Smoothly adjust Rain & Night layer gains on currently playing ambient loops.
   * @param {number} fadeSeconds
   */
  updateAmbientMix(fadeSeconds = 0.6) {
    if (!this.ctx || !this.ambientTracks) return;
    const now = this.ctx.currentTime;
    const mix = this.getTargetAmbientMix();
    const tc = Math.max(0.05, fadeSeconds / 3);

    if (this.ambientTracks.rain) {
      const g = this.ambientTracks.rain.gain.gain;
      g.cancelScheduledValues(now);
      g.setTargetAtTime(mix.rain, now, tc);
    }
    if (this.ambientTracks.night) {
      const g = this.ambientTracks.night.gain.gain;
      g.cancelScheduledValues(now);
      g.setTargetAtTime(mix.night, now, tc);
    }
  }

  /**
   * Start ambient Rain and Night loops quietly with smooth fade-in.
   */
  startAmbient() {
    if (!this.ctx || !this.ambientBus || this.ambientMode === 'off' || this.isPaused) {
      return;
    }

    // Accelerate cleanup of any previously fading ambient tracks
    const now = this.ctx.currentTime;
    for (const old of this.fadingAmbient) {
      try {
        old.gain.gain.cancelScheduledValues(now);
        old.gain.gain.setValueAtTime(old.gain.gain.value, now);
        old.gain.gain.linearRampToValueAtTime(0, now + 0.04);
        old.src.stop(now + 0.06);
      } catch {
        // Ignore stopped
      }
    }
    this.fadingAmbient = [];

    if (this.ambientTracks) {
      this.updateAmbientMix(0.8);
      return;
    }

    const mix = this.getTargetAmbientMix();
    const layers = [
      { prop: 'rain', key: 'ambientRain', targetGain: mix.rain, freq: 130.81, isNoise: true },
      { prop: 'night', key: 'ambientNight', targetGain: mix.night, freq: 196.0, isNoise: false },
    ];

    const created = { rain: null, night: null };
    let hasAny = false;

    for (const layer of layers) {
      const buffer = this.buffers.get(layer.key);
      if (buffer) {
        const src = this.ctx.createBufferSource();
        src.buffer = buffer;
        src.loop = true;

        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(0, now);
        gain.gain.linearRampToValueAtTime(layer.targetGain, now + 1.4);

        src.connect(gain);
        gain.connect(this.ambientBus);
        src.start(now);

        created[layer.prop] = { src, gain };
        hasAny = true;
      } else if (this.missingFiles.includes(AUDIO_LABELS[layer.key])) {
        const fallback = this.createAmbientFallbackNode(
          layer.isNoise,
          layer.freq,
          layer.targetGain,
          now
        );
        if (fallback) {
          created[layer.prop] = fallback;
          hasAny = true;
        }
      }
    }

    if (hasAny) {
      this.ambientTracks = created;
    }
  }

  /**
   * Fade out and stop looping ambient tracks cleanly.
   * @param {number} fadeSeconds
   */
  stopAmbient(fadeSeconds = 0.5) {
    if (!this.ctx || !this.ambientTracks) return;
    const now = this.ctx.currentTime;
    const tracks = [this.ambientTracks.rain, this.ambientTracks.night].filter(Boolean);
    this.ambientTracks = null;

    for (const item of tracks) {
      try {
        item.gain.gain.cancelScheduledValues(now);
        item.gain.gain.setValueAtTime(item.gain.gain.value, now);
        item.gain.gain.linearRampToValueAtTime(0, now + fadeSeconds);
        item.src.stop(now + fadeSeconds + 0.05);
        this.fadingAmbient.push(item);
      } catch {
        // Ignore already stopped
      }
    }
  }

  /**
   * Soft synthesized ambient fallback if an ambient MP3 is missing.
   */
  createAmbientFallbackNode(isNoise, freq, targetGain, now) {
    const ctx = this.ctx;
    if (isNoise) {
      if (!this.fallbackNoiseBuffer) {
        const len = ctx.sampleRate * 2;
        const buf = ctx.createBuffer(1, len, ctx.sampleRate);
        const data = buf.getChannelData(0);
        let lastOut = 0;
        for (let i = 0; i < len; i++) {
          const white = Math.random() * 2 - 1;
          lastOut = (lastOut + 0.03 * white) / 1.03;
          data[i] = lastOut * 2.2;
        }
        this.fallbackNoiseBuffer = buf;
      }
      const src = ctx.createBufferSource();
      src.buffer = this.fallbackNoiseBuffer;
      src.loop = true;

      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(620, now);

      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(targetGain * 0.4, now + 1.2);

      src.connect(filter);
      filter.connect(gain);
      gain.connect(this.ambientBus);
      src.start(now);
      return { src, gain };
    }

    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, now);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(targetGain * 0.12, now + 1.2);

    osc.connect(gain);
    gain.connect(this.ambientBus);
    osc.start(now);
    return { src: osc, gain };
  }

  /**
   * Remove expired notes from activeNotes tracking.
   * @param {number} now
   */
  pruneActiveNotes(now) {
    for (const note of this.activeNotes) {
      if (now >= note.endTime) {
        this.activeNotes.delete(note);
      }
    }
  }

  /**
   * Fade out and stop all active or queued note voices cleanly without clicks.
   * @param {number} fadeSeconds
   */
  stopAllNotes(fadeSeconds = 0.04) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    for (const note of this.activeNotes) {
      try {
        note.gainNode.gain.cancelScheduledValues(now);
        note.gainNode.gain.setValueAtTime(note.gainNode.gain.value, now);
        note.gainNode.gain.linearRampToValueAtTime(0, now + fadeSeconds);
        note.source.stop(now + fadeSeconds + 0.02);
      } catch {
        // Already stopped
      }
    }
    this.activeNotes.clear();
  }

  /**
   * Play the mapped sound for a branch event when it begins growing,
   * quantized to the active BPM grid and capped at 8 simultaneous notes.
   * @param {Object} branch
   * @param {{ minX: number, maxX: number }} bounds
   * @param {number} maxDepth
   */
  playBranchEvent(branch, bounds, maxDepth) {
    if (
      !this.ctx ||
      !this.initialized ||
      !this.isPlayingTree ||
      this.isPaused ||
      this.ctx.state !== 'running'
    ) {
      return;
    }

    const now = this.ctx.currentTime;
    this.pruneActiveNotes(now);

    if (this.activeNotes.size >= MAX_SIMULTANEOUS_NOTES) {
      return;
    }

    const beatSeconds = 60 / this.activeTempo;
    const gridStep = beatSeconds / 4; // 16th-note musical grid
    const minGap = clamp(beatSeconds * 0.16, 0.1, 0.22);

    const isTrunk = branch.side === 'trunk' && branch.depth === 1;
    let scheduledTime = now;

    if (!isTrunk) {
      const stepsAhead = Math.max(0, Math.ceil((now - this.gridOrigin) / gridStep));
      let quantized = this.gridOrigin + stepsAhead * gridStep;

      if (quantized - this.lastScheduledTime < minGap) {
        const nextSlot = quantized + gridStep;
        if (
          nextSlot - this.lastScheduledTime >= minGap &&
          nextSlot - now <= gridStep * 1.6
        ) {
          quantized = nextSlot;
        } else {
          return;
        }
      }
      scheduledTime = Math.max(now + 0.005, quantized);
    }

    this.lastScheduledTime = scheduledTime;

    const scaleDef = SCALES[this.scale] || SCALES['c-major'];
    let key = 'branch';
    let targetBus = this.notesBus;
    let playbackRate = 1;
    let baseGain = 0.3;
    let noteDuration = 0.8;
    let attack = 0.035;
    let release = 0.35;
    let fallbackFreq = scaleDef.refFreq;

    if (isTrunk) {
      key = 'trunk';
      targetBus = this.notesBus;
      playbackRate = 1;
      baseGain = 0.42;
      noteDuration = 1.25;
      attack = 0.055;
      release = 0.5;
      fallbackFreq = scaleDef.trunkFreq;
    } else if (branch.isLeaf) {
      key = 'leaf';
      targetBus = this.leavesBus;
      playbackRate = 1;
      baseGain = 0.11 * Math.pow(0.92, Math.max(0, branch.depth - 1));
      noteDuration = 0.65;
      attack = 0.045;
      release = 0.36;
      fallbackFreq = scaleDef.leafFreq;
    } else {
      key = 'branch';
      targetBus = this.notesBus;
      const semitones = getBranchPentatonicSemitones(
        branch.depth,
        maxDepth,
        branch.side,
        this.scale
      );
      playbackRate = semitonesToPlaybackRate(semitones);
      baseGain = 0.32 * Math.pow(0.84, Math.max(0, branch.depth - 2));
      noteDuration = Math.max(0.55, 0.85 - Math.max(0, branch.depth - 2) * 0.04);
      attack = 0.035;
      release = 0.35;
      fallbackFreq = scaleDef.refFreq * playbackRate;
    }

    const halfSpan = Math.max(20, Math.abs(bounds.minX), Math.abs(bounds.maxX));
    const pan = isTrunk ? 0 : clamp(branch.endX / halfSpan, -0.85, 0.85);

    const buffer = this.buffers.get(key);
    if (buffer) {
      this.triggerSampleNote({
        buffer,
        offset: this.activeOffsets.get(key) || 0,
        when: scheduledTime,
        playbackRate,
        gainAmount: baseGain,
        pan,
        noteDuration,
        attack,
        release,
        targetBus,
      });
    } else if (this.missingFiles.includes(AUDIO_LABELS[key]) || !this.loadingPromises.has(key)) {
      this.triggerSynthFallbackNote({
        when: scheduledTime,
        frequency: fallbackFreq,
        gainAmount: baseGain * 0.45,
        pan,
        noteDuration,
        attack,
        release,
        isLeaf: branch.isLeaf,
        targetBus,
      });
    } else {
      const triggeredAt = now;
      const epoch = this.transportEpoch;
      this.loadingPromises.get(key).then(() => {
        if (
          epoch !== this.transportEpoch ||
          !this.ctx ||
          !this.isPlayingTree ||
          this.isPaused ||
          this.ctx.state !== 'running'
        ) {
          return;
        }
        const currentNow = this.ctx.currentTime;
        if (currentNow - triggeredAt > 1.2) return;
        this.pruneActiveNotes(currentNow);
        if (this.activeNotes.size >= MAX_SIMULTANEOUS_NOTES) return;

        const decoded = this.buffers.get(key);
        if (decoded) {
          this.triggerSampleNote({
            buffer: decoded,
            offset: this.activeOffsets.get(key) || 0,
            when: currentNow + 0.01,
            playbackRate,
            gainAmount: baseGain,
            pan,
            noteDuration,
            attack,
            release,
            targetBus,
          });
        } else {
          this.triggerSynthFallbackNote({
            when: currentNow + 0.01,
            frequency: fallbackFreq,
            gainAmount: baseGain * 0.45,
            pan,
            noteDuration,
            attack,
            release,
            isLeaf: branch.isLeaf,
            targetBus,
          });
        }
      });
    }
  }

  /**
   * Trigger a decoded AudioBuffer note with soft attack/release and stereo pan.
   */
  triggerSampleNote({
    buffer,
    offset,
    when,
    playbackRate,
    gainAmount,
    pan,
    noteDuration,
    attack,
    release,
    targetBus,
  }) {
    const ctx = this.ctx;
    const maxPlayable = Math.max(0.12, (buffer.duration - offset) / playbackRate - 0.02);
    const dur = Math.min(noteDuration, maxPlayable);
    const safeAttack = Math.min(attack, dur * 0.35);
    const safeRelease = Math.min(release, dur * 0.6);
    const releaseStart = Math.max(when + safeAttack, when + dur - safeRelease);
    const endTime = when + dur;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.setValueAtTime(playbackRate, when);

    const gainNode = ctx.createGain();
    gainNode.gain.setValueAtTime(0, when);
    gainNode.gain.linearRampToValueAtTime(gainAmount, when + safeAttack);
    gainNode.gain.setValueAtTime(gainAmount, releaseStart);
    gainNode.gain.linearRampToValueAtTime(0, endTime);

    const panner = ctx.createStereoPanner();
    panner.pan.setValueAtTime(pan, when);

    source.connect(gainNode);
    gainNode.connect(panner);
    panner.connect(targetBus);

    const record = { source, gainNode, endTime };
    this.activeNotes.add(record);
    source.onended = () => {
      this.activeNotes.delete(record);
    };

    source.start(when, offset);
    source.stop(endTime + 0.02);
  }

  /**
   * Soft synthesized fallback tone used when an MP3 file is missing or unavailable.
   */
  triggerSynthFallbackNote({
    when,
    frequency,
    gainAmount,
    pan,
    noteDuration,
    attack,
    release,
    isLeaf,
    targetBus,
  }) {
    const ctx = this.ctx;
    const dur = noteDuration;
    const safeAttack = Math.min(attack, dur * 0.35);
    const safeRelease = Math.min(release, dur * 0.6);
    const releaseStart = Math.max(when + safeAttack, when + dur - safeRelease);
    const endTime = when + dur;

    const osc = ctx.createOscillator();
    osc.type = isLeaf ? 'sine' : 'triangle';
    osc.frequency.setValueAtTime(frequency, when);

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(isLeaf ? 2200 : 1400, when);

    const gainNode = ctx.createGain();
    gainNode.gain.setValueAtTime(0, when);
    gainNode.gain.linearRampToValueAtTime(gainAmount, when + safeAttack);
    gainNode.gain.setValueAtTime(gainAmount * 0.85, releaseStart);
    gainNode.gain.linearRampToValueAtTime(0, endTime);

    const panner = ctx.createStereoPanner();
    panner.pan.setValueAtTime(pan, when);

    osc.connect(filter);
    filter.connect(gainNode);
    gainNode.connect(panner);
    panner.connect(targetBus);

    const record = { source: osc, gainNode, endTime };
    this.activeNotes.add(record);
    osc.onended = () => {
      this.activeNotes.delete(record);
    };

    osc.start(when);
    osc.stop(endTime + 0.02);
  }
}

:root {
  --bg-deep: #041019;
  --bg-mid: #09222e;
  --bg-panel: rgba(8, 25, 34, 0.86);
  --bg-elevated: rgba(16, 44, 56, 0.72);
  --border-subtle: rgba(128, 214, 194, 0.18);
  --border-focus: #8cf2d3;

  --text-primary: #e8f5f2;
  --text-secondary: #a8cac4;
  --text-muted: #86ada6;

  --accent: #7ce8c8;
  --accent-strong: #9ef7db;
  --accent-text: #041b17;

  --radius-lg: 18px;
  --radius-md: 11px;
  --radius-sm: 8px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: linear-gradient(160deg, var(--bg-deep) 0%, var(--bg-mid) 58%, #0e2e39 100%);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.42;
  -webkit-font-smoothing: antialiased;
}

.app-shell {
  display: flex;
  flex-direction: row;
  height: 100dvh;
  width: 100%;
  overflow: hidden;
}

.garden-stage {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  background: var(--bg-deep);
}

#garden-canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.stage-overlay {
  position: absolute;
  top: 16px;
  left: 16px;
  pointer-events: none;
  z-index: 2;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(5, 19, 27, 0.75);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(10px);
  color: var(--text-secondary);
  font-size: 0.84rem;
  font-weight: 500;
  letter-spacing: 0.01em;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--text-muted);
  transition: background-color 0.25s ease, box-shadow 0.25s ease;
}

.status-dot[data-state="growing"] {
  background: var(--accent);
  box-shadow: 0 0 8px rgba(124, 232, 200, 0.85);
}

.status-dot[data-state="paused"] {
  background: #ebd089;
  box-shadow: 0 0 6px rgba(235, 208, 137, 0.65);
}

.status-dot[data-state="complete"] {
  background: #a5f5be;
  box-shadow: 0 0 8px rgba(165, 245, 190, 0.75);
}

/* Control Sidebar */
.control-panel {
  flex: 0 0 364px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 18px 18px;
  background: var(--bg-panel);
  border-left: 1px solid var(--border-subtle);
  backdrop-filter: blur(14px);
  overflow-y: auto;
  z-index: 3;
}

.panel-header {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.panel-header h1 {
  margin: 0;
  font-size: 1.32rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  color: var(--text-primary);
}

.step-badge {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 9px;
  border-radius: 999px;
  background: rgba(124, 232, 200, 0.14);
  color: var(--accent-strong);
  border: 1px solid rgba(124, 232, 200, 0.3);
}

.subtitle {
  margin: 0;
  font-size: 0.84rem;
  color: var(--text-secondary);
}

.section-heading {
  margin: 0 0 6px;
  font-size: 0.75rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

/* Playback & Progress */
.playback-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.button-row {
  display: grid;
  grid-template-columns: 1.2fr 0.9fr 1fr;
  gap: 8px;
}

.progress-block {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 9px 10px;
  border-radius: var(--radius-md);
  background: rgba(5, 17, 25, 0.6);
  border: 1px solid rgba(128, 214, 194, 0.14);
}

.progress-track {
  width: 100%;
  height: 7px;
  border-radius: 999px;
  background: rgba(140, 212, 198, 0.18);
  overflow: hidden;
}

.progress-fill {
  width: 0%;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #5cc7ab, var(--accent-strong));
  transition: width 0.08s linear;
}

.progress-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.time-readout {
  font-variant-numeric: tabular-nums;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-secondary);
}

/* Buttons */
.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  min-height: 40px;
  padding: 8px 12px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.18s ease, border-color 0.18s ease, transform 0.12s ease, opacity 0.18s ease;
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border-color: var(--border-subtle);
}

.btn-secondary:hover:not(:disabled) {
  background: rgba(24, 62, 76, 0.88);
  border-color: rgba(124, 232, 200, 0.38);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-secondary);
  border-color: rgba(255, 255, 255, 0.12);
}

.btn-ghost:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
}

.btn-compact {
  flex: 0 0 auto;
  padding: 8px 13px;
  white-space: nowrap;
}

.btn-mini {
  min-height: 28px;
  padding: 3px 10px;
  border-radius: 7px;
  font-size: 0.78rem;
}

.btn-mini.is-active {
  background: rgba(124, 232, 200, 0.18);
  border-color: rgba(124, 232, 200, 0.48);
  color: var(--accent-strong);
}

.btn-mini.is-muted {
  background: rgba(235, 190, 120, 0.16);
  border-color: rgba(235, 190, 120, 0.45);
  color: #f3d499;
}

/* Presets */
.preset-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}

.btn-preset {
  min-height: 36px;
  padding: 6px 10px;
  font-size: 0.83rem;
}

.btn-preset.is-active {
  background: rgba(124, 232, 200, 0.18);
  border-color: rgba(124, 232, 200, 0.5);
  color: var(--accent-strong);
}

/* Collapsible Panels */
.panel-group {
  border: 1px solid rgba(128, 214, 194, 0.15);
  border-radius: var(--radius-md);
  background: rgba(6, 20, 28, 0.52);
}

.group-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  font-size: 0.82rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.group-summary::-webkit-details-marker {
  display: none;
}

.group-summary::after {
  content: "+";
  font-size: 1rem;
  font-weight: 500;
  color: var(--accent);
}

.panel-group[open] > .group-summary::after {
  content: "−";
}

.group-body {
  display: flex;
  flex-direction: column;
  gap: 11px;
  padding: 4px 12px 12px;
  border-top: 1px solid rgba(128, 214, 194, 0.1);
}

/* Sliders & Inputs */
.control-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.inline-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

label,
.label-text {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-primary);
}

.helper-text {
  margin: 0;
  font-size: 0.74rem;
  line-height: 1.32;
  color: var(--text-muted);
}

.value-badge {
  font-variant-numeric: tabular-nums;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent-strong);
  background: rgba(124, 232, 200, 0.11);
  border: 1px solid rgba(124, 232, 200, 0.22);
  padding: 1px 7px;
  border-radius: 6px;
  min-width: 50px;
  text-align: center;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 24px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 999px;
  background: rgba(140, 212, 198, 0.2);
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  margin-top: -5.5px;
  background: var(--accent);
  border: 2px solid #052024;
  box-shadow: 0 0 8px rgba(124, 232, 200, 0.5);
  transition: transform 0.15s ease, background-color 0.15s ease;
}

input[type="range"]:hover::-webkit-slider-thumb {
  background: var(--accent-strong);
  transform: scale(1.08);
}

input[type="range"]::-moz-range-track {
  height: 6px;
  border-radius: 999px;
  background: rgba(140, 212, 198, 0.2);
}

input[type="range"]::-moz-range-thumb {
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid #052024;
  box-shadow: 0 0 8px rgba(124, 232, 200, 0.5);
}

.seed-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

input[type="number"],
.select-input {
  width: 100%;
  min-width: 0;
  min-height: 38px;
  padding: 7px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: rgba(4, 15, 22, 0.82);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.88rem;
  font-variant-numeric: tabular-nums;
}

.seed-row input[type="number"] {
  flex: 1 1 auto;
}

.segmented-group {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  margin-top: 2px;
}

.btn-seg {
  min-height: 34px;
  padding: 5px 4px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  background: rgba(16, 44, 56, 0.55);
  color: var(--text-secondary);
  border-color: rgba(128, 214, 194, 0.16);
}

.btn-seg:hover:not(:disabled) {
  background: rgba(24, 62, 76, 0.85);
  color: var(--text-primary);
}

.btn-seg.is-active {
  background: rgba(124, 232, 200, 0.2);
  border-color: rgba(124, 232, 200, 0.55);
  color: var(--accent-strong);
}

/* Focus indicators for keyboard accessibility */
button:focus-visible,
input:focus-visible,
select:focus-visible,
summary:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* Footer & Audio Notice */
.panel-footer {
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid rgba(128, 214, 194, 0.12);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.audio-notice {
  margin: 0;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: rgba(5, 18, 26, 0.65);
  border: 1px solid rgba(128, 214, 194, 0.14);
  color: var(--text-secondary);
  font-size: 0.79rem;
  line-height: 1.38;
}

.audio-notice.is-warning {
  background: rgba(66, 42, 18, 0.55);
  border-color: rgba(242, 196, 120, 0.45);
  color: #f7deb0;
}

.tree-meta {
  margin: 0;
  font-size: 0.82rem;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.shortcuts-hint {
  margin: 0;
  font-size: 0.76rem;
  color: var(--text-muted);
}

kbd {
  display: inline-block;
  padding: 1px 5px;
  border-radius: 4px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.72rem;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: var(--text-primary);
}

/* Responsive mobile / tablet layout */
@media (max-width: 899px) {
  .app-shell {
    flex-direction: column;
    height: auto;
    min-height: 100dvh;
    overflow: visible;
  }

  .garden-stage {
    height: 50dvh;
    min-height: 270px;
    flex: none;
  }

  .control-panel {
    flex: none;
    width: 100%;
    border-left: none;
    border-top: 1px solid var(--border-subtle);
    padding: 16px 14px 24px;
    overflow-y: visible;
  }

  .shortcuts-hint {
    display: none;
  }
}

/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

