for (const btn of ambientModeButtons) {
  btn.addEventListener('click', async () => {
    activePresetId = null;
    await audio.unlock();
    audio.setAmbientMode(btn.dataset.ambient);
    updateToggleButtons();
  });
}

// Keyboard shortcuts: Space = play/pause, M = mute, R = restart
// Never override normal keys while any interactive control is focused.
window.addEventListener('keydown', (event) => {
  if (event.metaKey || event.ctrlKey || event.altKey) return;

  const target = event.target;
  const tag = target && target.tagName ? target.tagName.toUpperCase() : '';
  const isControlFocused =
    tag === 'INPUT' ||
    tag === 'SELECT' ||
    tag === 'TEXTAREA' ||
    tag === 'BUTTON' ||
    tag === 'SUMMARY' ||
    Boolean(target && target.isContentEditable);

  if (isControlFocused) return;

  if (event.code === 'Space') {
    event.preventDefault();
    handlePlayPause();
    return;
  }

  const key = event.key.toLowerCase();
  if (key === 'm') {
    handleToggleMute();
  } else if (key === 'r') {
    handleRestart();
  }
});

// Dynamic reduced-motion handling
const handleMotionChange = (event) => {
  isReducedMotion = event.matches;
  if (isReducedMotion) {
    clearLoopTimer();
  }
  renderer.setReducedMotion(isReducedMotion);
};

if (typeof motionQuery.addEventListener === 'function') {
  motionQuery.addEventListener('change', handleMotionChange);
} else if (typeof motionQuery.addListener === 'function') {
  motionQuery.addListener(handleMotionChange);
}

// Initial boot: show default still preview; wait for user click to start playback + audio
renderer.setSpeed(params.speed);
renderer.setReducedMotion(isReducedMotion);
applyConfiguration({ ...DEFAULTS, loop: false, muted: false }, null);

