31: /**
32:  * Deterministic-feeling PRNG for impulse response generation so offline
33:  * and live renders produce consistent, smooth reverb tails.
34:  */
35: function createIrRandom(seed = 1337) {
36:   let s = seed >>> 0;
37:   return () => {
38:     s = (s + 0x6d2b79f5) | 0;
39:     let t = Math.imul(s ^ (s >>> 15), 1 | s);
40:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
41:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
42:   };
43: }
