45: /**
46:  * Generate a stereo impulse response buffer for the requested reverb preset.
47:  * @param {BaseAudioContext} ctx
48:  * @param {string} [presetId='forest']
49:  * @returns {AudioBuffer}
50:  */
51: export function createReverbImpulse(ctx, presetId = 'forest') {
52:   const preset = REVERB_PRESETS[presetId] || REVERB_PRESETS.forest;
53:   const sampleRate = ctx.sampleRate || 44100;
54:   const length = Math.max(1024, Math.floor(sampleRate * preset.duration));
55:   const impulse = ctx.createBuffer(2, length, sampleRate);
56: 
57:   for (let ch = 0; ch < 2; ch++) {
58:     const channel = impulse.getChannelData(ch);
59:     const rand = createIrRandom(presetId.length * 997 + ch * 49157);
60:     let lp = 0;
61:     const attackSamples = Math.max(1, Math.floor(sampleRate * 0.022));
62: 
63:     for (let i = 0; i < length; i++) {
64:       const t = i / length;
65:       const attack = Math.min(1, i / attackSamples);
66:       const decay = Math.pow(1 - t, preset.decayPower);
67:       const white = rand() * 2 - 1;
68:       lp = lp * preset.damping + white * (1 - preset.damping);
69:       channel[i] = lp * attack * decay * 0.48;
70:     }
71:   }
72: 
73:   return impulse;
