76: /**
77:  * Create a seamlessly crossfaded looping AudioBuffer from a decoded sample,
78:  * eliminating MP3 frame boundary gaps and clicks without runtime re-scheduling.
79:  * @param {BaseAudioContext} ctx
80:  * @param {AudioBuffer} sourceBuffer
81:  * @param {number} [crossfadeSeconds=2.5]
82:  * @returns {AudioBuffer}
83:  */
84: export function createCrossfadedLoopBuffer(ctx, sourceBuffer, crossfadeSeconds = 2.5) {
85:   if (!sourceBuffer || sourceBuffer.length < 64) {
86:     return sourceBuffer;
87:   }
88: 
89:   const sampleRate = sourceBuffer.sampleRate || ctx.sampleRate || 44100;
90:   const numChannels = sourceBuffer.numberOfChannels;
91:   const rawLength = sourceBuffer.length;
92: 
93:   // Trim pure leading/trailing silence (< 0.003 amplitude) on channel 0
94:   const ch0 = sourceBuffer.getChannelData(0);
95:   const threshold = 0.003;
96:   let startSample = 0;
97:   let endSample = rawLength - 1;
98: 
99:   const maxTrim = Math.floor(rawLength * 0.2);
100:   while (startSample < maxTrim && Math.abs(ch0[startSample]) < threshold) {
101:     startSample++;
102:   }
103:   while (endSample > rawLength - 1 - maxTrim && Math.abs(ch0[endSample]) < threshold) {
104:     endSample--;
105:   }
106: 
107:   const trimmedLength = Math.max(256, endSample - startSample + 1);
108:   const maxFade = Math.floor(trimmedLength * 0.25);
109:   const fadeSamples = Math.min(maxFade, Math.max(32, Math.floor(sampleRate * crossfadeSeconds)));
110:   const outLength = Math.max(64, trimmedLength - fadeSamples);
111: 
112:   const outBuffer = ctx.createBuffer(numChannels, outLength, sampleRate);
113: 
114:   for (let ch = 0; ch < numChannels; ch++) {
115:     const src = sourceBuffer.getChannelData(ch);
116:     const dst = outBuffer.getChannelData(ch);
117: 
118:     // Copy main body shifted cleanly after head fade overlap
119:     for (let i = fadeSamples; i < outLength; i++) {
120:       dst[i] = src[startSample + i];
121:     }
122: 
123:     // Equal-power crossfade between tail segment and head segment at loop seam
124:     for (let i = 0; i < fadeSamples; i++) {
125:       const progress = i / fadeSamples;
126:       const fadeIn = Math.sin(progress * Math.PI * 0.5);
127:       const fadeOut = Math.cos(progress * Math.PI * 0.5);
128:       const headSample = src[startSample + i];
129:       const tailSample = src[startSample + outLength + i];
130:       dst[i] = headSample * fadeIn + tailSample * fadeOut;
131:     }
132:   }
133: 
134:   return outBuffer;
135: }
