139:  * @param {BaseAudioContext} ctx
140:  * @param {number} [seconds=4]
141:  * @returns {AudioBuffer}
142:  */
143: export function createPinkNoiseBuffer(ctx, seconds = 4) {
144:   const sampleRate = ctx.sampleRate || 44100;
145:   const length = Math.max(1024, Math.floor(sampleRate * seconds));
146:   const raw = ctx.createBuffer(1, length, sampleRate);
147:   const data = raw.getChannelData(0);
148: 
149:   let b0 = 0;
150:   let b1 = 0;
151:   let b2 = 0;
152:   let b3 = 0;
153:   let b4 = 0;
154:   let b5 = 0;
155:   let b6 = 0;
156:   const rand = createIrRandom(9001);
157: 
158:   for (let i = 0; i < length; i++) {
159:     const white = rand() * 2 - 1;
160:     b0 = 0.99886 * b0 + white * 0.0555179;
161:     b1 = 0.99332 * b1 + white * 0.0750759;
162:     b2 = 0.96900 * b2 + white * 0.1538520;
163:     b3 = 0.86650 * b3 + white * 0.3104856;
164:     b4 = 0.55000 * b4 + white * 0.5329522;
165:     b5 = -0.7616 * b5 - white * 0.0168980;
166:     data[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.09;
167:     b6 = white * 0.115926;
