import { clamp, getTreeTotalDuration } from './tree.js';

/**
 * Pure Web Audio API routing graph, DSP buffer builders, and deterministic
 * composition scheduler. Designed to work identically with live AudioContext
 * and OfflineAudioContext for WAV export.
 */

export const AUDIO_FILES = {
  trunk: 'assets/audio/trunk.mp3',
  branch: 'assets/audio/branch.mp3',
  leaf: 'assets/audio/leaf.mp3',
  ambientRain: 'assets/audio/ambient-rain.mp3',
  ambientNight: 'assets/audio/ambient-night.mp3',
};

export const AUDIO_LABELS = {
  trunk: 'trunk.mp3',
  branch: 'branch.mp3',
  leaf: 'leaf.mp3',
  ambientRain: 'ambient-rain.mp3',
  ambientNight: 'ambient-night.mp3',
};

export const REVERB_PRESETS = {
  'small-garden': {
    label: 'Small Garden',
    duration: 1.25,
    decayPower: 3.3,
    damping: 0.66,
    wetScale: 0.65,
  },
  forest: {
    label: 'Forest',
    duration: 2.35,
    decayPower: 2.5,
    damping: 0.74,
    wetScale: 0.85,
  },
  'open-sky': {
    label: 'Open Sky',
    duration: 3.8,
    decayPower: 1.85,
    damping: 0.82,
    wetScale: 1.0,
  },
};

export const SCALES = {
  'c-major': {
    label: 'C major pentatonic (Calm)',
    slug: 'calm',
    // C4, D4, E4, G4, A4, C5, D5, E5, G5, A5, C6
    semitones: [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24],
    trunkFreq: 130.81, // C3
    refFreq: 261.63,   // C4
    leafFreq: 1046.5,  // C6
    chords: [
      { name: 'Cadd9', padSemitones: [0, 7, 16], pitchClasses: [0, 4, 7] },
      { name: 'Am7', padSemitones: [-3, 4, 12], pitchClasses: [9, 0, 4] },
      { name: 'Dm9', padSemitones: [2, 9, 16], pitchClasses: [2, 4, 9] },
      { name: 'G6', padSemitones: [-5, 2, 14], pitchClasses: [7, 2] },
    ],
  },
  'a-minor': {
    label: 'A minor pentatonic (Dreamy)',
    slug: 'dreamy',
    // A3, C4, D4, E4, G4, A4, C5, D5, E5, G5, A5
    semitones: [-3, 0, 2, 4, 7, 9, 12, 14, 16, 19, 21],
    trunkFreq: 110.0,  // A2
    refFreq: 261.63,   // C4 reference for semitone offsets
    leafFreq: 880.0,   // A5
    chords: [
      { name: 'Am', padSemitones: [-3, 4, 12], pitchClasses: [9, 0, 4] },
      { name: 'C', padSemitones: [0, 7, 16], pitchClasses: [0, 4, 7] },
      { name: 'Dm7', padSemitones: [2, 9, 12], pitchClasses: [2, 9, 0] },
      { name: 'G6', padSemitones: [-5, 2, 16], pitchClasses: [7, 2, 4] },
    ],
  },
};

export const MAX_SIMULTANEOUS_NOTES = 8;

/**
 * Compute playbackRate from semitone offset.
 * @param {number} semitones
 * @returns {number}
 */
export function semitonesToPlaybackRate(semitones) {
  return Math.pow(2, semitones / 12);
}

/**
 * Deterministic PRNG for audio synthesis (reverb IR, wind noise, subtle variations)
 * so live and offline renders produce matching textures without Math.random.
 * @param {number} [seed=1337]
 * @returns {() => number}
 */
export function createAudioSeededRandom(seed = 1337) {
  let s = (Math.trunc(Number(seed)) || 1337) >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Compute pentatonic semitone offset (limited to 2 octaves) so deeper branches
 * play higher or equal notes while favoring pitch classes from the active chord.
 */
export function getBranchPentatonicSemitones(
  depth,
  maxDepth,
  side,
  scaleId = 'c-major',
  chordPitchClasses = null
) {
  const scale = SCALES[scaleId] || SCALES['c-major'];
  const ladder = scale.semitones;

  if (depth <= 1 || maxDepth <= 2) {
    return ladder[0];
  }

  const chordSet = chordPitchClasses ? new Set(chordPitchClasses) : null;
  const normalLevels = Math.max(1, maxDepth - 2);

  let minBandIdx = 0;
  let maxBandIdx = ladder.length - 1;
  let preferredIdx = 0;

  if (normalLevels <= 5) {
    const baseIndex = (depth - 2) * 2;
    minBandIdx = clamp(baseIndex, 0, ladder.length - 1);
    maxBandIdx = clamp(baseIndex + 1, minBandIdx, ladder.length - 1);
    preferredIdx = clamp(baseIndex + (side === 'right' ? 1 : 0), minBandIdx, maxBandIdx);
  } else {
    const ratio = clamp((depth - 2) / (normalLevels - 1), 0, 1);
    preferredIdx = clamp(Math.round(ratio * (ladder.length - 1)), 0, ladder.length - 1);
    minBandIdx = preferredIdx;
    maxBandIdx = clamp(preferredIdx + 1, minBandIdx, ladder.length - 1);
  }

  if (!chordSet) {
    return ladder[preferredIdx];
  }

  const altIdx = preferredIdx === minBandIdx ? maxBandIdx : minBandIdx;
  for (const idx of [preferredIdx, altIdx]) {
    const pc = ((ladder[idx] % 12) + 12) % 12;
    if (chordSet.has(pc)) {
      return ladder[idx];
    }
  }

  return ladder[preferredIdx];
}

/**
 * Scan decoded PCM channel data to skip leading silence while preserving transients.
 * @param {AudioBuffer} buffer
 * @returns {number}
 */
export function findActiveStartOffset(buffer) {
  if (!buffer || buffer.length === 0) return 0;
  const data = buffer.getChannelData(0);
  const sampleRate = buffer.sampleRate || 44100;
  const windowSize = Math.max(256, Math.floor(sampleRate * 0.02));
  const maxScanSamples = Math.min(data.length, Math.floor(sampleRate * 8));

  for (let i = 0; i < maxScanSamples; i += windowSize) {
    let peak = 0;
    const end = Math.min(data.length, i + windowSize);
    for (let j = i; j < end; j++) {
      const abs = Math.abs(data[j]);
      if (abs > peak) peak = abs;
    }
    if (peak >= 0.02) {
      return Math.max(0, i / sampleRate - 0.02);
    }
  }
  return 0;
}

/**
 * Generate a stereo impulse response buffer for the requested reverb preset.
 * @param {BaseAudioContext} ctx
 * @param {string} [presetId='forest']
 * @param {number} [seed=4217]
 * @returns {AudioBuffer}
 */
export function createReverbImpulse(ctx, presetId = 'forest', seed = 4217) {
  const preset = REVERB_PRESETS[presetId] || REVERB_PRESETS.forest;
  const sampleRate = ctx.sampleRate || 44100;
  const length = Math.max(1024, Math.floor(sampleRate * preset.duration));
  const impulse = ctx.createBuffer(2, length, sampleRate);

  for (let ch = 0; ch < 2; ch++) {
    const channel = impulse.getChannelData(ch);
    const rand = createAudioSeededRandom(seed + presetId.length * 997 + ch * 49157);
    let lp = 0;
    const attackSamples = Math.max(1, Math.floor(sampleRate * 0.022));

    for (let i = 0; i < length; i++) {
      const t = i / length;
      const attack = Math.min(1, i / attackSamples);
      const decay = Math.pow(1 - t, preset.decayPower);
      const white = rand() * 2 - 1;
      lp = lp * preset.damping + white * (1 - preset.damping);
      channel[i] = lp * attack * decay * 0.48;
    }
  }

  return impulse;
}

/**
 * Create a seamlessly crossfaded looping AudioBuffer from a decoded sample,
 * eliminating MP3 frame boundary gaps and clicks without runtime timers.
 * @param {BaseAudioContext} ctx
 * @param {AudioBuffer} sourceBuffer
 * @param {number} [crossfadeSeconds=2.5]
 * @returns {AudioBuffer}
 */
export function createCrossfadedLoopBuffer(ctx, sourceBuffer, crossfadeSeconds = 2.5) {
  if (!sourceBuffer || sourceBuffer.length < 64) {
    return sourceBuffer;
  }

  const sampleRate = sourceBuffer.sampleRate || ctx.sampleRate || 44100;
  const numChannels = sourceBuffer.numberOfChannels;
  const rawLength = sourceBuffer.length;

  const ch0 = sourceBuffer.getChannelData(0);
  const threshold = 0.003;
  let startSample = 0;
  let endSample = rawLength - 1;

  const maxTrim = Math.floor(rawLength * 0.2);
  while (startSample < maxTrim && Math.abs(ch0[startSample]) < threshold) {
    startSample++;
  }
  while (endSample > rawLength - 1 - maxTrim && Math.abs(ch0[endSample]) < threshold) {
    endSample--;
  }

  const trimmedLength = Math.max(256, endSample - startSample + 1);
  const maxFade = Math.floor(trimmedLength * 0.25);
  const fadeSamples = Math.min(maxFade, Math.max(32, Math.floor(sampleRate * crossfadeSeconds)));
  const outLength = Math.max(64, trimmedLength - fadeSamples);

  const outBuffer = ctx.createBuffer(numChannels, outLength, sampleRate);

  for (let ch = 0; ch < numChannels; ch++) {
    const src = sourceBuffer.getChannelData(ch);
    const dst = outBuffer.getChannelData(ch);

    for (let i = fadeSamples; i < outLength; i++) {
      dst[i] = src[startSample + i];
    }

    for (let i = 0; i < fadeSamples; i++) {
      const progress = i / fadeSamples;
      const fadeIn = Math.sin(progress * Math.PI * 0.5);
      const fadeOut = Math.cos(progress * Math.PI * 0.5);
      const headSample = src[startSample + i];
      const tailSample = src[startSample + outLength + i];
      dst[i] = headSample * fadeIn + tailSample * fadeOut;
    }
  }

  return outBuffer;
}

/**
 * Create a smooth seeded pink-noise AudioBuffer for procedural wind synthesis.
 * @param {BaseAudioContext} ctx
 * @param {number} [seconds=4]
 * @param {number} [seed=4217]
 * @returns {AudioBuffer}
 */
export function createPinkNoiseBuffer(ctx, seconds = 4, seed = 4217) {
  const sampleRate = ctx.sampleRate || 44100;
  const length = Math.max(1024, Math.floor(sampleRate * seconds));
  const raw = ctx.createBuffer(1, length, sampleRate);
  const data = raw.getChannelData(0);

  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  let b3 = 0;
  let b4 = 0;
  let b5 = 0;
  let b6 = 0;
  const rand = createAudioSeededRandom(seed + 9001);

  for (let i = 0; i < length; i++) {
    const white = rand() * 2 - 1;
    b0 = 0.99886 * b0 + white * 0.0555179;
    b1 = 0.99332 * b1 + white * 0.0750759;
    b2 = 0.96900 * b2 + white * 0.1538520;
    b3 = 0.86650 * b3 + white * 0.3104856;
    b4 = 0.55000 * b4 + white * 0.5329522;
    b5 = -0.7616 * b5 - white * 0.0168980;
    data[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.09;
    b6 = white * 0.115926;
  }

  return createCrossfadedLoopBuffer(ctx, raw, Math.min(1.0, seconds * 0.25));
}

/**
 * Build a deterministic single-cycle schedule of chord changes, branch notes,
 * and resolving chord chimes shared identically by live playback and OfflineAudioContext.
 */
export function buildCycleSchedule({
  events,
  bounds,
  maxDepth,
  speed = 1,
  tempo = 70,
  scale = 'c-major',
  seed = 4217,
}) {
  const safeSpeed = clamp(Number(speed) || 1, 0.5, 2);
  const safeTempo = Math.round(clamp(Number(tempo) || 70, 50, 90));
  const scaleDef = SCALES[scale] || SCALES['c-major'];
  const rand = createAudioSeededRandom(seed + 777);

  const treeWallDuration = getTreeTotalDuration(events) / safeSpeed;
  const beatSeconds = 60 / safeTempo;
  const gridStep = beatSeconds / 4;
  const minGap = clamp(beatSeconds * 0.16, 0.1, 0.22);
  const twoBarsSec = beatSeconds * 8;

  // 1. Chord progression timeline (every 2 bars, settling to chord 0 at end)
  const chords = [];
  for (let t = 0, step = 0; t < treeWallDuration; t += twoBarsSec, step++) {
    const chordIndex = step % scaleDef.chords.length;
    chords.push({
      time: t,
      chordIndex,
      chord: scaleDef.chords[chordIndex],
      isResolving: false,
    });
  }
  chords.push({
    time: treeWallDuration,
    chordIndex: 0,
    chord: scaleDef.chords[0],
    isResolving: true,
  });

  const getChordAt = (wallTime) => {
    let active = chords[0];
    for (const c of chords) {
      if (c.time <= wallTime) {
        active = c;
      } else {
        break;
      }
    }
    return active;
  };

  // 2. Deterministic branch / trunk / leaf note schedule
  const notes = [];
  const notesByBranchId = new Map();
  let activeEndTimes = [];
  let lastScheduledTime = -Infinity;
  const halfSpan = Math.max(20, Math.abs(bounds.minX), Math.abs(bounds.maxX));

  for (const branch of events) {
    const wallStart = branch.startTime / safeSpeed;
    const isTrunk = branch.side === 'trunk' && branch.depth === 1;
    let scheduledTime = wallStart;

    if (!isTrunk) {
      const stepsAhead = Math.max(0, Math.ceil(wallStart / gridStep));
      let quantized = stepsAhead * gridStep;

      if (quantized - lastScheduledTime < minGap) {
        const nextSlot = quantized + gridStep;
        if (
          nextSlot - lastScheduledTime >= minGap &&
          nextSlot - wallStart <= gridStep * 1.6
        ) {
          quantized = nextSlot;
        } else {
          continue;
        }
      }
      scheduledTime = Math.max(0.005, quantized);
    }

    activeEndTimes = activeEndTimes.filter((endT) => endT > scheduledTime);
    if (activeEndTimes.length >= MAX_SIMULTANEOUS_NOTES) {
      continue;
    }

    const chordInfo = getChordAt(scheduledTime);
    const subtleHumanGain = 0.94 + rand() * 0.12;

    let key = 'branch';
    let busName = 'notesBus';
    let playbackRate = 1;
    let gainAmount = 0.36;
    let noteDuration = 0.8;
    let attack = 0.035;
    let release = 0.35;
    let fallbackFreq = scaleDef.refFreq;

    if (isTrunk) {
      key = 'trunk';
      busName = 'notesBus';
      playbackRate = 1;
      gainAmount = 0.45;
      noteDuration = 1.25;
      attack = 0.055;
      release = 0.5;
      fallbackFreq = scaleDef.trunkFreq;
    } else if (branch.isLeaf) {
      key = 'leaf';
      busName = 'leavesBus';
      playbackRate = 1;
      gainAmount = 0.12 * Math.pow(0.92, Math.max(0, branch.depth - 1)) * subtleHumanGain;
      noteDuration = 0.65;
      attack = 0.045;
      release = 0.36;
      fallbackFreq = scaleDef.leafFreq;
    } else {
      key = 'branch';
      busName = 'notesBus';
      const semitones = getBranchPentatonicSemitones(
        branch.depth,
        maxDepth,
        branch.side,
        scale,
        chordInfo.chord.pitchClasses
      );
      playbackRate = semitonesToPlaybackRate(semitones);
      gainAmount = 0.36 * Math.pow(0.84, Math.max(0, branch.depth - 2)) * subtleHumanGain;
      noteDuration = Math.max(0.55, 0.85 - Math.max(0, branch.depth - 2) * 0.04);
      attack = 0.035;
      release = 0.35;
      fallbackFreq = scaleDef.refFreq * playbackRate;
    }

    const pan = isTrunk ? 0 : clamp(branch.endX / halfSpan, -0.85, 0.85);
    lastScheduledTime = scheduledTime;
    activeEndTimes.push(scheduledTime + noteDuration);

    const noteEvent = {
      branchId: branch.id,
      treeTime: branch.startTime,
      time: scheduledTime,
      key,
      busName,
      playbackRate,
      gainAmount,
      pan,
      noteDuration,
      attack,
      release,
      fallbackFreq,
      isLeaf: branch.isLeaf,
    };

    notes.push(noteEvent);
    notesByBranchId.set(branch.id, noteEvent);
  }

  // 3. Resolving tonic chord bloom when tree finishes
  const resolvingPans = [-0.28, 0.28, 0];
  const resolvingNotes = scaleDef.chords[0].padSemitones.map((st, idx) => ({
    time: treeWallDuration + 0.08 + idx * 0.07,
    frequency: scaleDef.refFreq * semitonesToPlaybackRate(st),
    gainAmount: 0.055,
    pan: resolvingPans[idx % resolvingPans.length],
    noteDuration: 2.2,
    attack: 0.32,
    release: 1.25,
    isLeaf: true,
    busName: 'leavesBus',
  }));

  return {
    treeWallDuration,
    chords,
    notes,
    notesByBranchId,
    resolvingNotes,
  };
}

/**
 * Build a complete composition timeline for offline WAV rendering
 * supporting Full tree once, 1 minute, and 3 minutes with 2s fade-in,
 * 4s fade-out, and natural unclipped reverb tail.
 */
export function buildCompositionSchedule({
  events,
  bounds,
  maxDepth,
  speed = 1,
  tempo = 70,
  scale = 'c-major',
  seed = 4217,
  lengthMode = 'full',
  reverbPreset = 'forest',
  hasAmbient = true,
}) {
  const cycle = buildCycleSchedule({
    events,
    bounds,
    maxDepth,
    speed,
    tempo,
    scale,
    seed,
  });

  const fadeInSec = 2.0;
  const fadeOutSec = 4.0;
  const presetMeta = REVERB_PRESETS[reverbPreset] || REVERB_PRESETS.forest;
  const reverbTailSec = presetMeta.duration + 0.55;
  const firstCycleStart = hasAmbient ? 1.5 : 0.2;
  const cycleHoldSec = 2.2;

  let fadeOutStart = 0;
  let fadeOutEnd = 0;

  if (lengthMode === '1m') {
    fadeOutEnd = 60.0;
    fadeOutStart = 56.0;
  } else if (lengthMode === '3m') {
    fadeOutEnd = 180.0;
    fadeOutStart = 176.0;
  } else {
    fadeOutStart = firstCycleStart + cycle.treeWallDuration + 1.5;
    fadeOutEnd = fadeOutStart + fadeOutSec;
  }

  const totalRenderSec = fadeOutEnd + reverbTailSec;
  const cyclePeriod = cycle.treeWallDuration + cycleHoldSec;

  const scheduledNotes = [];
  const scheduledResolvingNotes = [];
  const scheduledChords = [];
  const brightnessEvents = [];

  const maxCycles = lengthMode === 'full' ? 1 : Math.ceil(fadeOutEnd / Math.max(0.5, cyclePeriod)) + 1;

  for (let c = 0; c < maxCycles; c++) {
    const offset = firstCycleStart + c * cyclePeriod;
    if (lengthMode !== 'full' && offset >= fadeOutStart - 1.0) {
      break;
    }

    for (const ch of cycle.chords) {
      const t = offset + ch.time;
      if (t < fadeOutEnd - 0.5) {
        scheduledChords.push({ ...ch, time: t });
      }
    }

    brightnessEvents.push({ time: offset, frequency: 2200, settled: false });
    const midTime = offset + cycle.treeWallDuration * 0.5;
    if (midTime < fadeOutEnd - 0.8) {
      brightnessEvents.push({ time: midTime, frequency: 4700, settled: false });
    }
    const endTime = offset + cycle.treeWallDuration;
    if (endTime < fadeOutEnd - 0.4) {
      brightnessEvents.push({ time: endTime, frequency: 6800, settled: false });
      brightnessEvents.push({ time: endTime + 0.15, frequency: 3400, settled: true });
    }

    for (const note of cycle.notes) {
      const t = offset + note.time;
      if (t < fadeOutEnd - 0.6) {
        scheduledNotes.push({ ...note, time: t });
      }
    }

    for (const rNote of cycle.resolvingNotes) {
      const t = offset + rNote.time;
      if (t < fadeOutEnd - 0.8) {
        scheduledResolvingNotes.push({ ...rNote, time: t });
      }
    }
  }

  return {
    fadeInSec,
    fadeOutSec,
    fadeOutStart,
    fadeOutEnd,
    reverbTailSec,
    totalRenderSec,
    treeWallDuration: cycle.treeWallDuration,
    notes: scheduledNotes,
    resolvingNotes: scheduledResolvingNotes,
    chords: scheduledChords,
    brightnessEvents,
  };
}

/**
 * Build the complete Web Audio signal graph onto any BaseAudioContext
 * (live AudioContext or OfflineAudioContext).
 */
export function createGardenAudioGraph(ctx, initial = {}) {
  const now = ctx.currentTime || 0;
  const masterVolume = initial.masterVolume ?? 0.8;
  const notesVolume = initial.notesVolume ?? 0.8;
  const leavesVolume = initial.leavesVolume ?? 0.7;
  const ambientVolume = initial.ambientVolume ?? 0.52;
  const reverbAmount = initial.reverbAmount ?? 0.42;
  const reverbPreset = initial.reverbPreset ?? 'forest';
  const seed = initial.seed ?? 4217;
  const muted = Boolean(initial.muted);
  const withAnalyser = initial.withAnalyser !== false && typeof ctx.createAnalyser === 'function';

  // --- Melodic & Leaf Buses ---
  const notesBus = ctx.createGain();
  notesBus.gain.setValueAtTime(notesVolume, now);

  const leavesBus = ctx.createGain();
  leavesBus.gain.setValueAtTime(leavesVolume, now);

  const leafDelay = ctx.createDelay(1.0);
  leafDelay.delayTime.setValueAtTime(0.32, now);

  const leafDelayFilter = ctx.createBiquadFilter();
  leafDelayFilter.type = 'lowpass';
  leafDelayFilter.frequency.setValueAtTime(1750, now);

  const leafDelayFeedback = ctx.createGain();
  leafDelayFeedback.gain.setValueAtTime(0.24, now);

  const leafDelayWet = ctx.createGain();
  leafDelayWet.gain.setValueAtTime(0.26, now);

  const notesHPF = ctx.createBiquadFilter();
  notesHPF.type = 'highpass';
  notesHPF.frequency.setValueAtTime(75, now);
  notesHPF.Q.setValueAtTime(0.7, now);

  const brightnessFilter = ctx.createBiquadFilter();
  brightnessFilter.type = 'lowpass';
  brightnessFilter.frequency.setValueAtTime(2400, now);
  brightnessFilter.Q.setValueAtTime(0.65, now);

  const dryBus = ctx.createGain();
  dryBus.gain.setValueAtTime(0.88 - reverbAmount * 0.14, now);

  // --- Ambient Layer Buses ---
  const rainBus = ctx.createGain();
  rainBus.gain.setValueAtTime(0.48, now);

  const nightBus = ctx.createGain();
  nightBus.gain.setValueAtTime(0.52, now);

  const padBus = ctx.createGain();
  padBus.gain.setValueAtTime(0.46, now);

  const windBus = ctx.createGain();
  windBus.gain.setValueAtTime(0.36, now);

  const ambientHPF = ctx.createBiquadFilter();
  ambientHPF.type = 'highpass';
  ambientHPF.frequency.setValueAtTime(85, now);

  const ambientLPF = ctx.createBiquadFilter();
  ambientLPF.type = 'lowpass';
  ambientLPF.frequency.setValueAtTime(5400, now);

  const ambientMasterBus = ctx.createGain();
  ambientMasterBus.gain.setValueAtTime(ambientVolume * 0.34, now);

  // --- Reverb Send Levels & Dual-Convolver Crossfade ---
  const wetSendSum = ctx.createGain();
  wetSendSum.gain.setValueAtTime(1.0, now);

  const notesReverbSend = ctx.createGain();
  notesReverbSend.gain.setValueAtTime(0.48, now);

  const leavesReverbSend = ctx.createGain();
  leavesReverbSend.gain.setValueAtTime(0.95, now);

  const rainReverbSend = ctx.createGain();
  rainReverbSend.gain.setValueAtTime(0.10, now);

  const nightReverbSend = ctx.createGain();
  nightReverbSend.gain.setValueAtTime(0.42, now);

  const padReverbSend = ctx.createGain();
  padReverbSend.gain.setValueAtTime(0.95, now);

  const windReverbSend = ctx.createGain();
  windReverbSend.gain.setValueAtTime(0.48, now);

  const irCache = new Map();
  const getIr = (presetId) => {
    const key = REVERB_PRESETS[presetId] ? presetId : 'forest';
    if (!irCache.has(key)) {
      irCache.set(key, createReverbImpulse(ctx, key, seed));
    }
    return irCache.get(key);
  };

  const convolverA = ctx.createConvolver();
  convolverA.buffer = getIr(reverbPreset);
  const convolverGainA = ctx.createGain();
  convolverGainA.gain.setValueAtTime(1, now);

  const convolverB = ctx.createConvolver();
  convolverB.buffer = getIr(reverbPreset);
  const convolverGainB = ctx.createGain();
  convolverGainB.gain.setValueAtTime(0, now);

  const reverbLPF = ctx.createBiquadFilter();
  reverbLPF.type = 'lowpass';
  reverbLPF.frequency.setValueAtTime(4600, now);

  const presetMeta = REVERB_PRESETS[reverbPreset] || REVERB_PRESETS.forest;
  const wetBus = ctx.createGain();
  wetBus.gain.setValueAtTime(reverbAmount * presetMeta.wetScale * 0.78, now);

  // --- Master Cleanup, Compressor & Anti-Clip Limiter ---
  const mixSum = ctx.createGain();
  mixSum.gain.setValueAtTime(1.0, now);

  const masterHPF = ctx.createBiquadFilter();
  masterHPF.type = 'highpass';
  masterHPF.frequency.setValueAtTime(42, now);

  const masterLPF = ctx.createBiquadFilter();
  masterLPF.type = 'lowpass';
  masterLPF.frequency.setValueAtTime(11500, now);

  const compressor = ctx.createDynamicsCompressor();
  compressor.threshold.setValueAtTime(-16, now);
  compressor.knee.setValueAtTime(20, now);
  compressor.ratio.setValueAtTime(3.2, now);
  compressor.attack.setValueAtTime(0.012, now);
  compressor.release.setValueAtTime(0.22, now);

  const safetyLimiter = ctx.createDynamicsCompressor();
  safetyLimiter.threshold.setValueAtTime(-1.5, now);
  safetyLimiter.knee.setValueAtTime(0, now);
  safetyLimiter.ratio.setValueAtTime(20, now);
  safetyLimiter.attack.setValueAtTime(0.002, now);
  safetyLimiter.release.setValueAtTime(0.08, now);

  const pauseGain = ctx.createGain();
  pauseGain.gain.setValueAtTime(1.0, now);

  const masterGain = ctx.createGain();
  masterGain.gain.setValueAtTime(muted ? 0 : masterVolume, now);

  let analyser = null;
  if (withAnalyser) {
    analyser = ctx.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.85;
  }

  // Routing
  notesBus.connect(dryBus);
  notesBus.connect(notesReverbSend);
  notesReverbSend.connect(wetSendSum);

  leavesBus.connect(dryBus);
  leavesBus.connect(leavesReverbSend);
  leavesReverbSend.connect(wetSendSum);

  leavesBus.connect(leafDelay);
  leafDelay.connect(leafDelayFilter);
  leafDelayFilter.connect(leafDelayFeedback);
  leafDelayFeedback.connect(leafDelay);
  leafDelayFilter.connect(leafDelayWet);
  leafDelayWet.connect(dryBus);
  leafDelayWet.connect(leavesReverbSend);

  dryBus.connect(notesHPF);
  notesHPF.connect(brightnessFilter);
  brightnessFilter.connect(mixSum);

  const ambientDryGate = ctx.createGain();
  ambientDryGate.gain.setValueAtTime(0.85, now);

  const ambientWetMaster = ctx.createGain();
  ambientWetMaster.gain.setValueAtTime(ambientVolume * 0.42, now);

  rainBus.connect(ambientMasterBus);
  nightBus.connect(ambientMasterBus);
  padBus.connect(ambientMasterBus);
  windBus.connect(ambientMasterBus);

  rainBus.connect(rainReverbSend);
  nightBus.connect(nightReverbSend);
  padBus.connect(padReverbSend);
  windBus.connect(windReverbSend);

  rainReverbSend.connect(ambientWetMaster);
  nightReverbSend.connect(ambientWetMaster);
  padReverbSend.connect(ambientWetMaster);
  windReverbSend.connect(ambientWetMaster);
  ambientWetMaster.connect(wetSendSum);

  ambientMasterBus.connect(ambientHPF);
  ambientHPF.connect(ambientLPF);
  ambientLPF.connect(ambientDryGate);
  ambientDryGate.connect(mixSum);

  wetSendSum.connect(convolverA);
  wetSendSum.connect(convolverB);
  convolverA.connect(convolverGainA);
  convolverB.connect(convolverGainB);
  convolverGainA.connect(reverbLPF);
  convolverGainB.connect(reverbLPF);
  reverbLPF.connect(wetBus);
  wetBus.connect(mixSum);

  mixSum.connect(masterHPF);
  masterHPF.connect(masterLPF);
  masterLPF.connect(compressor);
  compressor.connect(safetyLimiter);
  safetyLimiter.connect(pauseGain);
  pauseGain.connect(masterGain);

  if (analyser) {
    masterGain.connect(analyser);
    analyser.connect(ctx.destination);
  } else {
    masterGain.connect(ctx.destination);
  }

  let activeConvolverSlot = 'A';
  let currentReverbPreset = REVERB_PRESETS[reverbPreset] ? reverbPreset : 'forest';
  let currentReverbAmount = reverbAmount;

  return {
    notesBus,
    leavesBus,
    rainBus,
    nightBus,
    padBus,
    windBus,
    ambientMasterBus,
    ambientWetMaster,
    brightnessFilter,
    dryBus,
    wetBus,
    pauseGain,
    masterGain,
    compressor,
    safetyLimiter,
    analyser,

    setReverbPreset(nextPresetId, fadeSeconds = 0.8) {
      const targetId = REVERB_PRESETS[nextPresetId] ? nextPresetId : 'forest';
      const t = ctx.currentTime || 0;
      const meta = REVERB_PRESETS[targetId];

      if (targetId !== currentReverbPreset) {
        currentReverbPreset = targetId;
        const ir = getIr(targetId);

        if (activeConvolverSlot === 'A') {
          convolverB.buffer = ir;
          convolverGainA.gain.cancelScheduledValues(t);
          convolverGainB.gain.cancelScheduledValues(t);
          convolverGainA.gain.setValueAtTime(convolverGainA.gain.value, t);
          convolverGainB.gain.setValueAtTime(convolverGainB.gain.value, t);
          convolverGainA.gain.linearRampToValueAtTime(0, t + fadeSeconds);
          convolverGainB.gain.linearRampToValueAtTime(1, t + fadeSeconds);
          activeConvolverSlot = 'B';
        } else {
          convolverA.buffer = ir;
          convolverGainA.gain.cancelScheduledValues(t);
          convolverGainB.gain.cancelScheduledValues(t);
          convolverGainA.gain.setValueAtTime(convolverGainA.gain.value, t);
          convolverGainB.gain.setValueAtTime(convolverGainB.gain.value, t);
          convolverGainB.gain.linearRampToValueAtTime(0, t + fadeSeconds);
          convolverGainA.gain.linearRampToValueAtTime(1, t + fadeSeconds);
          activeConvolverSlot = 'A';
        }
      }

      wetBus.gain.cancelScheduledValues(t);
      wetBus.gain.setTargetAtTime(currentReverbAmount * meta.wetScale * 0.78, t, 0.05);
    },

    setReverbAmount(amount) {
      currentReverbAmount = Math.min(1, Math.max(0, amount));
      const t = ctx.currentTime || 0;
      const meta = REVERB_PRESETS[currentReverbPreset] || REVERB_PRESETS.forest;
      wetBus.gain.cancelScheduledValues(t);
      wetBus.gain.setTargetAtTime(currentReverbAmount * meta.wetScale * 0.78, t, 0.035);
      dryBus.gain.cancelScheduledValues(t);
      dryBus.gain.setTargetAtTime(0.88 - currentReverbAmount * 0.14, t, 0.035);
    },

    setAmbientMasterVolume(volume) {
      const v = Math.min(1, Math.max(0, volume));
      const t = ctx.currentTime || 0;
      ambientMasterBus.gain.cancelScheduledValues(t);
      ambientMasterBus.gain.setTargetAtTime(v * 0.34, t, 0.04);
      ambientWetMaster.gain.cancelScheduledValues(t);
      ambientWetMaster.gain.setTargetAtTime(v * 0.42, t, 0.04);
    },

    setBrightnessProgress(progress, isSettled = false) {
      const t = ctx.currentTime || 0;
      if (isSettled) {
        brightnessFilter.frequency.cancelScheduledValues(t);
        brightnessFilter.frequency.setTargetAtTime(3400, t, 0.45);
        return;
      }
      const p = Math.min(1, Math.max(0, progress));
      const targetFreq = 2200 + Math.pow(p, 0.85) * 4600;
      brightnessFilter.frequency.cancelScheduledValues(t);
      brightnessFilter.frequency.setTargetAtTime(targetFreq, t, 0.18);
    },
  };
}

import {
  AUDIO_FILES,
  AUDIO_LABELS,
  SCALES,
  buildCompositionSchedule,
  createCrossfadedLoopBuffer,
  createGardenAudioGraph,
  createPinkNoiseBuffer,
  findActiveStartOffset,
  semitonesToPlaybackRate,
} from './audio-graph.js';

const EXPORT_SAMPLE_RATE = 44100;
const TARGET_PEAK_LINEAR = Math.pow(10, -1 / 20); // -1.0 dBFS (~0.89125)

/**
 * Scan peak amplitude across all channels and compute safe -1 dB normalization gain.
 * Avoids dividing by zero on silent buffers and never produces clipping.
 * @param {AudioBuffer} buffer
 * @returns {{ peak: number, normGain: number, isSilent: boolean }}
 */
export function computeSafeNormalization(buffer) {
  let maxAbs = 0;
  for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
    const data = buffer.getChannelData(ch);
    for (let i = 0; i < data.length; i++) {
      const v = Math.abs(data[i]);
      if (v > maxAbs) maxAbs = v;
    }
  }

  if (maxAbs <= 1e-6) {
    return { peak: 0, normGain: 1, isSilent: true };
  }

  // Safely scale up quiet mixes (capped at +15 dB / 5.6x) or attenuate loud peaks to -1 dB
  const normGain = Math.min(5.6, TARGET_PEAK_LINEAR / maxAbs);
  return { peak: maxAbs, normGain, isSilent: false };
}

/**
 * Encode a stereo AudioBuffer to a 16-bit 44.1 kHz PCM WAV Blob
 * with safe peak normalization around -1 dB (no external libraries).
 * @param {AudioBuffer} audioBuffer
 * @returns {{ blob: Blob, duration: number, peakAfterNorm: number, isSilent: boolean }}
 */
export function encodeWav16Stereo(audioBuffer) {
  const numChannels = 2;
  const sampleRate = audioBuffer.sampleRate || EXPORT_SAMPLE_RATE;
  const numFrames = audioBuffer.length;
  const left = audioBuffer.getChannelData(0);
  const right = audioBuffer.numberOfChannels > 1 ? audioBuffer.getChannelData(1) : left;

  const { normGain, isSilent } = computeSafeNormalization(audioBuffer);
  const dataBytes = numFrames * numChannels * 2;
  const wavBuffer = new ArrayBuffer(44 + dataBytes);
  const view = new DataView(wavBuffer);

  const writeAscii = (offset, str) => {
    for (let i = 0; i < str.length; i++) {
      view.setUint8(offset + i, str.charCodeAt(i));
    }
  };

  // Standard 44-byte RIFF/WAVE PCM header
  writeAscii(0, 'RIFF');
  view.setUint32(4, 36 + dataBytes, true);
  writeAscii(8, 'WAVE');
  writeAscii(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true); // PCM
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * numChannels * 2, true);
  view.setUint16(32, numChannels * 2, true);
  view.setUint16(34, 16, true);
  writeAscii(36, 'data');
  view.setUint32(40, dataBytes, true);

  let offset = 44;
  let peakAfterNorm = 0;

  for (let i = 0; i < numFrames; i++) {
    const l = Math.max(-1, Math.min(1, left[i] * normGain));
    const r = Math.max(-1, Math.min(1, right[i] * normGain));

    const absL = Math.abs(l);
    const absR = Math.abs(r);
    if (absL > peakAfterNorm) peakAfterNorm = absL;
    if (absR > peakAfterNorm) peakAfterNorm = absR;

    const intL = l < 0 ? Math.round(l * 32768) : Math.round(l * 32767);
    const intR = r < 0 ? Math.round(r * 32768) : Math.round(r * 32767);

    view.setInt16(offset, Math.max(-32768, Math.min(32767, intL)), true);
    view.setInt16(offset + 2, Math.max(-32768, Math.min(32767, intR)), true);
    offset += 4;
  }

  return {
    blob: new Blob([wavBuffer], { type: 'audio/wav' }),
    duration: numFrames / sampleRate,
    peakAfterNorm,
    isSilent,
  };
}

/**
 * Decode all 5 audio files directly onto the target OfflineAudioContext so sample
 * rates align cleanly at 44.1 kHz without altering live AudioContext buffers.
 */
async function decodeAssetsForContext(ctx) {
  const buffers = new Map();
  const activeOffsets = new Map();
  const missing = [];

  await Promise.all(
    Object.entries(AUDIO_FILES).map(async ([key, url]) => {
      try {
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }
        const raw = await response.arrayBuffer();
        const decoded = await ctx.decodeAudioData(raw);
        if (key === 'ambientRain' || key === 'ambientNight') {
          buffers.set(key, createCrossfadedLoopBuffer(ctx, decoded, 2.5));
        } else {
          buffers.set(key, decoded);
          activeOffsets.set(key, findActiveStartOffset(decoded));
        }
      } catch {
        missing.push(AUDIO_LABELS[key]);
      }
    })
  );

  return { buffers, activeOffsets, missing };
}

/**
 * Schedule a sample note onto OfflineAudioContext without real-time timers.
 */
function scheduleSampleNote(ctx, bus, {
  buffer,
  offset,
  when,
  playbackRate,
  gainAmount,
  pan,
  noteDuration,
  attack,
  release,
}) {
  const maxPlayable = Math.max(0.12, (buffer.duration - offset) / playbackRate - 0.02);
  const dur = Math.min(noteDuration, maxPlayable);
  const safeAttack = Math.min(attack, dur * 0.35);
  const safeRelease = Math.min(release, dur * 0.6);
  const releaseStart = Math.max(when + safeAttack, when + dur - safeRelease);
  const endTime = when + dur;

  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.playbackRate.setValueAtTime(playbackRate, when);

  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(0, when);
  gainNode.gain.linearRampToValueAtTime(gainAmount, when + safeAttack);
  gainNode.gain.setValueAtTime(gainAmount, releaseStart);
  gainNode.gain.linearRampToValueAtTime(0, endTime);

  const panner = ctx.createStereoPanner();
  panner.pan.setValueAtTime(pan, when);

  source.connect(gainNode);
  gainNode.connect(panner);
  panner.connect(bus);

  source.start(when, offset);
  source.stop(endTime + 0.02);
}

/**
 * Schedule a synthesized fallback or resolving chord tone onto OfflineAudioContext.
 */
function scheduleSynthNote(ctx, bus, {
  when,
  frequency,
  gainAmount,
  pan,
  noteDuration,
  attack,
  release,
  isLeaf,
}) {
  const safeAttack = Math.min(attack, noteDuration * 0.35);
  const safeRelease = Math.min(release, noteDuration * 0.6);
  const releaseStart = Math.max(when + safeAttack, when + noteDuration - safeRelease);
  const endTime = when + noteDuration;

  const osc = ctx.createOscillator();
  osc.type = isLeaf ? 'sine' : 'triangle';
  osc.frequency.setValueAtTime(frequency, when);

  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(isLeaf ? 2200 : 1400, when);

  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(0, when);
  gainNode.gain.linearRampToValueAtTime(gainAmount, when + safeAttack);
  gainNode.gain.setValueAtTime(gainAmount * 0.85, releaseStart);
  gainNode.gain.linearRampToValueAtTime(0, endTime);

  const panner = ctx.createStereoPanner();
  panner.pan.setValueAtTime(pan, when);

  osc.connect(filter);
  filter.connect(gainNode);
  gainNode.connect(panner);
  panner.connect(bus);

  osc.start(when);
  osc.stop(endTime + 0.02);
}

/**
 * Render the current Fractal Garden composition offline with OfflineAudioContext,
 * sharing the exact routing, settings, seeded randomness, and schedule as live playback.
 *
 * @param {Object} options
 * @param {Array<Object>} options.events
 * @param {Object} options.bounds
 * @param {number} options.maxDepth
 * @param {number} options.speed
 * @param {number} options.seed
 * @param {number} options.tempo
 * @param {string} options.scale
 * @param {string} options.reverbPreset
 * @param {number} options.reverbAmount
 * @param {number} options.masterVolume Effective unmuted master volume [0, 1]
 * @param {number} options.notesVolume
 * @param {number} options.leavesVolume
 * @param {number} options.ambientVolume
 * @param {Object} options.layers
 * @param {string} options.lengthMode 'full' | '1m' | '3m'
 * @param {(pct: number) => void} [options.onProgress]
 * @returns {Promise<{ blob: Blob, fileName: string, duration: number, peakAfterNorm: number, missing: string[] }>}
 */
export async function renderCompositionWav({
  events,
  bounds,
  maxDepth,
  speed,
  seed,
  tempo,
  scale,
  reverbPreset,
  reverbAmount,
  masterVolume,
  notesVolume,
  leavesVolume,
  ambientVolume,
  layers,
  lengthMode = 'full',
  onProgress = () => {},
}) {
  const OfflineCtx = window.OfflineAudioContext || window.webkitOfflineAudioContext;
  if (!OfflineCtx) {
    throw new Error('OfflineAudioContext is not supported in this browser.');
  }

  const hasAmbient =
    ambientVolume > 0 &&
    ['rain', 'night', 'pad', 'wind'].some((k) => layers[k]?.enabled && layers[k]?.volume > 0);

  const schedule = buildCompositionSchedule({
    events,
    bounds,
    maxDepth,
    speed,
    tempo,
    scale,
    seed,
    lengthMode,
    reverbPreset,
    hasAmbient,
  });

  const frameCount = Math.max(
    EXPORT_SAMPLE_RATE,
    Math.ceil(schedule.totalRenderSec * EXPORT_SAMPLE_RATE)
  );
  const ctx = new OfflineCtx(2, frameCount, EXPORT_SAMPLE_RATE);

  onProgress(5);
  const { buffers, activeOffsets, missing } = await decodeAssetsForContext(ctx);
  onProgress(18);

  const graph = createGardenAudioGraph(ctx, {
    masterVolume,
    notesVolume,
    leavesVolume,
    ambientVolume,
    reverbAmount,
    reverbPreset,
    seed,
    muted: false,
    withAnalyser: false,
  });

  // Set per-layer bus volumes
  graph.rainBus.gain.setValueAtTime(layers.rain.enabled ? layers.rain.volume : 0, 0);
  graph.nightBus.gain.setValueAtTime(layers.night.enabled ? layers.night.volume : 0, 0);
  graph.padBus.gain.setValueAtTime(layers.pad.enabled ? layers.pad.volume : 0, 0);
  graph.windBus.gain.setValueAtTime(layers.wind.enabled ? layers.wind.volume : 0, 0);

  // 2s fade-in at start and 4s fade-out of source buses before reverb tail finishes
  const { fadeInSec, fadeOutStart, fadeOutEnd, totalRenderSec } = schedule;

  graph.ambientMasterBus.gain.setValueAtTime(0, 0);
  graph.ambientMasterBus.gain.linearRampToValueAtTime(ambientVolume * 0.34, fadeInSec);
  graph.ambientMasterBus.gain.setValueAtTime(ambientVolume * 0.34, fadeOutStart);
  graph.ambientMasterBus.gain.linearRampToValueAtTime(0, fadeOutEnd);

  graph.ambientWetMaster.gain.setValueAtTime(0, 0);
  graph.ambientWetMaster.gain.linearRampToValueAtTime(ambientVolume * 0.42, fadeInSec);
  graph.ambientWetMaster.gain.setValueAtTime(ambientVolume * 0.42, fadeOutStart);
  graph.ambientWetMaster.gain.linearRampToValueAtTime(0, fadeOutEnd);

  graph.notesBus.gain.setValueAtTime(notesVolume, 0);
  graph.notesBus.gain.setValueAtTime(notesVolume, fadeOutStart);
  graph.notesBus.gain.linearRampToValueAtTime(0, fadeOutEnd);

  graph.leavesBus.gain.setValueAtTime(leavesVolume, 0);
  graph.leavesBus.gain.setValueAtTime(leavesVolume, fadeOutStart);
  graph.leavesBus.gain.linearRampToValueAtTime(0, fadeOutEnd);

  // Gentle anti-click master envelope; stays at target through reverbTailSec
  graph.masterGain.gain.setValueAtTime(0, 0);
  graph.masterGain.gain.linearRampToValueAtTime(masterVolume, 0.08);
  graph.masterGain.gain.setValueAtTime(masterVolume, Math.max(0.1, totalRenderSec - 0.12));
  graph.masterGain.gain.linearRampToValueAtTime(0, totalRenderSec);

  const pinkNoiseBuffer = createPinkNoiseBuffer(ctx, 4, seed);

  // Schedule enabled ambient layers strictly up to fadeOutEnd (letting reverb ring out after)
  const ambientStopTime = fadeOutEnd + 0.05;

  if (layers.rain.enabled && layers.rain.volume > 0) {
    const rainBuf = buffers.get('ambientRain');
    if (rainBuf) {
      const src = ctx.createBufferSource();
      src.buffer = rainBuf;
      src.loop = true;
      src.connect(graph.rainBus);
      src.start(0);
      src.stop(ambientStopTime);
    } else {
      const src = ctx.createBufferSource();
      src.buffer = pinkNoiseBuffer;
      src.loop = true;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(750, 0);
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0.42, 0);
      src.connect(filter);
      filter.connect(gain);
      gain.connect(graph.rainBus);
      src.start(0);
      src.stop(ambientStopTime);
    }
  }

  if (layers.night.enabled && layers.night.volume > 0) {
    const nightBuf = buffers.get('ambientNight');
    if (nightBuf) {
      const src = ctx.createBufferSource();
      src.buffer = nightBuf;
      src.loop = true;
      src.connect(graph.nightBus);
      src.start(0);
      src.stop(ambientStopTime);
    } else {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(196, 0);
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0.08, 0);
      osc.connect(gain);
      gain.connect(graph.nightBus);
      osc.start(0);
      osc.stop(ambientStopTime);
    }
  }

  if (layers.pad.enabled && layers.pad.volume > 0) {
    const scaleDef = SCALES[scale] || SCALES['c-major'];
    const padFilter = ctx.createBiquadFilter();
    padFilter.type = 'lowpass';
    padFilter.frequency.setValueAtTime(640, 0);
    padFilter.Q.setValueAtTime(0.7, 0);

    const padBreathGain = ctx.createGain();
    padBreathGain.gain.setValueAtTime(0.24, 0);

    const filterLfo = ctx.createOscillator();
    filterLfo.type = 'sine';
    filterLfo.frequency.setValueAtTime(0.08, 0);
    const filterDepth = ctx.createGain();
    filterDepth.gain.setValueAtTime(240, 0);
    filterLfo.connect(filterDepth);
    filterDepth.connect(padFilter.frequency);

    const ampLfo = ctx.createOscillator();
    ampLfo.type = 'sine';
    ampLfo.frequency.setValueAtTime(0.062, 0);
    const ampDepth = ctx.createGain();
    ampDepth.gain.setValueAtTime(0.06, 0);
    ampLfo.connect(ampDepth);
    ampDepth.connect(padBreathGain.gain);

    const voiceOscs = scaleDef.chords[0].padSemitones.map((st, idx) => {
      const osc = ctx.createOscillator();
      osc.type = idx === 0 ? 'sine' : 'triangle';
      osc.frequency.setValueAtTime(scaleDef.refFreq * semitonesToPlaybackRate(st), 0);

      const vGain = ctx.createGain();
      vGain.gain.setValueAtTime(idx === 0 ? 0.36 : 0.22, 0);
      osc.connect(vGain);
      vGain.connect(padFilter);
      osc.start(0);
      osc.stop(ambientStopTime);
      return osc;
    });

    // Schedule deterministic chord progression glides without timers
    for (const ch of schedule.chords) {
      voiceOscs.forEach((osc, idx) => {
        const st = ch.chord.padSemitones[idx] ?? ch.chord.padSemitones[0];
        const freq = scaleDef.refFreq * semitonesToPlaybackRate(st);
        osc.frequency.setTargetAtTime(freq, ch.time, ch.isResolving ? 1.1 : 0.75);
      });
    }

    padFilter.connect(padBreathGain);
    padBreathGain.connect(graph.padBus);
    filterLfo.start(0);
    ampLfo.start(0);
    filterLfo.stop(ambientStopTime);
    ampLfo.stop(ambientStopTime);
  }

  if (layers.wind.enabled && layers.wind.volume > 0) {
    const src = ctx.createBufferSource();
    src.buffer = pinkNoiseBuffer;
    src.loop = true;

    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'bandpass';
    windFilter.frequency.setValueAtTime(360, 0);
    windFilter.Q.setValueAtTime(1.25, 0);

    const windBreathGain = ctx.createGain();
    windBreathGain.gain.setValueAtTime(0.45, 0);

    const filterLfo = ctx.createOscillator();
    filterLfo.type = 'sine';
    filterLfo.frequency.setValueAtTime(0.09, 0);
    const filterDepth = ctx.createGain();
    filterDepth.gain.setValueAtTime(175, 0);
    filterLfo.connect(filterDepth);
    filterDepth.connect(windFilter.frequency);

    const ampLfo = ctx.createOscillator();
    ampLfo.type = 'sine';
    ampLfo.frequency.setValueAtTime(0.055, 0);
    const ampDepth = ctx.createGain();
    ampDepth.gain.setValueAtTime(0.24, 0);
    ampLfo.connect(ampDepth);
    ampDepth.connect(windBreathGain.gain);

    src.connect(windFilter);
    windFilter.connect(windBreathGain);
    windBreathGain.connect(graph.windBus);

    src.start(0);
    filterLfo.start(0);
    ampLfo.start(0);
    src.stop(ambientStopTime);
    filterLfo.stop(ambientStopTime);
    ampLfo.stop(ambientStopTime);
  }

  // Schedule deterministic brightness curve
  for (const b of schedule.brightnessEvents) {
    graph.brightnessFilter.frequency.setTargetAtTime(b.frequency, b.time, b.settled ? 0.45 : 0.25);
  }

  // Schedule all tree notes
  for (const note of schedule.notes) {
    const bus = note.busName === 'leavesBus' ? graph.leavesBus : graph.notesBus;
    const buffer = buffers.get(note.key);
    if (buffer) {
      scheduleSampleNote(ctx, bus, {
        buffer,
        offset: activeOffsets.get(note.key) || 0,
        when: note.time,
        playbackRate: note.playbackRate,
        gainAmount: note.gainAmount,
        pan: note.pan,
        noteDuration: note.noteDuration,
        attack: note.attack,
        release: note.release,
      });
    } else {
      scheduleSynthNote(ctx, bus, {
        when: note.time,
        frequency: note.fallbackFreq,
        gainAmount: note.gainAmount * 0.45,
        pan: note.pan,
        noteDuration: note.noteDuration,
        attack: note.attack,
        release: note.release,
        isLeaf: note.isLeaf,
      });
    }
  }

  // Schedule soft resolving chord notes
  for (const rNote of schedule.resolvingNotes) {
    scheduleSynthNote(ctx, graph.leavesBus, {
      when: rNote.time,
      frequency: rNote.frequency,
      gainAmount: rNote.gainAmount,
      pan: rNote.pan,
      noteDuration: rNote.noteDuration,
      attack: rNote.attack,
      release: rNote.release,
      isLeaf: true,
    });
  }

  onProgress(24);

  // Render offline audio while smoothly reporting progress via requestAnimationFrame
  let rafId = null;
  let visualPct = 24;
  const updateRenderProgress = () => {
    const ctxPct =
      schedule.totalRenderSec > 0
        ? 24 + (ctx.currentTime / schedule.totalRenderSec) * 64
        : 24;
    visualPct = Math.min(88, Math.max(visualPct + 0.5, ctxPct));
    onProgress(Math.round(visualPct));
    rafId = requestAnimationFrame(updateRenderProgress);
  };
  if (typeof requestAnimationFrame === 'function') {
    rafId = requestAnimationFrame(updateRenderProgress);
  }

  let renderedBuffer;
  try {
    renderedBuffer = await ctx.startRendering();
  } finally {
    if (rafId !== null && typeof cancelAnimationFrame === 'function') {
      cancelAnimationFrame(rafId);
    }
  }

  onProgress(92);
  await new Promise((resolve) => setTimeout(resolve, 0));

  const encoded = encodeWav16Stereo(renderedBuffer);
  onProgress(100);

  const moodSlug = (SCALES[scale] || SCALES['c-major']).slug;
  const fileName = `fractal-garden_depth${maxDepth}_seed${seed}_${moodSlug}.wav`;

  return {
    blob: encoded.blob,
    fileName,
    duration: encoded.duration,
    peakAfterNorm: encoded.peakAfterNorm,
    isSilent: encoded.isSilent,
    missing,
  };
}

/**
 * Trigger browser file download for a Blob and clean up object URL.
 * @param {Blob} blob
 * @param {string} fileName
 */
export function triggerBlobDownload(blob, fileName) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  link.style.display = 'none';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  setTimeout(() => URL.revokeObjectURL(url), 1500);
}

import { clamp } from './tree.js';
import {
  AUDIO_FILES,
  AUDIO_LABELS,
  MAX_SIMULTANEOUS_NOTES,
  REVERB_PRESETS,
  SCALES,
  buildCycleSchedule,
  createCrossfadedLoopBuffer,
  createGardenAudioGraph,
  createPinkNoiseBuffer,
  findActiveStartOffset,
  getBranchPentatonicSemitones,
  semitonesToPlaybackRate,
} from './audio-graph.js';

export { REVERB_PRESETS, SCALES, getBranchPentatonicSemitones, semitonesToPlaybackRate };

const LAYER_FADE_SECONDS = 2.4;

/**
 * Web Audio API live sound engine for Fractal Garden.
 * Shares the deterministic routing graph and cycle schedule with OfflineAudioContext export.
 */
export class GardenAudio {
  /**
   * @param {Object} [callbacks]
   * @param {(info: { ready: boolean, missing: string[], message: string }) => void} [callbacks.onStatusChange]
   */
  constructor(callbacks = {}) {
    this.onStatusChange = callbacks.onStatusChange || (() => {});

    this.ctx = null;
    this.graph = null;
    this.initialized = false;
    this.loadingStarted = false;
    this.isPlayingTree = false;
    this.isPaused = false;
    this.isSettled = false;
    this.transportEpoch = 0;

    this.masterVolume = 0.8;
    this.preMuteVolume = 0.8;
    this.notesVolume = 0.8;
    this.leavesVolume = 0.7;
    this.ambientVolume = 0.52;
    this.reverbAmount = 0.42;
    this.reverbPreset = 'forest';
    this.muted = false;

    this.scale = 'c-major';
    this.pendingTempo = 70;
    this.activeTempo = 70;
    this.seed = 4217;
    this.scheduleSpeed = 1;

    this.layers = {
      rain: { enabled: true, volume: 0.48 },
      night: { enabled: true, volume: 0.52 },
      pad: { enabled: true, volume: 0.46 },
      wind: { enabled: true, volume: 0.36 },
    };

    this.layerHandles = {
      rain: null,
      night: null,
      pad: null,
      wind: null,
    };

    this.buffers = new Map();
    this.activeOffsets = new Map();
    this.loadingPromises = new Map();
    this.missingFiles = [];
    this.pinkNoiseBuffer = null;

    this.suspendTimer = null;
    this.chordInterval = null;
    this.currentChordIndex = 0;
    this.growthStartTime = 0;
    this.currentCycleSchedule = null;

    this.activeNotes = new Set();
    this.gridOrigin = 0;
    this.lastScheduledTime = -Infinity;
    this.energyData = null;
  }

  /**
   * Ensure AudioContext is created and resumed inside a user gesture handler.
   * @returns {Promise<boolean>}
   */
  async unlock() {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) {
      this.emitStatus('Web Audio API is unavailable in this browser.');
      return false;
    }

    if (!this.ctx) {
      this.ctx = new AudioCtx();
      this.graph = createGardenAudioGraph(this.ctx, {
        masterVolume: this.masterVolume,
        notesVolume: this.notesVolume,
        leavesVolume: this.leavesVolume,
        ambientVolume: this.ambientVolume,
        reverbAmount: this.reverbAmount,
        reverbPreset: this.reverbPreset,
        seed: this.seed,
        muted: this.muted,
        withAnalyser: true,
      });

      this.syncLayerBusVolumes();
      this.pinkNoiseBuffer = createPinkNoiseBuffer(this.ctx, 4, this.seed);
      if (this.graph.analyser) {
        this.energyData = new Uint8Array(this.graph.analyser.fftSize);
      }

      this.initialized = true;
      this.gridOrigin = this.ctx.currentTime;
    }

    if (!this.loadingStarted) {
      this.loadingStarted = true;
      this.loadAllAssets();
    }

    if (this.ctx.state === 'suspended' && !this.isPaused) {
      try {
        await this.ctx.resume();
      } catch {
        // Ignore resume failure outside gesture
      }
    }

    return true;
  }

  syncLayerBusVolumes() {
    if (!this.ctx || !this.graph) return;
    const now = this.ctx.currentTime;
    this.graph.rainBus.gain.setValueAtTime(this.layers.rain.volume, now);
    this.graph.nightBus.gain.setValueAtTime(this.layers.night.volume, now);
    this.graph.padBus.gain.setValueAtTime(this.layers.pad.volume, now);
    this.graph.windBus.gain.setValueAtTime(this.layers.wind.volume, now);
  }

  async loadAllAssets() {
    const entries = Object.entries(AUDIO_FILES);
    const missing = [];

    await Promise.all(
      entries.map(([key, url]) => {
        const task = (async () => {
          try {
            const response = await fetch(url);
            if (!response.ok) {
              throw new Error(`HTTP ${response.status}`);
            }
            const arrayBuffer = await response.arrayBuffer();
            const decoded = await this.ctx.decodeAudioData(arrayBuffer);

            if (key === 'ambientRain' || key === 'ambientNight') {
              this.buffers.set(key, createCrossfadedLoopBuffer(this.ctx, decoded, 2.5));
            } else {
              this.buffers.set(key, decoded);
              this.activeOffsets.set(key, findActiveStartOffset(decoded));
            }
          } catch {
            missing.push(AUDIO_LABELS[key]);
          }
        })();
        this.loadingPromises.set(key, task);
        return task;
      })
    );

    this.missingFiles = missing;

    if (this.isPlayingTree && !this.isPaused) {
      this.syncAllLayers(LAYER_FADE_SECONDS);
    }

    if (missing.length > 0) {
      this.emitStatus(
        `Missing or unreadable audio file(s): ${missing.join(', ')} — using soft synthesized fallback.`
      );
    } else {
      this.emitActiveSummary();
    }
  }

  emitActiveSummary() {
    if (!this.initialized || this.missingFiles.length > 0) return;
    const scaleName = this.scale === 'a-minor' ? 'A minor' : 'C major';
    const presetName = (REVERB_PRESETS[this.reverbPreset] || REVERB_PRESETS.forest).label;
    this.emitStatus(`Audio ready · ${scaleName} · ${this.activeTempo} BPM · ${presetName}`);
  }

  emitStatus(message) {
    this.onStatusChange({
      ready: this.initialized,
      missing: [...this.missingFiles],
      message,
    });
  }

  clearSuspendTimer() {
    if (this.suspendTimer !== null) {
      clearTimeout(this.suspendTimer);
      this.suspendTimer = null;
    }
  }

  clearChordScheduler() {
    if (this.chordInterval !== null) {
      clearInterval(this.chordInterval);
      this.chordInterval = null;
    }
  }

  getCurrentChord() {
    const scale = SCALES[this.scale] || SCALES['c-major'];
    const idx = clamp(this.currentChordIndex, 0, scale.chords.length - 1);
    return scale.chords[idx];
  }

  startChordScheduler() {
    this.clearChordScheduler();
    if (!this.ctx) return;

    this.currentChordIndex = 0;
    this.growthStartTime = this.ctx.currentTime;

    this.chordInterval = setInterval(() => {
      if (!this.ctx || !this.isPlayingTree || this.isPaused) return;

      if (this.isSettled) {
        if (this.currentChordIndex !== 0) {
          this.currentChordIndex = 0;
          this.glidePadToCurrentChord(1.2);
        }
        return;
      }

      const elapsed = Math.max(0, this.ctx.currentTime - this.growthStartTime);
      let nextIndex = 0;

      if (this.currentCycleSchedule && this.currentCycleSchedule.chords.length > 0) {
        for (const c of this.currentCycleSchedule.chords) {
          if (c.time <= elapsed) {
            nextIndex = c.chordIndex;
          } else {
            break;
          }
        }
      } else {
        const scale = SCALES[this.scale] || SCALES['c-major'];
        const twoBarsSec = (60 / this.activeTempo) * 8;
        nextIndex = Math.floor(elapsed / twoBarsSec) % scale.chords.length;
      }

      if (nextIndex !== this.currentChordIndex) {
        this.currentChordIndex = nextIndex;
        this.glidePadToCurrentChord(0.85);
      }
    }, 300);
  }

  /**
   * Start or restart audio playback from t = 0 using the shared deterministic schedule.
   */
  async startGrowth({
    keepAmbient = false,
    events = null,
    bounds = null,
    maxDepth = 7,
    speed = 1,
    seed = this.seed,
  } = {}) {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();

    this.activeTempo = this.pendingTempo;
    this.seed = seed;
    this.scheduleSpeed = clamp(Number(speed) || 1, 0.5, 2);
    this.isPlayingTree = true;
    this.isPaused = false;
    this.isSettled = false;
    this.currentChordIndex = 0;

    if (events && bounds) {
      this.currentCycleSchedule = buildCycleSchedule({
        events,
        bounds,
        maxDepth,
        speed: this.scheduleSpeed,
        tempo: this.activeTempo,
        scale: this.scale,
        seed: this.seed,
      });
    } else {
      this.currentCycleSchedule = null;
    }

    const ok = await this.unlock();
    if (!ok || epoch !== this.transportEpoch) return;

    this.stopAllNotes(0.035);

    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch {
        return;
      }
      if (epoch !== this.transportEpoch) return;
    }

    const now = this.ctx.currentTime;
    this.gridOrigin = now;
    this.lastScheduledTime = -Infinity;
    this.growthStartTime = now;

    this.graph.setBrightnessProgress(0, false);
    this.graph.pauseGain.gain.cancelScheduledValues(now);
    this.graph.pauseGain.gain.setValueAtTime(this.graph.pauseGain.gain.value, now);
    this.graph.pauseGain.gain.linearRampToValueAtTime(1, now + 0.06);

    this.startChordScheduler();
    this.syncAllLayers(keepAmbient ? 1.0 : LAYER_FADE_SECONDS);
    this.glidePadToCurrentChord(0.6);
    this.emitActiveSummary();
  }

  updateGrowthProgress(progress) {
    if (!this.ctx || !this.graph || this.isPaused || this.isSettled) return;
    this.graph.setBrightnessProgress(progress, false);
  }

  completeGrowth() {
    if (!this.ctx || !this.graph || !this.isPlayingTree || this.isPaused || this.isSettled) {
      return;
    }
    this.isSettled = true;
    this.currentChordIndex = 0;
    this.graph.setBrightnessProgress(1, true);
    this.glidePadToCurrentChord(1.2);

    if (this.ctx.state === 'running' && !this.muted) {
      const now = this.ctx.currentTime;
      const scale = SCALES[this.scale] || SCALES['c-major'];
      const resolving = this.currentCycleSchedule
        ? this.currentCycleSchedule.resolvingNotes
        : scale.chords[0].padSemitones.map((st, idx) => ({
            time: 0.08 + idx * 0.07,
            frequency: scale.refFreq * semitonesToPlaybackRate(st),
            gainAmount: 0.055,
            pan: [-0.28, 0.28, 0][idx % 3],
            noteDuration: 2.2,
            attack: 0.32,
            release: 1.25,
          }));

      const baseOffset = this.currentCycleSchedule
        ? this.currentCycleSchedule.treeWallDuration
        : 0;

      for (const rNote of resolving) {
        if (this.activeNotes.size >= MAX_SIMULTANEOUS_NOTES) break;
        const delay = Math.max(0.05, rNote.time - baseOffset);
        this.triggerSynthFallbackNote({
          when: now + delay,
          frequency: rNote.frequency,
          gainAmount: rNote.gainAmount,
          pan: rNote.pan,
          noteDuration: rNote.noteDuration,
          attack: rNote.attack,
          release: rNote.release,
          isLeaf: true,
          targetBus: this.graph.leavesBus,
        });
      }
    }
  }

  async pause() {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();
    if (!this.ctx || !this.isPlayingTree || this.isPaused) return;

    this.isPaused = true;
    const now = this.ctx.currentTime;
    this.stopAllNotes(0.045);

    this.graph.pauseGain.gain.cancelScheduledValues(now);
    this.graph.pauseGain.gain.setValueAtTime(this.graph.pauseGain.gain.value, now);
    this.graph.pauseGain.gain.linearRampToValueAtTime(0, now + 0.08);

    this.suspendTimer = setTimeout(() => {
      this.suspendTimer = null;
      if (epoch === this.transportEpoch && this.isPaused && this.ctx && this.ctx.state === 'running') {
        this.ctx.suspend().catch(() => {});
      }
    }, 105);
  }

  async resume() {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();
    if (!this.ctx || !this.isPlayingTree || !this.isPaused) return;

    this.isPaused = false;

    if (this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch {
        return;
      }
      if (epoch !== this.transportEpoch) return;
    }

    const now = this.ctx.currentTime;
    this.gridOrigin = now;
    this.lastScheduledTime = -Infinity;

    this.graph.pauseGain.gain.cancelScheduledValues(now);
    this.graph.pauseGain.gain.setValueAtTime(this.graph.pauseGain.gain.value, now);
    this.graph.pauseGain.gain.linearRampToValueAtTime(1, now + 0.12);

    this.syncAllLayers(0.8);
  }

  stop() {
    const epoch = ++this.transportEpoch;
    this.clearSuspendTimer();
    this.clearChordScheduler();
    this.isPlayingTree = false;
    this.isPaused = false;
    this.isSettled = false;
    this.currentCycleSchedule = null;
    this.lastScheduledTime = -Infinity;

    if (!this.ctx || !this.graph) return;

    const now = this.ctx.currentTime;
    this.stopAllNotes(0.06);
    this.syncAllLayers(1.1);

    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }

    if (epoch === this.transportEpoch) {
      this.graph.pauseGain.gain.cancelScheduledValues(now);
      this.graph.pauseGain.gain.setValueAtTime(this.graph.pauseGain.gain.value, now);
      this.graph.pauseGain.gain.linearRampToValueAtTime(1, now + 0.06);
    }
  }

  setSeed(seed) {
    this.seed = Number.isFinite(Number(seed)) ? Math.trunc(Number(seed)) : 4217;
    if (this.ctx && this.pinkNoiseBuffer) {
      this.pinkNoiseBuffer = createPinkNoiseBuffer(this.ctx, 4, this.seed);
    }
  }

  setMasterVolume(value) {
    const v = clamp(Number(value) || 0, 0, 1);
    this.masterVolume = v;
    if (v > 0) {
      this.preMuteVolume = v;
      if (this.muted) {
        this.muted = false;
      }
    }
    if (!this.ctx || !this.graph) return;
    const now = this.ctx.currentTime;
    const target = this.muted ? 0 : this.masterVolume;
    this.graph.masterGain.gain.cancelScheduledValues(now);
    this.graph.masterGain.gain.setTargetAtTime(target, now, 0.025);
  }

  setNotesVolume(value) {
    this.notesVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.graph) return;
    const now = this.ctx.currentTime;
    this.graph.notesBus.gain.cancelScheduledValues(now);
    this.graph.notesBus.gain.setTargetAtTime(this.notesVolume, now, 0.025);
  }

  setLeavesVolume(value) {
    this.leavesVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.graph) return;
    const now = this.ctx.currentTime;
    this.graph.leavesBus.gain.cancelScheduledValues(now);
    this.graph.leavesBus.gain.setTargetAtTime(this.leavesVolume, now, 0.025);
  }

  setAmbientVolume(value) {
    this.ambientVolume = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.graph) return;
    this.graph.setAmbientMasterVolume(this.ambientVolume);
  }

  setLayerEnabled(layerName, enabled) {
    if (!this.layers[layerName]) return;
    this.layers[layerName].enabled = Boolean(enabled);
    if (this.ctx && this.isPlayingTree && !this.isPaused) {
      this.syncLayer(layerName, this.layers[layerName].enabled, LAYER_FADE_SECONDS);
    }
  }

  setLayerVolume(layerName, value) {
    if (!this.layers[layerName]) return;
    const v = clamp(Number(value) || 0, 0, 1);
    this.layers[layerName].volume = v;
    if (!this.ctx || !this.graph) return;
    const bus = this.graph[`${layerName}Bus`];
    if (!bus) return;
    const now = this.ctx.currentTime;
    bus.gain.cancelScheduledValues(now);
    bus.gain.setTargetAtTime(v, now, 0.04);
  }

  setReverbAmount(value) {
    this.reverbAmount = clamp(Number(value) || 0, 0, 1);
    if (!this.ctx || !this.graph) return;
    this.graph.setReverbAmount(this.reverbAmount);
  }

  setReverbPreset(presetId) {
    this.reverbPreset = REVERB_PRESETS[presetId] ? presetId : 'forest';
    if (this.ctx && this.graph) {
      this.graph.setReverbPreset(this.reverbPreset, 0.85);
    }
    this.emitActiveSummary();
  }

  setTempo(bpm) {
    this.pendingTempo = Math.round(clamp(Number(bpm) || 70, 50, 90));
  }

  setScale(scaleId) {
    this.scale = scaleId === 'a-minor' ? 'a-minor' : 'c-major';
    if (this.ctx && this.layerHandles.pad) {
      this.glidePadToCurrentChord(0.8);
    }
    this.emitActiveSummary();
  }

  setMuted(muted) {
    const nextMuted = Boolean(muted);
    if (nextMuted) {
      if (this.masterVolume > 0) {
        this.preMuteVolume = this.masterVolume;
      }
      this.muted = true;
    } else {
      this.muted = false;
      this.masterVolume = this.preMuteVolume > 0 ? this.preMuteVolume : 0.8;
    }

    if (this.ctx && this.graph) {
      const now = this.ctx.currentTime;
      const target = this.muted ? 0 : this.masterVolume;
      this.graph.masterGain.gain.cancelScheduledValues(now);
      this.graph.masterGain.gain.setTargetAtTime(target, now, 0.025);
    }

    return this.muted ? 0 : this.masterVolume;
  }

  syncAllLayers(fadeSeconds = LAYER_FADE_SECONDS) {
    if (!this.ctx || !this.graph) return;
    const active = this.isPlayingTree && !this.isPaused;
    for (const name of ['rain', 'night', 'pad', 'wind']) {
      this.syncLayer(name, active && this.layers[name].enabled, fadeSeconds);
    }
  }

  syncLayer(name, shouldPlay, fadeSeconds = LAYER_FADE_SECONDS) {
    if (!this.ctx || !this.graph) return;
    const now = this.ctx.currentTime;
    let handle = this.layerHandles[name];

    if (shouldPlay) {
      if (handle) {
        if (handle.stopTimer !== null) {
          clearTimeout(handle.stopTimer);
          handle.stopTimer = null;
        }
        handle.fadeGain.gain.cancelScheduledValues(now);
        handle.fadeGain.gain.setValueAtTime(handle.fadeGain.gain.value, now);
        handle.fadeGain.gain.linearRampToValueAtTime(1, now + fadeSeconds);
        return;
      }

      handle = this.createLayerHandle(name, now);
      if (handle) {
        this.layerHandles[name] = handle;
        handle.fadeGain.gain.setValueAtTime(0, now);
        handle.fadeGain.gain.linearRampToValueAtTime(1, now + fadeSeconds);
      }
      return;
    }

    if (!handle) return;

    if (handle.stopTimer !== null) {
      clearTimeout(handle.stopTimer);
    }
    handle.fadeGain.gain.cancelScheduledValues(now);
    handle.fadeGain.gain.setValueAtTime(handle.fadeGain.gain.value, now);
    handle.fadeGain.gain.linearRampToValueAtTime(0, now + fadeSeconds);

    handle.stopTimer = setTimeout(() => {
      this.destroyLayerHandle(name, handle);
    }, Math.ceil(fadeSeconds * 1000) + 90);
  }

  destroyLayerHandle(name, expectedHandle) {
    const current = this.layerHandles[name];
    if (current !== expectedHandle || !expectedHandle) return;

    if (expectedHandle.stopTimer !== null) {
      clearTimeout(expectedHandle.stopTimer);
      expectedHandle.stopTimer = null;
    }

    for (const src of expectedHandle.stoppables) {
      try {
        src.stop();
      } catch {
        // Already stopped
      }
    }
    for (const node of expectedHandle.nodes) {
      try {
        node.disconnect();
      } catch {
        // Already disconnected
      }
    }

    this.layerHandles[name] = null;
  }

  createLayerHandle(name, now) {
    const ctx = this.ctx;
    const fadeGain = ctx.createGain();
    fadeGain.gain.setValueAtTime(0, now);

    if (name === 'rain' || name === 'night') {
      const bufferKey = name === 'rain' ? 'ambientRain' : 'ambientNight';
      const targetBus = name === 'rain' ? this.graph.rainBus : this.graph.nightBus;
      const buffer = this.buffers.get(bufferKey);

      if (buffer) {
        const src = ctx.createBufferSource();
        src.buffer = buffer;
        src.loop = true;
        src.connect(fadeGain);
        fadeGain.connect(targetBus);
        src.start(now);
        return { fadeGain, stoppables: [src], nodes: [src, fadeGain], stopTimer: null };
      }

      if (this.missingFiles.includes(AUDIO_LABELS[bufferKey])) {
        if (name === 'rain') {
          const src = ctx.createBufferSource();
          src.buffer = this.pinkNoiseBuffer;
          src.loop = true;
          const filter = ctx.createBiquadFilter();
          filter.type = 'lowpass';
          filter.frequency.setValueAtTime(750, now);
          const scaleGain = ctx.createGain();
          scaleGain.gain.setValueAtTime(0.42, now);
          src.connect(filter);
          filter.connect(scaleGain);
          scaleGain.connect(fadeGain);
          fadeGain.connect(targetBus);
          src.start(now);
          return {
            fadeGain,
            stoppables: [src],
            nodes: [src, filter, scaleGain, fadeGain],
            stopTimer: null,
          };
        }

        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(196, now);
        const scaleGain = ctx.createGain();
        scaleGain.gain.setValueAtTime(0.08, now);
        osc.connect(scaleGain);
        scaleGain.connect(fadeGain);
        fadeGain.connect(targetBus);
        osc.start(now);
        return {
          fadeGain,
          stoppables: [osc],
          nodes: [osc, scaleGain, fadeGain],
          stopTimer: null,
        };
      }
      return null;
    }

    if (name === 'pad') {
      const scale = SCALES[this.scale] || SCALES['c-major'];
      const chord = this.getCurrentChord();

      const padFilter = ctx.createBiquadFilter();
      padFilter.type = 'lowpass';
      padFilter.frequency.setValueAtTime(640, now);
      padFilter.Q.setValueAtTime(0.7, now);

      const padBreathGain = ctx.createGain();
      padBreathGain.gain.setValueAtTime(0.24, now);

      const filterLfo = ctx.createOscillator();
      filterLfo.type = 'sine';
      filterLfo.frequency.setValueAtTime(0.08, now);
      const filterLfoDepth = ctx.createGain();
      filterLfoDepth.gain.setValueAtTime(240, now);
      filterLfo.connect(filterLfoDepth);
      filterLfoDepth.connect(padFilter.frequency);

      const ampLfo = ctx.createOscillator();
      ampLfo.type = 'sine';
      ampLfo.frequency.setValueAtTime(0.062, now);
      const ampLfoDepth = ctx.createGain();
      ampLfoDepth.gain.setValueAtTime(0.06, now);
      ampLfo.connect(ampLfoDepth);
      ampLfoDepth.connect(padBreathGain.gain);

      const voiceOscs = [];
      const voiceNodes = [];

      chord.padSemitones.forEach((st, idx) => {
        const osc = ctx.createOscillator();
        osc.type = idx === 0 ? 'sine' : 'triangle';
        osc.frequency.setValueAtTime(scale.refFreq * semitonesToPlaybackRate(st), now);

        const voiceGain = ctx.createGain();
        voiceGain.gain.setValueAtTime(idx === 0 ? 0.36 : 0.22, now);

        osc.connect(voiceGain);
        voiceGain.connect(padFilter);
        osc.start(now);

        voiceOscs.push(osc);
        voiceNodes.push(osc, voiceGain);
      });

      padFilter.connect(padBreathGain);
      padBreathGain.connect(fadeGain);
      fadeGain.connect(this.graph.padBus);

      filterLfo.start(now);
      ampLfo.start(now);

      return {
        fadeGain,
        voiceOscs,
        stoppables: [...voiceOscs, filterLfo, ampLfo],
        nodes: [
          ...voiceNodes,
          padFilter,
          padBreathGain,
          filterLfo,
          filterLfoDepth,
          ampLfo,
          ampLfoDepth,
          fadeGain,
        ],
        stopTimer: null,
      };
    }

    if (name === 'wind') {
      const src = ctx.createBufferSource();
      src.buffer = this.pinkNoiseBuffer;
      src.loop = true;

      const windFilter = ctx.createBiquadFilter();
      windFilter.type = 'bandpass';
      windFilter.frequency.setValueAtTime(360, now);
      windFilter.Q.setValueAtTime(1.25, now);

      const windBreathGain = ctx.createGain();
      windBreathGain.gain.setValueAtTime(0.45, now);

      const filterLfo = ctx.createOscillator();
      filterLfo.type = 'sine';
      filterLfo.frequency.setValueAtTime(0.09, now);
      const filterLfoDepth = ctx.createGain();
      filterLfoDepth.gain.setValueAtTime(175, now);
      filterLfo.connect(filterLfoDepth);
      filterLfoDepth.connect(windFilter.frequency);

      const ampLfo = ctx.createOscillator();
      ampLfo.type = 'sine';
      ampLfo.frequency.setValueAtTime(0.055, now);
      const ampLfoDepth = ctx.createGain();
      ampLfoDepth.gain.setValueAtTime(0.24, now);
      ampLfo.connect(ampLfoDepth);
      ampLfoDepth.connect(windBreathGain.gain);

      src.connect(windFilter);
      windFilter.connect(windBreathGain);
      windBreathGain.connect(fadeGain);
      fadeGain.connect(this.graph.windBus);

      src.start(now);
      filterLfo.start(now);
      ampLfo.start(now);

      return {
        fadeGain,
        stoppables: [src, filterLfo, ampLfo],
        nodes: [
          src,
          windFilter,
          windBreathGain,
          filterLfo,
          filterLfoDepth,
          ampLfo,
          ampLfoDepth,
          fadeGain,
        ],
        stopTimer: null,
      };
    }

    return null;
  }

  glidePadToCurrentChord(timeConstant = 0.8) {
    if (!this.ctx || !this.layerHandles.pad || !this.layerHandles.pad.voiceOscs) return;
    const now = this.ctx.currentTime;
    const scale = SCALES[this.scale] || SCALES['c-major'];
    const chord = this.getCurrentChord();

    this.layerHandles.pad.voiceOscs.forEach((osc, idx) => {
      const st = chord.padSemitones[idx] ?? chord.padSemitones[0];
      const freq = scale.refFreq * semitonesToPlaybackRate(st);
      osc.frequency.cancelScheduledValues(now);
      osc.frequency.setTargetAtTime(freq, now, timeConstant);
    });
  }

  pruneActiveNotes(now) {
    for (const note of this.activeNotes) {
      if (now >= note.endTime) {
        this.activeNotes.delete(note);
      }
    }
  }

  stopAllNotes(fadeSeconds = 0.04) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    for (const note of this.activeNotes) {
      try {
        note.gainNode.gain.cancelScheduledValues(now);
        note.gainNode.gain.setValueAtTime(note.gainNode.gain.value, now);
        note.gainNode.gain.linearRampToValueAtTime(0, now + fadeSeconds);
        note.source.stop(now + fadeSeconds + 0.02);
      } catch {
        // Already stopped
      }
    }
    this.activeNotes.clear();
  }

  getActiveCounts() {
    if (this.ctx) {
      this.pruneActiveNotes(this.ctx.currentTime);
    }
    const activeLayers = Object.values(this.layerHandles).filter(Boolean).length;
    return {
      activeNotes: this.activeNotes.size,
      activeLayers,
    };
  }

  getEnergyLevel() {
    if (
      !this.ctx ||
      !this.graph ||
      !this.graph.analyser ||
      !this.energyData ||
      !this.isPlayingTree ||
      this.isPaused ||
      this.muted ||
      this.ctx.state !== 'running'
    ) {
      return 0;
    }

    this.graph.analyser.getByteTimeDomainData(this.energyData);
    let sumSq = 0;
    for (let i = 0; i < this.energyData.length; i++) {
      const sample = (this.energyData[i] - 128) / 128;
      sumSq += sample * sample;
    }
    const rms = Math.sqrt(sumSq / this.energyData.length);
    return clamp(rms * 4.2, 0, 1);
  }

  /**
   * Play a branch sound using the precomputed cycle schedule when active,
   * ensuring live playback matches offline WAV export.
   */
  playBranchEvent(branch, bounds, maxDepth, currentElapsedSec = null) {
    if (
      !this.ctx ||
      !this.graph ||
      !this.initialized ||
      !this.isPlayingTree ||
      this.isPaused ||
      this.ctx.state !== 'running'
    ) {
      return;
    }

    const now = this.ctx.currentTime;
    this.pruneActiveNotes(now);
    if (this.activeNotes.size >= MAX_SIMULTANEOUS_NOTES) {
      return;
    }

    let scheduledTime = now;
    let key = 'branch';
    let targetBus = this.graph.notesBus;
    let playbackRate = 1;
    let baseGain = 0.36;
    let noteDuration = 0.8;
    let attack = 0.035;
    let release = 0.35;
    let fallbackFreq = 261.63;

    if (this.currentCycleSchedule) {
      const planned = this.currentCycleSchedule.notesByBranchId.get(branch.id);
      if (!planned) {
        return;
      }

      const wallPos =
        currentElapsedSec !== null
          ? currentElapsedSec / this.scheduleSpeed
          : branch.startTime / this.scheduleSpeed;
      const offsetFromNow = clamp(planned.time - wallPos, 0.005, 0.25);
      scheduledTime = now + offsetFromNow;
      key = planned.key;
      targetBus = planned.busName === 'leavesBus' ? this.graph.leavesBus : this.graph.notesBus;
      playbackRate = planned.playbackRate;
      baseGain = planned.gainAmount;
      noteDuration = planned.noteDuration;
      attack = planned.attack;
      release = planned.release;
      fallbackFreq = planned.fallbackFreq;
      this.lastScheduledTime = scheduledTime;
      var pan = planned.pan;
    } else {
      const beatSeconds = 60 / this.activeTempo;
      const gridStep = beatSeconds / 4;
      const minGap = clamp(beatSeconds * 0.16, 0.1, 0.22);
      const isTrunk = branch.side === 'trunk' && branch.depth === 1;

      if (!isTrunk) {
        const stepsAhead = Math.max(0, Math.ceil((now - this.gridOrigin) / gridStep));
        let quantized = this.gridOrigin + stepsAhead * gridStep;
        if (quantized - this.lastScheduledTime < minGap) {
          const nextSlot = quantized + gridStep;
          if (
            nextSlot - this.lastScheduledTime >= minGap &&
            nextSlot - now <= gridStep * 1.6
          ) {
            quantized = nextSlot;
          } else {
            return;
          }
        }
        scheduledTime = Math.max(now + 0.005, quantized);
      }

      this.lastScheduledTime = scheduledTime;
      const scaleDef = SCALES[this.scale] || SCALES['c-major'];
      const currentChord = this.getCurrentChord();

      if (isTrunk) {
        key = 'trunk';
        baseGain = 0.45;
        noteDuration = 1.25;
        attack = 0.055;
        release = 0.5;
        fallbackFreq = scaleDef.trunkFreq;
      } else if (branch.isLeaf) {
        key = 'leaf';
        targetBus = this.graph.leavesBus;
        baseGain = 0.12 * Math.pow(0.92, Math.max(0, branch.depth - 1));
        noteDuration = 0.65;
        attack = 0.045;
        release = 0.36;
        fallbackFreq = scaleDef.leafFreq;
      } else {
        const semitones = getBranchPentatonicSemitones(
          branch.depth,
          maxDepth,
          branch.side,
          this.scale,
          currentChord.pitchClasses
        );
        playbackRate = semitonesToPlaybackRate(semitones);
        baseGain = 0.36 * Math.pow(0.84, Math.max(0, branch.depth - 2));
        noteDuration = Math.max(0.55, 0.85 - Math.max(0, branch.depth - 2) * 0.04);
        fallbackFreq = scaleDef.refFreq * playbackRate;
      }

      const halfSpan = Math.max(20, Math.abs(bounds.minX), Math.abs(bounds.maxX));
      var pan = isTrunk ? 0 : clamp(branch.endX / halfSpan, -0.85, 0.85);
    }

    const buffer = this.buffers.get(key);
    if (buffer) {
      this.triggerSampleNote({
        buffer,
        offset: this.activeOffsets.get(key) || 0,
        when: scheduledTime,
        playbackRate,
        gainAmount: baseGain,
        pan,
        noteDuration,
        attack,
        release,
        targetBus,
      });
    } else if (this.missingFiles.includes(AUDIO_LABELS[key]) || !this.loadingPromises.has(key)) {
      this.triggerSynthFallbackNote({
        when: scheduledTime,
        frequency: fallbackFreq,
        gainAmount: baseGain * 0.45,
        pan,
        noteDuration,
        attack,
        release,
        isLeaf: branch.isLeaf,
        targetBus,
      });
    } else {
      const triggeredAt = now;
      const epoch = this.transportEpoch;
      this.loadingPromises.get(key).then(() => {
        if (
          epoch !== this.transportEpoch ||
          !this.ctx ||
          !this.isPlayingTree ||
          this.isPaused ||
          this.ctx.state !== 'running'
        ) {
          return;
        }
        const currentNow = this.ctx.currentTime;
        if (currentNow - triggeredAt > 1.2) return;
        this.pruneActiveNotes(currentNow);
        if (this.activeNotes.size >= MAX_SIMULTANEOUS_NOTES) return;

        const decoded = this.buffers.get(key);
        if (decoded) {
          this.triggerSampleNote({
            buffer: decoded,
            offset: this.activeOffsets.get(key) || 0,
            when: currentNow + 0.01,
            playbackRate,
            gainAmount: baseGain,
            pan,
            noteDuration,
            attack,
            release,
            targetBus,
          });
        } else {
          this.triggerSynthFallbackNote({
            when: currentNow + 0.01,
            frequency: fallbackFreq,
            gainAmount: baseGain * 0.45,
            pan,
            noteDuration,
            attack,
            release,
            isLeaf: branch.isLeaf,
            targetBus,
          });
        }
      });
    }
  }

  triggerSampleNote({
    buffer,
    offset,
    when,
    playbackRate,
    gainAmount,
    pan,
    noteDuration,
    attack,
    release,
    targetBus,
  }) {
    const ctx = this.ctx;
    const maxPlayable = Math.max(0.12, (buffer.duration - offset) / playbackRate - 0.02);
    const dur = Math.min(noteDuration, maxPlayable);
    const safeAttack = Math.min(attack, dur * 0.35);
    const safeRelease = Math.min(release, dur * 0.6);
    const releaseStart = Math.max(when + safeAttack, when + dur - safeRelease);
    const endTime = when + dur;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.setValueAtTime(playbackRate, when);

    const gainNode = ctx.createGain();
    gainNode.gain.setValueAtTime(0, when);
    gainNode.gain.linearRampToValueAtTime(gainAmount, when + safeAttack);
    gainNode.gain.setValueAtTime(gainAmount, releaseStart);
    gainNode.gain.linearRampToValueAtTime(0, endTime);

    const panner = ctx.createStereoPanner();
    panner.pan.setValueAtTime(pan, when);

    source.connect(gainNode);
    gainNode.connect(panner);
    panner.connect(targetBus);

    const record = { source, gainNode, panner, endTime };
    this.activeNotes.add(record);
    source.onended = () => {
      this.activeNotes.delete(record);
      try {
        source.disconnect();
        gainNode.disconnect();
        panner.disconnect();
      } catch {
        // Already disconnected
      }
    };

    source.start(when, offset);
    source.stop(endTime + 0.02);
  }

  triggerSynthFallbackNote({
    when,
    frequency,
    gainAmount,
    pan,
    noteDuration,
    attack,
    release,
    isLeaf,
    targetBus,
  }) {
    const ctx = this.ctx;
    const dur = noteDuration;
    const safeAttack = Math.min(attack, dur * 0.35);
    const safeRelease = Math.min(release, dur * 0.6);
    const releaseStart = Math.max(when + safeAttack, when + dur - safeRelease);
    const endTime = when + dur;

    const osc = ctx.createOscillator();
    osc.type = isLeaf ? 'sine' : 'triangle';
    osc.frequency.setValueAtTime(frequency, when);

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(isLeaf ? 2200 : 1400, when);

    const gainNode = ctx.createGain();
    gainNode.gain.setValueAtTime(0, when);
    gainNode.gain.linearRampToValueAtTime(gainAmount, when + safeAttack);
    gainNode.gain.setValueAtTime(gainAmount * 0.85, releaseStart);
    gainNode.gain.linearRampToValueAtTime(0, endTime);

    const panner = ctx.createStereoPanner();
    panner.pan.setValueAtTime(pan, when);

    osc.connect(filter);
    filter.connect(gainNode);
    gainNode.connect(panner);
    panner.connect(targetBus);

    const record = { source: osc, gainNode, panner, endTime };
    this.activeNotes.add(record);
    osc.onended = () => {
      this.activeNotes.delete(record);
      try {
        osc.disconnect();
        filter.disconnect();
        gainNode.disconnect();
        panner.disconnect();
      } catch {
        // Already disconnected
      }
    };

    osc.start(when);
    osc.stop(endTime + 0.02);
  }
}

args.Replacement:
.layer-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: rgba(4, 15, 22, 0.56);
  border: 1px solid rgba(128, 214, 194, 0.12);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.export-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(128, 214, 194, 0.12);
}

.export-row {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.btn-export {
  width: 100%;
}

.export-progress-wrap {
  width: 100%;
}

.audio-notice.is-success {
  background: rgba(14, 54, 46, 0.65);
  border-color: rgba(124, 232, 200, 0.45);
  color: var(--accent-strong);
}

args.Target:
.layer-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: rgba(4, 15, 22, 0.56);
  border: 1px solid rgba(128, 214, 194, 0.12);
}

args.Content:
import { generateFractalTree, getTreeBounds, getTreeTotalDuration } from './tree.js';
import { TreeRenderer } from './renderer.js';
import { GardenAudio } from './audio.js';
import { renderCompositionWav, triggerBlobDownload } from './audio-export.js';

const DEFAULTS = {
  depth: 7,
  branchAngle: 25,
  lengthRatio: 0.72,
  randomness: 0.2,
  speed: 1.0,
  seed: 4217,
  scale: 'c-major',
  tempo: 70,
  reverbPreset: 'forest',
  reverb: 0.42,
  masterVolume: 0.8,
  notesVolume: 0.8,
  leavesVolume: 0.7,
  ambientVolume: 0.52,
  layers: {
    rain: { enabled: true, volume: 0.48 },
    night: { enabled: true, volume: 0.52 },
    pad: { enabled: true, volume: 0.46 },
    wind: { enabled: true, volume: 0.36 },
  },
};

const PRESETS = {
  'calm-rain': {
    depth: 6,
    branchAngle: 22,
    lengthRatio: 0.72,
    randomness: 0.15,
    speed: 0.9,
    scale: 'c-major',
    tempo: 66,
    reverbPreset: 'small-garden',
    reverb: 0.42,
    masterVolume: 0.8,
    notesVolume: 0.82,
    leavesVolume: 0.72,
    ambientVolume: 0.58,
    layers: {
      rain: { enabled: true, volume: 0.72 },
      night: { enabled: false, volume: 0.3 },
      pad: { enabled: true, volume: 0.42 },
      wind: { enabled: true, volume: 0.28 },
    },
  },
  'moonlit-night': {
    depth: 8,
    branchAngle: 32,
    lengthRatio: 0.74,
    randomness: 0.3,
    speed: 1.0,
    scale: 'a-minor',
    tempo: 62,
    reverbPreset: 'open-sky',
    reverb: 0.62,
    masterVolume: 0.8,
    notesVolume: 0.78,
    leavesVolume: 0.78,
    ambientVolume: 0.55,
    layers: {
      rain: { enabled: false, volume: 0.35 },
      night: { enabled: true, volume: 0.72 },
      pad: { enabled: true, volume: 0.55 },
      wind: { enabled: true, volume: 0.35 },
    },
  },
  'deep-forest': {
    depth: 9,
    branchAngle: 36,
    lengthRatio: 0.76,
    randomness: 0.45,
    speed: 0.8,
    scale: 'a-minor',
    tempo: 56,
    reverbPreset: 'forest',
    reverb: 0.68,
    masterVolume: 0.82,
    notesVolume: 0.76,
    leavesVolume: 0.7,
    ambientVolume: 0.6,
    layers: {
      rain: { enabled: true, volume: 0.52 },
      night: { enabled: true, volume: 0.64 },
      pad: { enabled: true, volume: 0.58 },
      wind: { enabled: true, volume: 0.56 },
    },
  },
};

const LOOP_HOLD_MS = 2200;

const canvas = document.getElementById('garden-canvas');
const playPauseBtn = document.getElementById('play-pause-btn');
const stopBtn = document.getElementById('stop-btn');
const restartBtn = document.getElementById('restart-btn');
const loopBtn = document.getElementById('loop-btn');

const progressBar = document.getElementById('progress-bar');
const progressFill = document.getElementById('progress-fill');
const timeReadout = document.getElementById('time-readout');

const presetButtons = Array.from(document.querySelectorAll('[data-preset]'));
const resetDefaultsBtn = document.getElementById('reset-defaults-btn');

const depthInput = document.getElementById('depth-input');
const angleInput = document.getElementById('angle-input');
const ratioInput = document.getElementById('ratio-input');
const randomnessInput = document.getElementById('randomness-input');
const speedInput = document.getElementById('speed-input');
const seedInput = document.getElementById('seed-input');
const newSeedBtn = document.getElementById('new-seed-btn');

const scaleSelect = document.getElementById('scale-select');
const tempoInput = document.getElementById('tempo-input');
const reverbInput = document.getElementById('reverb-input');
const reverbPresetButtons = Array.from(document.querySelectorAll('[data-reverb-preset]'));

const muteBtn = document.getElementById('mute-btn');
const masterVolInput = document.getElementById('master-vol-input');
const notesVolInput = document.getElementById('notes-vol-input');
const leavesVolInput = document.getElementById('leaves-vol-input');
const ambientVolInput = document.getElementById('ambient-vol-input');

const exportLengthSelect = document.getElementById('export-length-select');
const downloadWavBtn = document.getElementById('download-wav-btn');
const exportProgressWrap = document.getElementById('export-progress-wrap');
const exportProgressFill = document.getElementById('export-progress-fill');
const exportStatus = document.getElementById('export-status');

const layerControls = {
  rain: {
    toggle: document.getElementById('rain-toggle'),
    input: document.getElementById('rain-vol-input'),
    output: document.getElementById('rain-vol-value'),
  },
  night: {
    toggle: document.getElementById('night-toggle'),
    input: document.getElementById('night-vol-input'),
    output: document.getElementById('night-vol-value'),
  },
  pad: {
    toggle: document.getElementById('pad-toggle'),
    input: document.getElementById('pad-vol-input'),
    output: document.getElementById('pad-vol-value'),
  },
  wind: {
    toggle: document.getElementById('wind-toggle'),
    input: document.getElementById('wind-vol-input'),
    output: document.getElementById('wind-vol-value'),
  },
};

const depthValue = document.getElementById('depth-value');
const angleValue = document.getElementById('angle-value');
const ratioValue = document.getElementById('ratio-value');
const randomnessValue = document.getElementById('randomness-value');
const speedValue = document.getElementById('speed-value');
const tempoValue = document.getElementById('tempo-value');
const reverbValue = document.getElementById('reverb-value');
const masterVolValue = document.getElementById('master-vol-value');
const notesVolValue = document.getElementById('notes-vol-value');
const leavesVolValue = document.getElementById('leaves-vol-value');
const ambientVolValue = document.getElementById('ambient-vol-value');

const statusText = document.getElementById('status-text');
const statusDot = document.getElementById('status-dot');
const treeMeta = document.getElementById('tree-meta');
const audioStatus = document.getElementById('audio-status');

const params = {
  depth: Number(depthInput.value),
  branchAngle: Number(angleInput.value),
  lengthRatio: Number(ratioInput.value),
  randomness: Number(randomnessInput.value),
  speed: Number(speedInput.value),
  seed: Number(seedInput.value),
};

let currentEvents = [];
let currentBounds = { minX: 0, maxX: 0, minY: 0, maxY: 0, width: 0, height: 0 };
let leafCount = 0;
let loopEnabled = false;
let loopHoldTimer = null;
let activePresetId = null;
let isExporting = false;
const triggeredBranchIds = new Set();

const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
let isReducedMotion = motionQuery.matches;

const audio = new GardenAudio({
  onStatusChange: ({ missing, message }) => {
    audioStatus.textContent = message;
    audioStatus.classList.toggle('is-warning', missing.length > 0);
  },
});

const renderer = new TreeRenderer(canvas, {
  onStateChange: handleRendererStateChange,
  onProgress: handleGrowthProgress,
  getAudioLevel: () => audio.getEnergyLevel(),
});

function formatTime(seconds) {
  const safe = Math.max(0, Number.isFinite(seconds) ? seconds : 0);
  const mins = Math.floor(safe / 60);
  const secs = (safe % 60).toFixed(1).padStart(4, '0');
  return `${mins}:${secs}`;
}

function clearLoopTimer() {
  if (loopHoldTimer !== null) {
    clearTimeout(loopHoldTimer);
    loopHoldTimer = null;
  }
}

function handleGrowthProgress(elapsed, prevElapsed, state) {
  if (!audio.initialized || !audio.isPlayingTree || audio.isPaused) return;

  const progress = renderer.totalDuration > 0 ? Math.min(1, elapsed / renderer.totalDuration) : 1;
  audio.updateGrowthProgress(progress);

  for (const branch of currentEvents) {
    if (branch.startTime > elapsed) {
      break;
    }
    if (triggeredBranchIds.has(branch.id)) {
      continue;
    }
    if (branch.startTime >= prevElapsed - 0.08) {
      triggeredBranchIds.add(branch.id);
      audio.playBranchEvent(branch, currentBounds, params.depth, elapsed);
    } else {
      triggeredBranchIds.add(branch.id);
    }
  }

  if (state === 'complete') {
    audio.completeGrowth();
  }
}

function handleRendererStateChange(state, progress) {
  updatePlaybackUI(state, progress);

  if (state === 'complete' && loopEnabled && !isReducedMotion) {
    clearLoopTimer();
    statusText.textContent = 'Full bloom · looping…';
    loopHoldTimer = setTimeout(() => {
      loopHoldTimer = null;
      if (loopEnabled && renderer.state === 'complete') {
        startPlayback({ keepAmbient: true });
      }
    }, LOOP_HOLD_MS);
  }
}

function updateReadouts() {
  depthValue.textContent = String(params.depth);
  angleValue.textContent = `${params.branchAngle}°`;
  ratioValue.textContent = params.lengthRatio.toFixed(2);
  randomnessValue.textContent = params.randomness.toFixed(2);
  speedValue.textContent = `${params.speed.toFixed(1)}x`;

  tempoValue.textContent = `${audio.pendingTempo} BPM`;
  reverbValue.textContent = `${Math.round(audio.reverbAmount * 100)}%`;

  const displayMaster = audio.muted ? 0 : audio.masterVolume;
  masterVolValue.textContent = `${Math.round(displayMaster * 100)}%`;
  notesVolValue.textContent = `${Math.round(audio.notesVolume * 100)}%`;
  leavesVolValue.textContent = `${Math.round(audio.leavesVolume * 100)}%`;
  ambientVolValue.textContent = `${Math.round(audio.ambientVolume * 100)}%`;

  for (const name of ['rain', 'night', 'pad', 'wind']) {
    layerControls[name].output.textContent = `${Math.round(audio.layers[name].volume * 100)}%`;
  }
}

function updateToggleButtons() {
  muteBtn.setAttribute('aria-pressed', String(audio.muted));
  muteBtn.textContent = audio.muted ? 'Muted' : 'Mute';
  muteBtn.classList.toggle('is-muted', audio.muted);

  loopBtn.setAttribute('aria-pressed', String(loopEnabled));
  loopBtn.textContent = loopEnabled ? 'Loop: On' : 'Loop: Off';
  loopBtn.classList.toggle('is-active', loopEnabled);

  for (const btn of reverbPresetButtons) {
    const active = btn.dataset.reverbPreset === audio.reverbPreset;
    btn.setAttribute('aria-pressed', String(active));
    btn.classList.toggle('is-active', active);
  }

  for (const name of ['rain', 'night', 'pad', 'wind']) {
    const enabled = audio.layers[name].enabled;
    const btn = layerControls[name].toggle;
    btn.setAttribute('aria-pressed', String(enabled));
    btn.textContent = enabled ? 'On' : 'Off';
    btn.classList.toggle('is-active', enabled);
  }

  for (const btn of presetButtons) {
    btn.classList.toggle('is-active', btn.dataset.preset === activePresetId);
  }
}

function updateTreeMeta() {
  const totalBranches = currentEvents.length;
  const durationSec = (getTreeTotalDuration(currentEvents) / params.speed).toFixed(1);
  const branchLabel = totalBranches === 1 ? 'branch' : 'branches';
  const leafLabel = leafCount === 1 ? 'leaf' : 'leaves';
  treeMeta.textContent = `${totalBranches} ${branchLabel} · ${leafCount} ${leafLabel} · ${durationSec}s`;
}

function updatePlaybackUI(state, progress) {
  statusDot.dataset.state = state;

  const totalSec = getTreeTotalDuration(currentEvents) / params.speed;
  const elapsedSec =
    state === 'preview' || state === 'idle'
      ? 0
      : state === 'complete'
        ? totalSec
        : renderer.elapsed / params.speed;
  const pct = Math.round(
    state === 'preview' || state === 'idle' ? 0 : progress * 100
  );

  progressFill.style.width = `${pct}%`;
  progressBar.setAttribute('aria-valuenow', String(pct));
  timeReadout.textContent = `${formatTime(elapsedSec)} / ${formatTime(totalSec)}`;

  if (isReducedMotion) {
    playPauseBtn.textContent = 'Play';
    playPauseBtn.disabled = false;
    stopBtn.disabled = state === 'idle';
    statusText.textContent =
      state === 'idle' ? 'Stopped (reduced motion)' : `Static preview · ${currentEvents.length} branches`;
    return;
  }

  switch (state) {
    case 'growing':
      playPauseBtn.textContent = 'Pause';
      stopBtn.disabled = false;
      statusText.textContent = `Playing… ${pct}%`;
      break;
    case 'paused':
      playPauseBtn.textContent = 'Resume';
      stopBtn.disabled = false;
      statusText.textContent = `Paused · ${pct}%`;
      break;
    case 'complete':
      playPauseBtn.textContent = 'Play';
      stopBtn.disabled = false;
      statusText.textContent = `Full bloom · ${currentEvents.length} branches`;
      break;
    case 'preview':
      playPauseBtn.textContent = 'Play';
      stopBtn.disabled = false;
      statusText.textContent = `Preview · ${currentEvents.length} branches`;
      break;
    case 'idle':
    default:
      playPauseBtn.textContent = 'Play';
      stopBtn.disabled = true;
      statusText.textContent = 'Stopped';
      break;
  }
}

function previewTreeChanges() {
  clearLoopTimer();
  audio.stop();
  triggeredBranchIds.clear();

  audio.setSeed(params.seed);
  currentEvents = generateFractalTree({
    depth: params.depth,
    branchAngle: params.branchAngle,
    lengthRatio: params.lengthRatio,
    randomness: params.randomness,
    seed: params.seed,
  });

  currentBounds = getTreeBounds(currentEvents);
  leafCount = currentEvents.reduce((count, branch) => count + (branch.isLeaf ? 1 : 0), 0);

  updateReadouts();
  updateTreeMeta();
  renderer.showPreview(currentEvents, params.depth);
}

function startPlayback({ keepAmbient = false } = {}) {
  clearLoopTimer();
  triggeredBranchIds.clear();
  audio.startGrowth({
    keepAmbient,
    events: currentEvents,
    bounds: currentBounds,
    maxDepth: params.depth,
    speed: params.speed,
    seed: params.seed,
  });
  renderer.grow();
}

function handlePlayPause() {
  clearLoopTimer();

  if (isReducedMotion) {
    startPlayback();
    return;
  }

  if (renderer.state === 'growing') {
    renderer.togglePause();
    audio.pause();
  } else if (renderer.state === 'paused') {
    renderer.togglePause();
    audio.resume();
  } else {
    startPlayback();
  }
}

function handleStop() {
  clearLoopTimer();
  triggeredBranchIds.clear();
  audio.stop();
  renderer.reset();
}

function handleRestart() {
  startPlayback();
}

function pickNewSeed() {
  let nextSeed = Math.floor(Math.random() * 999999) + 1;
  if (nextSeed === params.seed) {
    nextSeed = (nextSeed % 999999) + 1;
  }
  activePresetId = null;
  params.seed = nextSeed;
  seedInput.value = String(nextSeed);
  updateToggleButtons();
  previewTreeChanges();
}

function applyConfiguration(config, presetId) {
  activePresetId = presetId;

  params.depth = config.depth;
  params.branchAngle = config.branchAngle;
  params.lengthRatio = config.lengthRatio;
  params.randomness = config.randomness;
  params.speed = config.speed;
  if (config.seed !== undefined) {
    params.seed = config.seed;
    seedInput.value = String(config.seed);
  }

  depthInput.value = String(params.depth);
  angleInput.value = String(params.branchAngle);
  ratioInput.value = String(params.lengthRatio);
  randomnessInput.value = String(params.randomness);
  speedInput.value = String(params.speed);
  renderer.setSpeed(params.speed);

  scaleSelect.value = config.scale;
  audio.setScale(config.scale);

  tempoInput.value = String(config.tempo);
  audio.setTempo(config.tempo);

  audio.setReverbPreset(config.reverbPreset);
  reverbInput.value = String(config.reverb);
  audio.setReverbAmount(config.reverb);

  masterVolInput.value = String(config.masterVolume);
  audio.setMasterVolume(config.masterVolume);

  notesVolInput.value = String(config.notesVolume);
  audio.setNotesVolume(config.notesVolume);

  leavesVolInput.value = String(config.leavesVolume);
  audio.setLeavesVolume(config.leavesVolume);

  ambientVolInput.value = String(config.ambientVolume);
  audio.setAmbientVolume(config.ambientVolume);

  for (const name of ['rain', 'night', 'pad', 'wind']) {
    const layerCfg = config.layers[name];
    audio.setLayerEnabled(name, layerCfg.enabled);
    audio.setLayerVolume(name, layerCfg.volume);
    layerControls[name].input.value = String(layerCfg.volume);
  }

  if (config.loop !== undefined) {
    loopEnabled = config.loop;
  }
  if (config.muted === false) {
    audio.setMuted(false);
  }

  updateToggleButtons();
  previewTreeChanges();
}

async function handleToggleMute() {
  await audio.unlock();
  const nextSliderVal = audio.setMuted(!audio.muted);
  masterVolInput.value = String(nextSliderVal);
  updateToggleButtons();
  updateReadouts();
}

function setExportFeedback(message, type = 'info') {
  exportStatus.hidden = !message;
  exportStatus.textContent = message;
  exportStatus.classList.toggle('is-warning', type === 'warning');
  exportStatus.classList.toggle('is-success', type === 'success');
}

/**
 * Render and download the current composition as a 16-bit 44.1 kHz stereo WAV.
 */
async function handleDownloadWav() {
  if (isExporting) return;

  // Use unmuted volume so muting during playback doesn't export silence by accident
  const exportMasterVolume = audio.muted ? audio.preMuteVolume : audio.masterVolume;
  const hasEnabledAmbient =
    audio.ambientVolume > 0 &&
    ['rain', 'night', 'pad', 'wind'].some(
      (k) => audio.layers[k].enabled && audio.layers[k].volume > 0
    );
  const hasAudibleNotes = audio.notesVolume > 0 || audio.leavesVolume > 0;

  if (exportMasterVolume <= 0 || (!hasAudibleNotes && !hasEnabledAmbient)) {
    setExportFeedback(
      'Volume is 0%. Raise Master or at least one active sound slider before downloading.',
      'warning'
    );
    return;
  }

  isExporting = true;
  downloadWavBtn.disabled = true;
  exportLengthSelect.disabled = true;
  exportProgressWrap.hidden = false;
  exportProgressFill.style.width = '4%';

  const muteNote = audio.muted
    ? ` (exported at ${Math.round(exportMasterVolume * 100)}% unmuted volume)`
    : '';

  setExportFeedback('Preparing your music… 0%', 'info');

  try {
    const result = await renderCompositionWav({
      events: currentEvents,
      bounds: currentBounds,
      maxDepth: params.depth,
      speed: params.speed,
      seed: params.seed,
      tempo: audio.pendingTempo,
      scale: audio.scale,
      reverbPreset: audio.reverbPreset,
      reverbAmount: audio.reverbAmount,
      masterVolume: exportMasterVolume,
      notesVolume: audio.notesVolume,
      leavesVolume: audio.leavesVolume,
      ambientVolume: audio.ambientVolume,
      layers: audio.layers,
      lengthMode: exportLengthSelect.value,
      onProgress: (pct) => {
        exportProgressFill.style.width = `${pct}%`;
        setExportFeedback(`Preparing your music… ${pct}%`, 'info');
      },
    });

    if (result.isSilent) {
      setExportFeedback(
        'Rendered audio is silent — check that volume sliders are above 0%.',
        'warning'
      );
      return;
    }

    triggerBlobDownload(result.blob, result.fileName);

    const missingNote =
      result.missing.length > 0
        ? ` Fallback synthesis used for missing: ${result.missing.join(', ')}.`
        : '';

    setExportFeedback(
      `Downloaded ${result.fileName} (${result.duration.toFixed(1)}s, 44.1 kHz 16-bit WAV)${muteNote}.${missingNote}`,
      'success'
    );
  } catch (err) {
    setExportFeedback(
      `Export failed: ${err && err.message ? err.message : 'Unable to render WAV.'}`,
      'warning'
    );
  } finally {
    isExporting = false;
    downloadWavBtn.disabled = false;
    exportLengthSelect.disabled = false;
    exportProgressWrap.hidden = true;
    exportProgressFill.style.width = '0%';
  }
}

// Playback & Export listeners
playPauseBtn.addEventListener('click', handlePlayPause);
stopBtn.addEventListener('click', handleStop);
restartBtn.addEventListener('click', handleRestart);
downloadWavBtn.addEventListener('click', handleDownloadWav);

loopBtn.addEventListener('click', () => {
  loopEnabled = !loopEnabled;
  if (!loopEnabled) {
    clearLoopTimer();
  } else if (renderer.state === 'complete' && !isReducedMotion) {
    handleRendererStateChange('complete', 1);
  }
  updateToggleButtons();
});

// Presets
for (const btn of presetButtons) {
  btn.addEventListener('click', () => {
    const id = btn.dataset.preset;
    if (PRESETS[id]) {
      applyConfiguration(PRESETS[id], id);
    }
  });
}

resetDefaultsBtn.addEventListener('click', () => {
  applyConfiguration({ ...DEFAULTS, loop: false, muted: false }, null);
});

// Tree sliders
depthInput.addEventListener('input', () => {
  activePresetId = null;
  params.depth = Number(depthInput.value);
  updateToggleButtons();
  previewTreeChanges();
});

angleInput.addEventListener('input', () => {
  activePresetId = null;
  params.branchAngle = Number(angleInput.value);
  updateToggleButtons();
  previewTreeChanges();
});

ratioInput.addEventListener('input', () => {
  activePresetId = null;
  params.lengthRatio = Number(ratioInput.value);
  updateToggleButtons();
  previewTreeChanges();
});

randomnessInput.addEventListener('input', () => {
  activePresetId = null;
  params.randomness = Number(randomnessInput.value);
  updateToggleButtons();
  previewTreeChanges();
});

speedInput.addEventListener('input', () => {
  activePresetId = null;
  params.speed = Number(speedInput.value);
  renderer.setSpeed(params.speed);
  updateToggleButtons();
  updateReadouts();
  updateTreeMeta();
  updatePlaybackUI(
    renderer.state,
    renderer.totalDuration > 0 ? renderer.elapsed / renderer.totalDuration : 0
  );
});

seedInput.addEventListener('input', () => {
  const raw = seedInput.value.trim();
  if (raw === '') return;
  const parsed = Math.trunc(Number(raw));
  if (Number.isFinite(parsed) && parsed >= 0) {
    activePresetId = null;
    params.seed = Math.min(999999, parsed);
    updateToggleButtons();
    previewTreeChanges();
  }
});

seedInput.addEventListener('change', () => {
  const raw = seedInput.value.trim();
  const parsed = Math.trunc(Number(raw));
  if (raw === '' || !Number.isFinite(parsed) || parsed < 0) {
    seedInput.value = String(params.seed);
  } else {
    activePresetId = null;
    params.seed = Math.min(999999, parsed);
    seedInput.value = String(params.seed);
    updateToggleButtons();
    previewTreeChanges();
  }
});

newSeedBtn.addEventListener('click', pickNewSeed);

// Music controls
scaleSelect.addEventListener('change', () => {
  activePresetId = null;
  audio.setScale(scaleSelect.value);
  updateToggleButtons();
});

tempoInput.addEventListener('input', () => {
  activePresetId = null;
  audio.setTempo(Number(tempoInput.value));
  updateToggleButtons();
  updateReadouts();
});

reverbInput.addEventListener('input', async () => {
  activePresetId = null;
  await audio.unlock();
  audio.setReverbAmount(Number(reverbInput.value));
  updateToggleButtons();
  updateReadouts();
});

for (const btn of reverbPresetButtons) {
  btn.addEventListener('click', async () => {
    activePresetId = null;
    await audio.unlock();
    audio.setReverbPreset(btn.dataset.reverbPreset);
    updateToggleButtons();
  });
}

// Volume & independent ambient layer controls
muteBtn.addEventListener('click', handleToggleMute);

masterVolInput.addEventListener('input', async () => {
  activePresetId = null;
  await audio.unlock();
  audio.setMasterVolume(Number(masterVolInput.value));
  updateToggleButtons();
  updateReadouts();
});

notesVolInput.addEventListener('input', async () => {
  activePresetId = null;
  await audio.unlock();
  audio.setNotesVolume(Number(notesVolInput.value));
  updateToggleButtons();
  updateReadouts();
});

