args.Content:
:root {
  --bg-deep: #041019;
  --bg-mid: #09222e;
  --bg-panel: rgba(8, 25, 34, 0.88);
  --bg-elevated: rgba(16, 44, 56, 0.78);
  --border-subtle: rgba(128, 214, 194, 0.2);
  --border-focus: #8cf2d3;

  --text-primary: #eaf7f4;
  --text-secondary: #b4d4ce;
  --text-muted: #8fb8b0;

  --accent: #7ce8c8;
  --accent-strong: #a6fae0;
  --accent-text: #041b17;

  --radius-lg: 20px;
  --radius-md: 11px;
  --radius-sm: 8px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: linear-gradient(160deg, var(--bg-deep) 0%, var(--bg-mid) 58%, #0e2e39 100%);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.44;
  -webkit-font-smoothing: antialiased;
}

/* Welcome Screen */
.welcome-overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: radial-gradient(circle at 50% 40%, rgba(9, 34, 46, 0.72), rgba(3, 12, 18, 0.9));
  backdrop-filter: blur(10px);
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.welcome-overlay[hidden] {
  display: none;
}

.welcome-card {
  width: 100%;
  max-width: 460px;
  padding: 30px 28px;
  border-radius: var(--radius-lg);
  background: rgba(7, 23, 32, 0.9);
  border: 1px solid rgba(128, 214, 194, 0.28);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

.welcome-kicker {
  margin: 0;
  font-size: 0.76rem;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
}

.welcome-card h1 {
  margin: 0;
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.welcome-desc {
  margin: 0;
  font-size: 0.98rem;
  color: var(--text-secondary);
  max-width: 38ch;
}

.welcome-highlights {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 4px 0;
}

.welcome-chip {
  font-size: 0.78rem;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(124, 232, 200, 0.12);
  border: 1px solid rgba(124, 232, 200, 0.25);
  color: var(--accent-strong);
}

.btn-welcome {
  width: 100%;
  max-width: 260px;
  min-height: 48px;
  font-size: 1rem;
  margin-top: 4px;
}

.welcome-note {
  margin: 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* App Shell & Stage */
.app-shell {
  display: flex;
  flex-direction: row;
  height: 100dvh;
  width: 100%;
  overflow: hidden;
}

.garden-stage {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  background: var(--bg-deep);
}

#garden-canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.stage-overlay-left {
  position: absolute;
  top: 14px;
  left: 14px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  pointer-events: none;
  z-index: 2;
  max-width: calc(100% - 28px);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(5, 19, 27, 0.78);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(10px);
  color: var(--text-secondary);
  font-size: 0.84rem;
  font-weight: 500;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--text-muted);
  transition: background-color 0.25s ease, box-shadow 0.25s ease;
}

.status-dot[data-state="growing"] {
  background: var(--accent);
  box-shadow: 0 0 8px rgba(124, 232, 200, 0.85);
}

.status-dot[data-state="paused"] {
  background: #ebd089;
  box-shadow: 0 0 6px rgba(235, 208, 137, 0.65);
}

.status-dot[data-state="complete"] {
  background: #a5f5be;
  box-shadow: 0 0 8px rgba(165, 245, 190, 0.75);
}

.live-readout {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  padding: 7px 12px;
  border-radius: var(--radius-md);
  background: rgba(5, 19, 27, 0.72);
  border: 1px solid rgba(128, 214, 194, 0.16);
  backdrop-filter: blur(10px);
}

.readout-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.readout-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.readout-val {
  font-variant-numeric: tabular-nums;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-primary);
}

.readout-sound .readout-val {
  color: var(--accent-strong);
}

.stage-toolbar {
  position: absolute;
  top: 14px;
  right: 14px;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  z-index: 4;
}

.btn-toolbar {
  min-height: 44px;
  padding: 8px 13px;
  border-radius: 999px;
  background: rgba(6, 22, 31, 0.82);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(10px);
  color: var(--text-primary);
  font-size: 0.82rem;
  font-weight: 600;
}

.btn-toolbar:hover:not(:disabled) {
  background: rgba(20, 54, 68, 0.92);
  border-color: rgba(124, 232, 200, 0.45);
}

.btn-toolbar[aria-pressed="true"] {
  background: rgba(124, 232, 200, 0.2);
  border-color: rgba(124, 232, 200, 0.55);
  color: var(--accent-strong);
}

/* Collapsible Side Panel (Desktop) */
.control-panel {
  flex: 0 0 376px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 18px 18px;
  background: var(--bg-panel);
  border-left: 1px solid var(--border-subtle);
  backdrop-filter: blur(14px);
  overflow-y: auto;
  z-index: 3;
  transition: flex-basis 0.28s ease, width 0.28s ease, opacity 0.22s ease, padding 0.28s ease;
}

.app-shell.is-panel-collapsed .control-panel,
.app-shell.is-focus-mode .control-panel {
  flex: 0 0 0px;
  width: 0;
  padding: 0;
  border: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.app-shell.is-focus-mode #panel-toggle-btn {
  display: none;
}

.panel-header {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.panel-header h2 {
  margin: 0;
  font-size: 1.32rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  color: var(--text-primary);
}

.step-badge {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 9px;
  border-radius: 999px;
  background: rgba(124, 232, 200, 0.14);
  color: var(--accent-strong);
  border: 1px solid rgba(124, 232, 200, 0.3);
}

.subtitle {
  margin: 0;
  font-size: 0.84rem;
  color: var(--text-secondary);
}

.section-heading {
  margin: 0 0 6px;
  font-size: 0.76rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

/* Playback & Progress */
.playback-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.button-row {
  display: grid;
  grid-template-columns: 1.2fr 0.9fr 1fr;
  gap: 8px;
}

.progress-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border-radius: var(--radius-md);
  background: rgba(5, 17, 25, 0.6);
  border: 1px solid rgba(128, 214, 194, 0.14);
}

.progress-track {
  width: 100%;
  height: 7px;
  border-radius: 999px;
  background: rgba(140, 212, 198, 0.18);
  overflow: hidden;
}

.progress-fill {
  width: 0%;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #5cc7ab, var(--accent-strong));
  transition: width 0.08s linear;
}

.progress-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.time-readout {
  font-variant-numeric: tabular-nums;
  font-size: 0.84rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.sleep-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.sleep-label {
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.sleep-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.select-sleep {
  width: auto;
  min-width: 104px;
}

.sleep-badge[hidden] {
  display: none;
}

/* Buttons (All >= 44px touch targets) */
.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  min-height: 44px;
  padding: 9px 14px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.18s ease, border-color 0.18s ease, transform 0.12s ease, opacity 0.18s ease;
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border-color: var(--border-subtle);
}

.btn-secondary:hover:not(:disabled) {
  background: rgba(24, 62, 76, 0.92);
  border-color: rgba(124, 232, 200, 0.4);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-secondary);
  border-color: rgba(255, 255, 255, 0.14);
}

.btn-ghost:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.12);
  color: var(--text-primary);
}

.btn-compact {
  flex: 0 0 auto;
  padding: 9px 14px;
  white-space: nowrap;
}

.btn-pill {
  min-height: 44px;
  min-width: 56px;
  padding: 6px 12px;
  border-radius: 9px;
  font-size: 0.82rem;
}

.btn-pill.is-active {
  background: rgba(124, 232, 200, 0.2);
  border-color: rgba(124, 232, 200, 0.5);
  color: var(--accent-strong);
}

.btn-pill.is-muted {
  background: rgba(235, 190, 120, 0.18);
  border-color: rgba(235, 190, 120, 0.48);
  color: #f3d499;
}

/* Presets */
.preset-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.btn-preset {
  min-height: 44px;
  padding: 8px 10px;
  font-size: 0.84rem;
}

.btn-preset.is-active {
  background: rgba(124, 232, 200, 0.2);
  border-color: rgba(124, 232, 200, 0.52);
  color: var(--accent-strong);
}

/* Collapsible Panels */
.panel-group {
  border: 1px solid rgba(128, 214, 194, 0.16);
  border-radius: var(--radius-md);
  background: rgba(6, 20, 28, 0.55);
}

.group-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 44px;
  padding: 10px 14px;
  font-size: 0.82rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.group-summary::-webkit-details-marker {
  display: none;
}

.group-summary::after {
  content: "+";
  font-size: 1.1rem;
  font-weight: 500;
  color: var(--accent);
}

.panel-group[open] > .group-summary::after {
  content: "−";
}

.group-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 6px 12px 14px;
  border-top: 1px solid rgba(128, 214, 194, 0.12);
}

/* How It Works */
.how-body {
  gap: 9px;
}

.how-item {
  margin: 0;
  font-size: 0.83rem;
  color: var(--text-secondary);
  line-height: 1.45;
}

.how-item strong {
  color: var(--accent-strong);
}

.how-item code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.78rem;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
}

/* Sliders & Inputs */
.control-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.inline-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

label,
.label-text {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-primary);
}

.helper-text {
  margin: 0;
  font-size: 0.76rem;
  line-height: 1.34;
  color: var(--text-muted);
}

.value-badge {
  font-variant-numeric: tabular-nums;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent-strong);
  background: rgba(124, 232, 200, 0.12);
  border: 1px solid rgba(124, 232, 200, 0.24);
  padding: 3px 8px;
  border-radius: 6px;
  min-width: 52px;
  text-align: center;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 44px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 999px;
  background: rgba(140, 212, 198, 0.24);
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  margin-top: -8px;
  background: var(--accent);
  border: 2px solid #052024;
  box-shadow: 0 0 8px rgba(124, 232, 200, 0.55);
  transition: transform 0.15s ease, background-color 0.15s ease;
}

input[type="range"]:hover::-webkit-slider-thumb {
  background: var(--accent-strong);
  transform: scale(1.08);
}

input[type="range"]::-moz-range-track {
  height: 6px;
  border-radius: 999px;
  background: rgba(140, 212, 198, 0.24);
}

input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid #052024;
  box-shadow: 0 0 8px rgba(124, 232, 200, 0.55);
}

.seed-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

input[type="number"],
.select-input {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: rgba(4, 15, 22, 0.84);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.88rem;
  font-variant-numeric: tabular-nums;
}

.seed-row input[type="number"] {
  flex: 1 1 auto;
}

.segmented-group {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-top: 2px;
}

.segmented-group-3 {
  grid-template-columns: repeat(3, 1fr);
}

.btn-seg {
  min-height: 44px;
  padding: 6px 4px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  background: rgba(16, 44, 56, 0.58);
  color: var(--text-secondary);
  border-color: rgba(128, 214, 194, 0.18);
}

.btn-seg:hover:not(:disabled) {
  background: rgba(24, 62, 76, 0.88);
  color: var(--text-primary);
}

.btn-seg.is-active {
  background: rgba(124, 232, 200, 0.22);
  border-color: rgba(124, 232, 200, 0.58);
  color: var(--accent-strong);
}

.layers-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 2px;
}

.layer-card {
