/* Mobile / Tablet Bottom Sheet */
@media (max-width: 899px) {
  .app-shell {
    flex-direction: column;
    height: 100dvh;
    overflow: hidden;
  }

  .garden-stage {
    flex: 1 1 52%;
    min-height: 240px;
  }

  .app-shell.is-panel-collapsed .garden-stage,
  .app-shell.is-focus-mode .garden-stage {
    flex: 1 1 100%;
    height: 100dvh;
  }

  .control-panel {
    flex: 0 0 48dvh;
    width: 100%;
    border-left: none;
    border-top: 1px solid rgba(128, 214, 194, 0.25);
    border-radius: 20px 20px 0 0;
    box-shadow: 0 -10px 30px rgba(0, 0, 0, 0.45);
    padding: 10px 14px 24px;
    overflow-y: auto;
    position: relative;
  }

  .control-panel::before {
    content: "";
    display: block;
    align-self: center;
    width: 40px;
    height: 4px;
    border-radius: 999px;
    background: rgba(168, 202, 196, 0.35);
    flex-shrink: 0;
    margin-bottom: 2px;
  }

  .app-shell.is-panel-collapsed .control-panel,
  .app-shell.is-focus-mode .control-panel {
    flex: 0 0 0px;
    height: 0;
    width: 100%;
    padding: 0;
    border: 0;
  }

  .stage-toolbar {
    top: 10px;
    right: 10px;
  }

  .stage-overlay-left {
    top: 10px;
    left: 10px;
  }

  .live-readout {
    display: grid;
    grid-template-columns: repeat(2, auto);
    gap: 5px 12px;
    padding: 6px 10px;
  }

  .shortcuts-hint {
    display: none;
  }
}

/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

