args.Content:
:root {
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  --bg-deep: #041019;
  --bg-mid: #09222e;
  --bg-surface: rgba(7, 23, 32, 0.84);
  --bg-surface-strong: rgba(7, 23, 32, 0.94);
  --bg-elevated: rgba(16, 44, 56, 0.78);
  --border-subtle: rgba(136, 218, 198, 0.2);
  --border-focus: #8cf2d3;

  --text-primary: #eaf7f4;
  --text-secondary: #b4d4ce;
  --text-muted: #8fb8b0;

  --accent: #7ce8c8;
  --accent-strong: #a6fae0;
  --accent-text: #041b17;

  --warn-bg: rgba(66, 42, 18, 0.72);
  --warn-border: rgba(242, 196, 120, 0.5);
  --warn-text: #f7deb0;

  --radius-panel: 16px;
  --radius-control: 10px;
  --radius-pill: 999px;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: linear-gradient(160deg, var(--bg-deep) 0%, var(--bg-mid) 58%, #0e2e39 100%);
  color: var(--text-primary);
  font-family: var(--font-sans);
  line-height: 1.44;
  -webkit-font-smoothing: antialiased;
}

button,
input,
select,
code,
kbd {
  font-family: var(--font-sans);
}

/* Welcome Screen */
.welcome-overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  background: radial-gradient(circle at 50% 40%, rgba(9, 34, 46, 0.72), rgba(3, 12, 18, 0.92));
  backdrop-filter: blur(10px);
}

.welcome-overlay[hidden] {
  display: none;
}

.welcome-card {
  width: 100%;
  max-width: 440px;
  padding: 28px 24px;
  border-radius: var(--radius-panel);
  background: var(--bg-surface-strong);
  border: 1px solid rgba(136, 218, 198, 0.28);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-3);
}

.welcome-kicker {
  margin: 0;
  font-size: 0.75rem;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
}

.welcome-card h1 {
  margin: 0;
  font-size: 1.95rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.welcome-desc {
  margin: 0;
  font-size: 0.95rem;
  color: var(--text-secondary);
  max-width: 36ch;
}

.welcome-highlights {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-2);
  margin: var(--space-1) 0;
}

.welcome-chip {
  font-size: 0.78rem;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: var(--radius-pill);
  background: rgba(124, 232, 200, 0.12);
  border: 1px solid rgba(124, 232, 200, 0.25);
  color: var(--accent-strong);
}

.btn-welcome {
  width: 100%;
  max-width: 260px;
  min-height: 48px;
  font-size: 1rem;
}

.welcome-note {
  margin: 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* App Shell & Stage */
.app-shell {
  display: flex;
  flex-direction: row;
  height: 100dvh;
  width: 100%;
  overflow: hidden;
}

.garden-stage {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  background: var(--bg-deep);
}

#garden-canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* Top Stage Bar (flex wrap prevents overlap at 360px, 768px, 1440px) */
.stage-top-bar {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  right: var(--space-3);
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-2);
  pointer-events: none;
  z-index: 4;
  transition: opacity 0.45s ease;
}

.stage-overlay-left {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 5px 11px;
  border-radius: var(--radius-pill);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(10px);
  color: var(--text-secondary);
  font-size: 0.8rem;
  font-weight: 500;
  transition: opacity 0.45s ease;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--text-muted);
  flex-shrink: 0;
  transition: background-color 0.25s ease, box-shadow 0.25s ease;
}

.status-dot[data-state="growing"] {
  background: var(--accent);
  box-shadow: 0 0 8px rgba(124, 232, 200, 0.85);
}

.status-dot[data-state="paused"] {
  background: #ebd089;
  box-shadow: 0 0 6px rgba(235, 208, 137, 0.65);
}

.status-dot[data-state="complete"] {
  background: #a5f5be;
  box-shadow: 0 0 8px rgba(165, 245, 190, 0.75);
}

/* Subtle single-line live readout */
.live-readout {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 7px;
  padding: 4px 10px;
  border-radius: var(--radius-control);
  background: rgba(5, 19, 27, 0.52);
  border: 1px solid rgba(136, 218, 198, 0.12);
  backdrop-filter: blur(8px);
  font-size: 0.75rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  transition: opacity 0.45s ease;
}

.live-readout strong {
  font-weight: 600;
  color: var(--text-secondary);
}

.live-readout .readout-sound strong {
  color: var(--accent);
}

.stage-toolbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  pointer-events: auto;
  margin-left: auto;
  transition: opacity 0.45s ease;
}

.btn-toolbar {
  min-height: 44px;
  padding: 8px 14px;
  border-radius: var(--radius-control);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(10px);
  color: var(--text-primary);
  font-size: 0.84rem;
  font-weight: 600;
}

.btn-toolbar:hover:not(:disabled) {
  background: rgba(20, 54, 68, 0.92);
  border-color: rgba(124, 232, 200, 0.45);
}

.btn-toolbar[aria-pressed="true"],
.btn-toolbar[aria-expanded="true"] {
  background: rgba(124, 232, 200, 0.18);
  border-color: rgba(124, 232, 200, 0.5);
  color: var(--accent-strong);
}

/* Floating Essential Dock */
.essential-dock {
  position: absolute;
  left: 50%;
  bottom: var(--space-4);
  transform: translateX(-50%);
  width: calc(100% - 24px);
  max-width: 960px;
  padding: var(--space-3);
  border-radius: var(--radius-panel);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(14px);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  z-index: 4;
  transition: opacity 0.45s ease, transform 0.35s ease;
}

.dock-main-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2) var(--space-3);
}

.dock-play {
  min-width: 92px;
  flex: 0 0 auto;
}

.dock-volume {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex: 1 1 210px;
  min-width: 0;
}

.dock-label {
  font-size: 0.84rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
}

.dock-volume input[type="range"] {
  flex: 1 1 90px;
  min-width: 70px;
}

.dock-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.dock-export {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1 1 auto;
  justify-content: flex-end;
}

.select-export {
  width: auto;
  min-width: 122px;
  flex: 0 0 auto;
}

.btn-export {
  flex: 0 1 auto;
  white-space: nowrap;
}

.dock-notice {
  margin-top: 2px;
}

/* Auto-hide controls after inactivity during playback */
.app-shell.is-controls-hidden .stage-toolbar,
.app-shell.is-controls-hidden .status-pill,
.app-shell.is-controls-hidden .essential-dock {
  opacity: 0;
  pointer-events: none;
}

.app-shell.is-controls-hidden .essential-dock {
  transform: translateX(-50%) translateY(10px);
}

.app-shell.is-controls-hidden .live-readout {
  opacity: 0.45;
}

.app-shell.is-focus-mode .essential-dock {
  opacity: 0;
  pointer-events: none;
  transform: translateX(-50%) translateY(12px);
}

.app-shell.is-focus-mode #panel-toggle-btn {
  display: none;
}

/* Side Panel (Closed by Default) */
.control-panel {
  flex: 0 0 368px;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-4);
  background: var(--bg-surface-strong);
  border-left: 1px solid var(--border-subtle);
  backdrop-filter: blur(16px);
  overflow-y: auto;
  overflow-x: hidden;
  z-index: 5;
  transition: flex-basis 0.28s ease, width 0.28s ease, opacity 0.22s ease, padding 0.28s ease;
}

.app-shell.is-panel-collapsed .control-panel,
.app-shell.is-focus-mode .control-panel {
  flex: 0 0 0px;
  width: 0;
  padding: 0;
  border: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.panel-header {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.panel-header h2 {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  color: var(--text-primary);
}

.subtitle {
  margin: 0;
  font-size: 0.84rem;
  color: var(--text-secondary);
}

/* Playback Extras inside Side Panel */
.playback-section {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.button-row-2 {
  display: grid;
  grid-template-columns: 0.9fr 1fr 1.1fr;
  gap: var(--space-2);
}

.progress-block {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-3);
  border-radius: var(--radius-control);
  background: rgba(5, 17, 25, 0.62);
  border: 1px solid rgba(136, 218, 198, 0.14);
}

.progress-track {
  width: 100%;
  height: 7px;
  border-radius: var(--radius-pill);
  background: rgba(140, 212, 198, 0.18);
  overflow: hidden;
}

.progress-fill {
  width: 0%;
  height: 100%;
  border-radius: var(--radius-pill);
  background: linear-gradient(90deg, #5cc7ab, var(--accent-strong));
  transition: width 0.08s linear;
}

.progress-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.time-readout {
  font-variant-numeric: tabular-nums;
  font-size: 0.84rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.sleep-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.sleep-label {
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.sleep-controls {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.select-sleep {
  width: auto;
  min-width: 104px;
}

.sleep-badge[hidden] {
  display: none;
}

/* Unified Button Styles (All >= 44px touch targets) */
.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: var(--radius-control);
  min-height: 44px;
  padding: 9px 14px;
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.18s ease, border-color 0.18s ease, transform 0.12s ease, opacity 0.18s ease;
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border-color: var(--border-subtle);
}

.btn-secondary:hover:not(:disabled) {
  background: rgba(24, 62, 76, 0.92);
  border-color: rgba(124, 232, 200, 0.42);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-secondary);
  border-color: rgba(255, 255, 255, 0.14);
}

.btn-ghost:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.12);
  color: var(--text-primary);
}

.btn-compact {
  flex: 0 0 auto;
  padding: 9px 14px;
  white-space: nowrap;
}

.btn-pill {
  min-height: 44px;
  min-width: 56px;
  padding: 6px 12px;
  border-radius: var(--radius-control);
  font-size: 0.82rem;
}

.btn-pill.is-active,
.btn-preset.is-active,
.btn-seg.is-active {
  background: rgba(124, 232, 200, 0.22);
  border-color: rgba(124, 232, 200, 0.56);
  color: var(--accent-strong);
}

.btn-pill.is-muted {
  background: var(--warn-bg);
  border-color: var(--warn-border);
  color: var(--warn-text);
}

.btn-preset {
  min-height: 44px;
  padding: 8px 12px;
  font-size: 0.84rem;
}

/* Collapsible Sections */
.panel-group {
  border: 1px solid rgba(136, 218, 198, 0.16);
  border-radius: var(--radius-control);
  background: rgba(6, 20, 28, 0.55);
}

.group-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 44px;
  padding: 10px 14px;
  font-size: 0.82rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.group-summary::-webkit-details-marker {
  display: none;
}

.group-summary::after {
  content: "+";
  font-size: 1.1rem;
  font-weight: 500;
  color: var(--accent);
}

.panel-group[open] > .group-summary::after {
  content: "−";
}

.group-body {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: 8px 12px 14px;
  border-top: 1px solid rgba(136, 218, 198, 0.12);
}

.how-body {
  gap: 9px;
}

.how-item {
  margin: 0;
  font-size: 0.83rem;
  color: var(--text-secondary);
  line-height: 1.45;
}

.how-item strong {
  color: var(--accent-strong);
}

.how-item code {
  font-size: 0.8rem;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
}

/* Sliders & Inputs */
.control-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.inline-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

label,
.label-text {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-primary);
}

.helper-text {
  margin: 0;
  font-size: 0.76rem;
  line-height: 1.34;
  color: var(--text-muted);
}

.value-badge {
  font-variant-numeric: tabular-nums;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent-strong);
  background: rgba(124, 232, 200, 0.12);
  border: 1px solid rgba(124, 232, 200, 0.24);
  padding: 3px 8px;
  border-radius: 6px;
  min-width: 50px;
  text-align: center;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 44px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: var(--radius-pill);
  background: rgba(140, 212, 198, 0.24);
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  margin-top: -8px;
  background: var(--accent);
  border: 2px solid #052024;
