import fs from 'node:fs';
import { generateFractalTree, getTreeBounds } from './js/tree.js';
import { renderCompositionWav } from './js/audio-export.js';

// Minimal DOM & Web Audio harness to boot js/main.js and exercise every button + WAV download
const html = fs.readFileSync('index.html', 'utf8');
const elements = new Map();
function makeEl(id, tag = 'div', type = '') {
  const attrs = new Map();
  const classes = new Set();
  if (id === 'app-shell') classes.add('is-panel-collapsed');
  const listeners = new Map();
  const el = {
    id, tagName: tag.toUpperCase(), type,
    value: '', textContent: '', hidden: false, disabled: false,
    title: '', style: {}, dataset: {},
    classList: {
      add: (c) => classes.add(c),
      remove: (c) => classes.delete(c),
      toggle: (c, f) => f === undefined ? (classes.has(c) ? (classes.delete(c), false) : (classes.add(c), true)) : (f ? (classes.add(c), true) : (classes.delete(c), false)),
      contains: (c) => classes.has(c),
    },
    setAttribute: (k, v) => attrs.set(k, String(v)),
    getAttribute: (k) => attrs.get(k),
    addEventListener: (ev, fn) => {
      if (!listeners.has(ev)) listeners.set(ev, []);
      listeners.get(ev).push(fn);
    },
    dispatch: async (ev) => {
      for (const fn of (listeners.get(ev) || [])) await fn({ target: el, preventDefault() {} });
    },
    click: async () => { await el.dispatch('click'); },
    focus: () => {},
    getContext: () => ({
      setTransform() {}, createLinearGradient: () => ({ addColorStop() {} }),
      createRadialGradient: () => ({ addColorStop() {} }),
      fillRect() {}, save() {}, restore() {}, beginPath() {}, moveTo() {}, lineTo() {},
      quadraticCurveTo() {}, closePath() {}, fill() {}, stroke() {}, arc() {},
      ellipse() {}, translate() {}, rotate() {}, drawImage() {},
    }),
    parentElement: { getBoundingClientRect: () => ({ width: 1200, height: 800 }) },
  };
  return el;
}

// Parse IDs and preset/reverb attributes from index.html
for (const m of html.matchAll(/<([a-z0-9]+)[^>]*\bid=\"([^\"]+)\"[^>]*>/gi)) {
  const tag = m[1].toLowerCase();
  const id = m[2];
  const full = m[0];
  const el = makeEl(id, tag, (full.match(/type=\"([^\"]+)\"/) || [])[1] || '');
  const valM = full.match(/value=\"([^\"]+)\"/);
  if (valM) el.value = valM[1];
  if (id === 'export-length-select') el.value = 'full';
  if (id === 'scale-select') el.value = 'c-major';
  if (id === 'sleep-timer-select') el.value = '0';
  if (id === 'export-status' || id === 'export-progress-wrap' || id === 'sleep-countdown') el.hidden = true;
  elements.set(id, el);
}
const presets = ['calm-rain', 'moonlit-night', 'deep-forest'].map((p) => {
  const b = makeEl('preset-' + p, 'button', 'button'); b.dataset.preset = p; return b;
});
const revPresets = ['small-garden', 'forest', 'open-sky'].map((r) => {
  const b = makeEl('rev-' + r, 'button', 'button'); b.dataset.reverbPreset = r; return b;
});

const docListeners = new Map();
const winListeners = new Map();
let downloadedFile = null;

class FakeParam { constructor(v=0){this.value=v;} setValueAtTime(v){this.value=v;} linearRampToValueAtTime(v){this.value=v;} setTargetAtTime(v){this.value=v;} cancelScheduledValues(){} }
class FakeNode { connect(){return this;} disconnect(){} }
class FakeGain extends FakeNode { constructor(){super(); this.gain=new FakeParam(1);} }
class FakeDelay extends FakeNode { constructor(){super(); this.delayTime=new FakeParam(0);} }
class FakePanner extends FakeNode { constructor(){super(); this.pan=new FakeParam(0);} }
class FakeComp extends FakeNode { constructor(){super(); this.threshold=new FakeParam();this.knee=new FakeParam();this.ratio=new FakeParam();this.attack=new FakeParam();this.release=new FakeParam();} }
class FakeConv extends FakeNode {}
class FakeFilter extends FakeNode { constructor(){super(); this.frequency=new FakeParam(350);this.Q=new FakeParam(1);} }
class FakeAnalyser extends FakeNode { constructor(){super(); this.fftSize=256;} getByteTimeDomainData(a){a.fill(140);} }
class FakeSource extends FakeNode { constructor(){super(); this.playbackRate=new FakeParam(1);} start(){} stop(){} }
class FakeOsc extends FakeNode { constructor(){super(); this.frequency=new FakeParam(440);} start(){} stop(){} }
class FakeBuffer { constructor(c,l,sr){this.numberOfChannels=c;this.length=l;this.sampleRate=sr;this.duration=l/sr;this._d=Array.from({length:c},()=>new Float32Array(l).fill(0.15));} getChannelData(c){return this._d[c];} }
class FakeOfflineCtx {
  constructor(ch=2,len=44100,sr=44100){this.numberOfChannels=ch;this.length=len;this.sampleRate=sr;this.currentTime=0;this.destination={};}
  createGain(){return new FakeGain();} createDelay(){return new FakeDelay();} createStereoPanner(){return new FakePanner();}
  createDynamicsCompressor(){return new FakeComp();} createConvolver(){return new FakeConv();} createBiquadFilter(){return new FakeFilter();}
  createBufferSource(){return new FakeSource();} createOscillator(){return new FakeOsc();} createBuffer(c,l,sr){return new FakeBuffer(c,l,sr);}
  async decodeAudioData(){return new FakeBuffer(2,44100*6,44100);}
  async startRendering(){ const b=new FakeBuffer(2,this.length,this.sampleRate); for(let i=0;i<this.length;i++){b.getChannelData(0)[i]=Math.sin(i*0.03)*0.7; b.getChannelData(1)[i]=Math.sin(i*0.03)*0.7;} return b; }
}
class FakeAudioCtx extends FakeOfflineCtx {
  constructor(){super(); this.state='running';}
  async resume(){this.state='running';} async suspend(){this.state='suspended';}
  createAnalyser(){return new FakeAnalyser();}
}

globalThis.document = {
  getElementById: (id) => elements.get(id) || null,
  querySelectorAll: (sel) => sel === '[data-preset]' ? presets : sel === '[data-reverb-preset]' ? revPresets : [],
  createElement: (tag) => {
    const e = makeEl('', tag);
    e.click = () => { if (e.download) downloadedFile = e.download; };
