  },
  body: { appendChild(){}, removeChild(){} },
  documentElement: { requestFullscreen: async () => {} },
  fullscreenEnabled: true,
  fullscreenElement: null,
  hidden: false,
  addEventListener: (ev, fn) => { if(!docListeners.has(ev)) docListeners.set(ev, []); docListeners.get(ev).push(fn); },
};
globalThis.window = {
  AudioContext: FakeAudioCtx,
  OfflineAudioContext: FakeOfflineCtx,
  devicePixelRatio: 1,
  matchMedia: () => ({ matches: false, addEventListener(){} }),
  addEventListener: (ev, fn) => { if(!winListeners.has(ev)) winListeners.set(ev, []); winListeners.get(ev).push(fn); },
  removeEventListener: () => {},
};
globalThis.requestAnimationFrame = () => 1;
globalThis.cancelAnimationFrame = () => {};
globalThis.URL = { createObjectURL: () => 'blob:test', revokeObjectURL: () => {} };
globalThis.fetch = async () => ({ ok: true, status: 200, arrayBuffer: async () => new ArrayBuffer(8) });

await import('./js/main.js');

// Exercise every button & WAV download!
const shell = elements.get('app-shell');
if (!shell.classList.contains('is-panel-collapsed')) throw new Error('Panel must start closed by default');
await elements.get('enter-garden-btn').click();
if (!elements.get('welcome-overlay').hidden) throw new Error('Welcome did not hide');

